```typescript
// Domain Layer - Interfaces and Types

/**
 * Domain Event interface
 * Represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly id: string;
  readonly occurredOn: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  publish(event: IDomainEvent): Promise<void>;
}

// Application Layer - Use Cases

import { Result, Ok, Err } from '../common/Result';

/**
 * Domain Error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EventPublishingError';
  }
}

/**
 * Use case that demonstrates publishing a domain event
 */
export class PublishDomainEventUseCase {
  constructor(private readonly eventPublisher: IEventPublisher) {}

  async execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      await this.eventPublisher.publish(event);
      return Ok(undefined);
    } catch (error) {
      return Err(new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`));
    }
  }
}

// Infrastructure Layer - Test Double Implementation

/**
 * In-memory test double implementation of IEventPublisher
 * Used for testing without external dependencies
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private readonly events: IDomainEvent[] = [];
  private readonly subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event
   * @param event The domain event to publish
   */
  async publish(event: IDomainEvent): Promise<void> {
    this.events.push(event);

    // Notify all subscribers
    this.subscribers.forEach(subscriber => subscriber(event));
  }

  /**
   * Subscribe to events for testing purposes
   * @param subscriber Function to be called when an event is published
   */
  subscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers.push(subscriber);
  }

  /**
   * Get all published events (for testing assertions)
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clear all published events (for test isolation)
   */
  clear(): void {
    this.events.length = 0;
  }
}
```

This implementation follows Clean Architecture principles:

1. **Domain Layer**:
   - Defines `IDomainEvent` interface and `IEventPublisher` port
   - No dependencies on external frameworks or infrastructure

2. **Application Layer**:
   - Contains use case that depends on the domain port
   - Uses `Result<T, E>` pattern for error handling
   - Domain errors are properly typed

3. **Infrastructure Layer**:
   - Implements the `InMemoryEventPublisher` test double
   - Provides testing utilities like `subscribe()` and `getPublishedEvents()`
   - Maintains the dependency rule (no external dependencies in domain/application layers)

The test double allows for:
- Verifying events are published correctly
- Testing event handling logic
- Isolated unit testing without external dependencies
- Mocking behavior for different test scenarios

Please write isolated unit tests (vitest) for the deposit settlement below. Cover the late-fee math and every error branch.

```typescript
import { Result } from '../shared/Result';

export interface Rental {
  id: string;
  depositCents: number;
  dueBack: Date;
  settled: boolean;
}

export interface RentalRepository {
  get(id: string): Promise<Rental | null>;
  save(rental: Rental): Promise<void>;
}

export interface DepositRefunder {
  refund(rentalId: string, cents: number): Promise<void>;
}

export type DepositError =
  | { kind: 'RentalNotFound' }
  | { kind: 'AlreadySettled' }
  | { kind: 'DeductionsExceedDeposit'; deductionsCents: number };

const LATE_FEE_PER_DAY_CENTS = 1_500;
const DAY_MS = 86_400_000;

export class SettleDeposit {
  constructor(
    private readonly rentals: RentalRepository,
    private readonly refunder: DepositRefunder,
    private readonly now: () => Date,
  ) {}

  async execute(rentalId: string, damageCents: number): Promise<Result<number, DepositError>> {
    const rental = await this.rentals.get(rentalId);
    if (!rental) return Result.fail({ kind: 'RentalNotFound' });
    if (rental.settled) return Result.fail({ kind: 'AlreadySettled' });
    const lateDays = Math.max(0, Math.ceil((this.now().getTime() - rental.dueBack.getTime()) / DAY_MS));
    const deductionsCents = damageCents + lateDays * LATE_FEE_PER_DAY_CENTS;
    if (deductionsCents > rental.depositCents) {
      return Result.fail({ kind: 'DeductionsExceedDeposit', deductionsCents });
    }
    const refundCents = rental.depositCents - deductionsCents;
    await this.refunder.refund(rental.id, refundCents);
    await this.rentals.save({ ...rental, settled: true });
    return Result.ok(refundCents);
  }
}
```

The clock is fixed and the due date is moved relative to it, which makes the `Math.ceil` rounding easy to pin down: one hour late already counts as a full day. The refunder is a spy; the repository is a map-backed fake.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { SettleDeposit, DepositRefunder, Rental, RentalRepository } from './SettleDeposit';

class InMemoryRentals implements RentalRepository {
  readonly rentals = new Map<string, Rental>();
  async get(id: string): Promise<Rental | null> {
    return this.rentals.get(id) ?? null;
  }
  async save(rental: Rental): Promise<void> {
    this.rentals.set(rental.id, rental);
  }
}

const NOW = new Date('2024-08-01T12:00:00Z');
const HOUR = 3_600_000;
const rental = (overrides: Partial<Rental> = {}): Rental => ({
  id: 'r-1', depositCents: 20_000, dueBack: NOW, settled: false, ...overrides,
});

describe('SettleDeposit', () => {
  let rentals: InMemoryRentals;
  let refund: ReturnType<typeof vi.fn<DepositRefunder['refund']>>;
  let useCase: SettleDeposit;

  beforeEach(() => {
    rentals = new InMemoryRentals();
    refund = vi.fn<DepositRefunder['refund']>().mockResolvedValue(undefined);
    useCase = new SettleDeposit(rentals, { refund }, () => NOW);
  });

  it.each([
    { label: 'returned early', dueOffsetHours: 5, damage: 0, expected: 20_000 },
    { label: 'on time with damage', dueOffsetHours: 0, damage: 4_000, expected: 16_000 },
    { label: '1 hour late', dueOffsetHours: -1, damage: 0, expected: 18_500 },
    { label: '49 hours late', dueOffsetHours: -49, damage: 1_000, expected: 14_500 },
  ])('refunds $expected cents when $label', async ({ dueOffsetHours, damage, expected }) => {
    // Arrange
    rentals.rentals.set('r-1', rental({ dueBack: new Date(NOW.getTime() + dueOffsetHours * HOUR) }));

    // Act
    const result = await useCase.execute('r-1', damage);

    // Assert
    expect(result.success).toBe(true);
    if (!result.success) return;
    expect(result.data).toBe(expected);
    expect(refund).toHaveBeenCalledWith('r-1', expected);
    expect(rentals.rentals.get('r-1')?.settled).toBe(true);
  });

  it('fails with RentalNotFound for an unknown rental', async () => {
    // Arrange: no rentals

    // Act
    const result = await useCase.execute('r-404', 0);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('RentalNotFound');
  });

  it('fails with AlreadySettled and refunds nothing', async () => {
    // Arrange
    rentals.rentals.set('r-1', rental({ settled: true }));

    // Act
    const result = await useCase.execute('r-1', 0);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AlreadySettled');
    expect(refund).not.toHaveBeenCalled();
  });

  it('fails when damage plus late fees exceed the deposit', async () => {
    // Arrange: 2 days late (3,000) + 18,000 damage = 21,000 > 20,000
    rentals.rentals.set('r-1', rental({ dueBack: new Date(NOW.getTime() - 48 * HOUR) }));

    // Act
    const result = await useCase.execute('r-1', 18_000);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'DeductionsExceedDeposit', deductionsCents: 21_000 });
    expect(rentals.rentals.get('r-1')?.settled).toBe(false);
  });
});
