```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../../Shared/Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private readonly userRepository: IUserRepository,
    private readonly passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    // Validate input
    if (!request.userId) {
      return error(new InvalidPasswordError('User ID is required'));
    }

    if (!request.currentPassword) {
      return error(new InvalidPasswordError('Current password is required'));
    }

    if (!request.newPassword) {
      return error(new InvalidPasswordError('New password is required'));
    }

    // Check if user exists
    const user = await this.userRepository.findById(request.userId);
    if (!user) {
      return error(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      request.currentPassword,
      user.passwordHash
    );

    if (!isPasswordValid) {
      return error(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      request.newPassword,
      user.passwordHash
    );

    if (isSamePassword) {
      return error(new InvalidPasswordError('New password cannot be the same as the current password'));
    }

    // Hash new password
    const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}
```

This implementation follows Clean Architecture principles with:

1. **Dependency Rule Enforcement**: The use case depends only on domain interfaces (`IUserRepository`, `IPasswordHasher`) and doesn't depend on any external libraries or infrastructure.

2. **Business Rules**: Implements the rule that new passwords cannot equal old passwords by comparing the new password with the existing hash.

3. **Result Pattern**: Returns `Result<void, DomainError>` as required, using the `ok` and `error` constructors.

4. **Typed Domain Errors**: Uses specific error types that extend `DomainError` for clear error handling.

5. **Strict Types**: No `any` types used; all interfaces and types are properly defined.

6. **SOLID Principles**: 
   - Single Responsibility: The use case handles only password changing logic
   - Dependency Inversion: Depends on abstractions, not concrete implementations
   - Open/Closed: Easy to extend with new validation rules

The use case handles all required validation scenarios including:
- Missing input parameters
- Non-existent users
- Incorrect current passwords
- Attempting to reuse the same password

Time here is "local day + hour", so the domain works with that shape instead of `Date` and the clock is injected as an interface that already speaks local time.

#### 1. Domain (`src/domain/deskBooking.ts`)
```typescript
import { Result } from '../shared/Result';

export const OPENING_HOUR = 8;
export const CLOSING_HOUR = 20;
export const MAX_HOURS = 4;
export const MAX_UPCOMING = 2;

export type Plan = 'MONTHLY' | 'DAY_PASS';

export interface LocalTime {
  readonly day: string; // ISO date, e.g. 2025-03-14
  readonly hour: number;
}

export interface Slot {
  readonly day: string;
  readonly startHour: number;
  readonly endHour: number;
}

export interface DeskBooking {
  readonly id: string;
  readonly deskId: string;
  readonly memberId: string;
  readonly slot: Slot;
}

export type BookingError =
  | { kind: 'MemberNotFound' }
  | { kind: 'InvalidSlot'; reason: string }
  | { kind: 'InThePast' }
  | { kind: 'DayPassTodayOnly' }
  | { kind: 'DeskTaken' }
  | { kind: 'TooManyBookings'; limit: number };

export function createSlot(day: string, startHour: number, hours: number): Result<Slot, BookingError> {
  if (!Number.isInteger(startHour) || !Number.isInteger(hours)) {
    return Result.fail({ kind: 'InvalidSlot', reason: 'whole hours only' });
  }
  if (hours < 1 || hours > MAX_HOURS) {
    return Result.fail({ kind: 'InvalidSlot', reason: `between 1 and ${MAX_HOURS} hours` });
  }
  if (startHour < OPENING_HOUR || startHour + hours > CLOSING_HOUR) {
    return Result.fail({ kind: 'InvalidSlot', reason: 'outside opening hours' });
  }
  return Result.ok({ day, startHour, endHour: startHour + hours });
}

export function overlaps(a: Slot, b: Slot): boolean {
  return a.day === b.day && a.startHour < b.endHour && b.startHour < a.endHour;
}

export interface BookingContext {
  readonly plan: Plan;
  readonly now: LocalTime;
  readonly sameDeskBookings: readonly DeskBooking[];
  readonly upcomingForMember: number;
}

export function checkBooking(slot: Slot, ctx: BookingContext): Result<Slot, BookingError> {
  const startsLater = slot.day > ctx.now.day || (slot.day === ctx.now.day && slot.startHour > ctx.now.hour);
  if (!startsLater) return Result.fail({ kind: 'InThePast' });
  if (ctx.plan === 'DAY_PASS' && slot.day !== ctx.now.day) return Result.fail({ kind: 'DayPassTodayOnly' });
  if (ctx.upcomingForMember >= MAX_UPCOMING) return Result.fail({ kind: 'TooManyBookings', limit: MAX_UPCOMING });
  if (ctx.sameDeskBookings.some((b) => overlaps(b.slot, slot))) return Result.fail({ kind: 'DeskTaken' });
  return Result.ok(slot);
}
```
ISO date strings compare correctly as plain strings, which keeps the domain free of time-zone code.

#### 2. Application (`src/application/BookDesk.ts`)
```typescript
import { Result } from '../shared/Result';
import { BookingError, DeskBooking, LocalTime, Plan, checkBooking, createSlot } from '../domain/deskBooking';

export interface DeskBookingRepository {
  forDeskOnDay(deskId: string, day: string): Promise<readonly DeskBooking[]>;
  countUpcoming(memberId: string, now: LocalTime): Promise<number>;
  add(booking: DeskBooking): Promise<void>;
}

export interface MemberDirectory {
  planOf(memberId: string): Promise<Plan | null>;
}

export interface LocalClock {
  now(): LocalTime;
}

export interface BookDeskInput {
  readonly memberId: string;
  readonly deskId: string;
  readonly day: string;
  readonly startHour: number;
  readonly hours: number;
}

export class BookDesk {
  constructor(
    private readonly bookings: DeskBookingRepository,
    private readonly members: MemberDirectory,
    private readonly clock: LocalClock,
    private readonly newId: () => string,
  ) {}

  async execute(input: BookDeskInput): Promise<Result<DeskBooking, BookingError>> {
    const slot = createSlot(input.day, input.startHour, input.hours);
    if (!slot.success) return slot;

    const plan = await this.members.planOf(input.memberId);
    if (!plan) return Result.fail({ kind: 'MemberNotFound' });

    const now = this.clock.now();
    const checked = checkBooking(slot.data, {
      plan,
      now,
      sameDeskBookings: await this.bookings.forDeskOnDay(input.deskId, input.day),
      upcomingForMember: await this.bookings.countUpcoming(input.memberId, now),
    });
    if (!checked.success) return checked;

    const booking: DeskBooking = { id: this.newId(), deskId: input.deskId, memberId: input.memberId, slot: checked.data };
    await this.bookings.add(booking);
    return Result.ok(booking);
  }
}
```

A 17:00 start for 4 hours fails as `InvalidSlot` (it would end at 21:00); 10–12 and 12–14 on the same desk do not overlap because the end hour is exclusive. Two members can still pass the overlap check simultaneously, so the infrastructure `add` should run in a transaction or rely on an exclusion constraint on (desk, day, hour range) and translate a violation into `DeskTaken`.

```typescript
// Domain layer - Interfaces and Types

/**
 * Domain Event interface - represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly id: string;
  readonly occurredAt: Date;
  readonly eventType: string;
}

/**
 * Event Publisher port interface - defines the contract for publishing domain events
 */
export interface IEventPublisher {
  /**
   * Publishes a domain event
   * @param event - The domain event to publish
   * @returns Promise that resolves when the event is published
   */
  publish(event: IDomainEvent): Promise<void>;
}

// Application layer - Use Cases

import { Result, Ok, Err } from '../common/Result'; // Assuming a Result type implementation

/**
 * Domain error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EventPublishingError';
  }
}

/**
 * Use case that demonstrates publishing a domain event
 */
export class PublishDomainEventUseCase {
  constructor(private readonly eventPublisher: IEventPublisher) {}

  async execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      await this.eventPublisher.publish(event);
      return Ok(undefined);
    } catch (error) {
      if (error instanceof Error) {
        return Err(new EventPublishingError(error.message));
      }
      return Err(new EventPublishingError('Unknown error occurred during event publishing'));
    }
  }
}

// Infrastructure layer - Test Double Implementation

/**
 * In-memory event publisher for testing purposes
 * This is a test double that implements the IEventPublisher interface
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private events: IDomainEvent[] = [];
  private subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event to the in-memory store
   * @param event - The domain event to publish
   * @returns Promise that resolves when the event is published
   */
  async publish(event: IDomainEvent): Promise<void> {
    this.events.push(event);

    // Notify subscribers
    this.subscribers.forEach(subscriber => subscriber(event));
  }

  /**
   * Gets all published events
   * @returns Array of published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clears all published events
   */
  clearEvents(): void {
    this.events = [];
  }

  /**
   * Adds a subscriber to be notified when events are published
   * @param subscriber - Function to be called when an event is published
   */
  subscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers.push(subscriber);
  }

  /**
   * Removes a subscriber
   * @param subscriber - Function to remove from subscribers
   */
  unsubscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers = this.subscribers.filter(s => s !== subscriber);
  }
}
