Critique this code using the Liskov Substitution Principle and SOLID, then fix it:

```typescript
class Bird {
  fly(): string { return 'flying'; }
}
class Penguin extends Bird {
  fly(): string { throw new Error('Penguins cannot fly'); }
}
function launch(birds: Bird[]) {
  return birds.map(b => b.fly());
}
```

### SOLID Critique
- **LSP (violated):** `Penguin` cannot stand in for `Bird`. `launch([new Penguin()])` throws, so callers must know the concrete subtype.
- **Root cause:** the base type promises a capability (`fly`) that not every bird has. The hierarchy models taxonomy, not behavior.
- **ISP angle:** `Bird` forces a `fly` contract on types that cannot honor it.

---

### Refactoring: split capabilities
```typescript
export interface Bird {
  readonly name: string;
}

export interface FlyingBird extends Bird {
  fly(): string;
}

export class Sparrow implements FlyingBird {
  readonly name = 'sparrow';
  fly(): string { return 'flying'; }
}

export class Penguin implements Bird {
  readonly name = 'penguin';
}

export function launch(birds: FlyingBird[]): string[] {
  return birds.map((bird) => bird.fly());
}
```

`launch` now only accepts types that can fly, so the invalid call `launch([new Penguin()])` fails at compile time instead of at runtime. Every `FlyingBird` is fully substitutable.

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  canBeCancelled(): boolean {
    return this.isActive() && !this.isExpired();
  }

  cancel(): Subscription {
    if (!this.canBeCancelled()) {
      throw new SubscriptionCannotBeCancelledError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionCannotBeCancelledError extends Error {
  constructor() {
    super('Cannot cancel an expired subscription');
    this.name = 'SubscriptionCannotBeCancelledError';
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription } from '../Entities/Subscription';
import { SubscriptionCannotBeCancelledError } from '../Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError());
      }

      if (!subscription.canBeCancelled()) {
        return error(new SubscriptionCannotBeCancelledError());
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof SubscriptionCannotBeCancelledError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

// Result type implementation
export type Result<T, E extends Error> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    isError: false,
    value
  };
}

export function error<E extends Error>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    isError: true,
    error
  };
}
```

Our order status transitions are implemented as Mongoose schema methods and a pre-save hook. Move the business rules out of the persistence model:

```typescript
const orderSchema = new Schema({
  status: { type: String, default: 'pending' },
  items: [{ sku: String, qty: Number }],
  shippedAt: Date,
  cancelReason: String,
});

orderSchema.methods.transition = function (to: string, reason?: string) {
  const allowed: Record<string, string[]> = {
    pending: ['paid', 'cancelled'],
    paid: ['shipped', 'cancelled'],
    shipped: ['delivered'],
  };
  if (!(allowed[this.status] ?? []).includes(to)) throw new Error(`Cannot go from ${this.status} to ${to}`);
  if (to === 'cancelled' && !reason) throw new Error('Cancellation needs a reason');
  this.status = to;
  if (to === 'cancelled') this.cancelReason = reason;
};

orderSchema.pre('save', function (next) {
  if (this.isModified('status') && this.status === 'shipped') this.shippedAt = new Date();
  next();
});

export const OrderModel = model('Order', orderSchema);
```

### Architectural Flaws in Original Code
1. **State machine inside the ORM:** transition rules only exist on Mongoose documents, so they cannot run without a schema.
2. **Hidden side effect in a hook:** `shippedAt` is set by `pre('save')`, far from the rule that triggers it.
3. **Stringly typed status and thrown errors** give callers no compile-time safety.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Order.ts`)
```typescript
import { Result } from '../shared/Result';

export type OrderStatus = 'pending' | 'paid' | 'shipped' | 'delivered' | 'cancelled';

export type TransitionError =
  | { kind: 'InvalidTransition'; from: OrderStatus; to: OrderStatus }
  | { kind: 'ReasonRequired' };

const ALLOWED: { readonly [S in OrderStatus]: readonly OrderStatus[] } = {
  pending: ['paid', 'cancelled'],
  paid: ['shipped', 'cancelled'],
  shipped: ['delivered'],
  delivered: [],
  cancelled: [],
};

export interface OrderLine { readonly sku: string; readonly qty: number; }

export interface OrderState {
  readonly status: OrderStatus;
  readonly shippedAt?: Date;
  readonly cancelReason?: string;
}

export class Order {
  constructor(readonly id: string, readonly lines: readonly OrderLine[], private current: OrderState) {}

  get state(): OrderState { return this.current; }

  transition(to: OrderStatus, now: Date, reason?: string): Result<OrderState, TransitionError> {
    const from = this.current.status;
    if (!ALLOWED[from].includes(to)) return Result.fail({ kind: 'InvalidTransition', from, to });
    if (to === 'cancelled' && !reason) return Result.fail({ kind: 'ReasonRequired' });

    this.current = {
      ...this.current,
      status: to,
      shippedAt: to === 'shipped' ? now : this.current.shippedAt,
      cancelReason: to === 'cancelled' ? reason : this.current.cancelReason,
    };
    return Result.ok(this.current);
  }
}
```

#### 2. Application Layer (`src/application/ChangeOrderStatus.ts`)
```typescript
import { Result } from '../shared/Result';
import { Order, OrderState, OrderStatus, TransitionError } from '../domain/Order';

export type ChangeStatusError = TransitionError | { kind: 'OrderNotFound' };

export interface OrderRepository {
  findById(id: string): Promise<Order | null>;
  save(order: Order): Promise<void>;
}

export class ChangeOrderStatus {
  constructor(private readonly orders: OrderRepository, private readonly clock: () => Date) {}

  async execute(orderId: string, to: OrderStatus, reason?: string): Promise<Result<OrderState, ChangeStatusError>> {
    const order = await this.orders.findById(orderId);
    if (!order) return Result.fail({ kind: 'OrderNotFound' });

    const changed = order.transition(to, this.clock(), reason);
    if (!changed.success) return changed;

    await this.orders.save(order);
    return changed;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/MongooseOrderRepository.ts`)
The schema becomes a plain persistence mapping with no methods or hooks.
```typescript
import { Model, Schema, Types, model } from 'mongoose';
import { Order, OrderStatus } from '../domain/Order';
import { OrderRepository } from '../application/ChangeOrderStatus';

interface OrderDoc {
  _id: Types.ObjectId;
  status: OrderStatus;
  items: { sku: string; qty: number }[];
  shippedAt?: Date;
  cancelReason?: string;
}

const orderSchema = new Schema<OrderDoc>({
  status: { type: String, default: 'pending' },
  items: [{ sku: String, qty: Number }],
  shippedAt: Date,
  cancelReason: String,
});

export const OrderModel: Model<OrderDoc> = model<OrderDoc>('Order', orderSchema);

export class MongooseOrderRepository implements OrderRepository {
  async findById(id: string): Promise<Order | null> {
    const doc = await OrderModel.findById(id).lean<OrderDoc>();
    if (!doc) return null;
    return new Order(doc._id.toString(), doc.items, {
      status: doc.status, shippedAt: doc.shippedAt, cancelReason: doc.cancelReason,
    });
  }

  async save(order: Order): Promise<void> {
    await OrderModel.updateOne({ _id: new Types.ObjectId(order.id) }, { $set: { ...order.state } });
  }
}
```

Callers now receive `{ kind: 'InvalidTransition', from: 'shipped', to: 'cancelled' }` instead of parsing an error message, and `shippedAt` is set by the same rule that ships the order.

Restructure this renewal job using Clean Architecture. Billing rules, Stripe and Sequelize are tangled together:

```typescript
cron.schedule('0 3 * * *', async () => {
  const due = await Subscription.findAll({
    where: { status: 'active', renewsAt: { [Op.lte]: new Date() } },
  });
  for (const sub of due) {
    try {
      await stripe.paymentIntents.create({
        amount: sub.priceCents, currency: 'usd', customer: sub.stripeCustomerId,
        payment_method: sub.defaultPaymentMethod, off_session: true, confirm: true,
      });
      const next = new Date(sub.renewsAt);
      next.setMonth(next.getMonth() + (sub.interval === 'yearly' ? 12 : 1));
      await sub.update({ renewsAt: next, failedAttempts: 0 });
    } catch (e) {
      const attempts = sub.failedAttempts + 1;
      await sub.update({ failedAttempts: attempts, status: attempts >= 3 ? 'past_due' : 'active' });
    }
  }
});
```

### Architectural Flaws in Original Code
1. **Renewal policy hidden in a cron callback:** the billing interval and the three-strike rule cannot be tested without Stripe and a database.
2. **Active Record models as domain:** `sub.update(...)` couples state changes to Sequelize.
3. **Exceptions as control flow:** any error, including a network outage or a bug, is counted as a failed charge and can push a customer to `past_due`.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Subscription.ts`)
```typescript
export type BillingInterval = 'monthly' | 'yearly';
export type SubscriptionStatus = 'active' | 'past_due';

export class Subscription {
  static readonly MAX_FAILED_ATTEMPTS = 3;

  constructor(
    readonly id: string,
    readonly customerRef: string,
    readonly paymentMethodRef: string,
    readonly priceCents: number,
    readonly interval: BillingInterval,
    private renewal: Date,
    private failures: number,
    private state: SubscriptionStatus,
  ) {}

  get renewsAt(): Date { return this.renewal; }
  get failedAttempts(): number { return this.failures; }
  get status(): SubscriptionStatus { return this.state; }

  renewed(): void {
    const next = new Date(this.renewal);
    next.setMonth(next.getMonth() + (this.interval === 'yearly' ? 12 : 1));
    this.renewal = next;
    this.failures = 0;
  }

  chargeFailed(): void {
    this.failures += 1;
    if (this.failures >= Subscription.MAX_FAILED_ATTEMPTS) this.state = 'past_due';
  }
}
```

#### 2. Application Layer (`src/application/RenewDueSubscriptions.ts`)
```typescript
import { Result } from '../shared/Result';
import { Subscription } from '../domain/Subscription';

export type ChargeError = { kind: 'Declined'; reason: string } | { kind: 'Unavailable' };

export interface SubscriptionRepository {
  findDue(asOf: Date): Promise<Subscription[]>;
  save(subscription: Subscription): Promise<void>;
}

export interface PaymentProcessor {
  charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>>;
}

export class RenewDueSubscriptions {
  constructor(
    private readonly subscriptions: SubscriptionRepository,
    private readonly payments: PaymentProcessor,
    private readonly now: () => Date,
  ) {}

  async execute(): Promise<{ renewed: number; failed: number; retryLater: number }> {
    let renewed = 0;
    let failed = 0;
    let retryLater = 0;
    for (const sub of await this.subscriptions.findDue(this.now())) {
      const charge = await this.payments.charge(sub.customerRef, sub.paymentMethodRef, sub.priceCents);
      if (charge.success) {
        sub.renewed();
        renewed++;
      } else if (charge.error.kind === 'Declined') {
        sub.chargeFailed();
        failed++;
      } else {
        retryLater++; // provider unavailable: leave the subscription untouched, it stays due
        continue;
      }
      await this.subscriptions.save(sub);
    }
    return { renewed, failed, retryLater };
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/StripePaymentProcessor.ts`)
```typescript
import Stripe from 'stripe';
import { Result } from '../shared/Result';
import { ChargeError, PaymentProcessor } from '../application/RenewDueSubscriptions';

function isCardDecline(error: unknown): error is { type: 'StripeCardError'; message: string } {
  return typeof error === 'object' && error !== null && (error as { type?: unknown }).type === 'StripeCardError';
}

export class StripePaymentProcessor implements PaymentProcessor {
  constructor(private readonly stripe: Stripe) {}

  async charge(customerRef: string, paymentMethodRef: string, amountCents: number): Promise<Result<void, ChargeError>> {
    try {
      await this.stripe.paymentIntents.create({
        amount: amountCents, currency: 'usd', customer: customerRef,
        payment_method: paymentMethodRef,
        off_session: true, confirm: true,
      });
      return Result.ok(undefined);
    } catch (error) {
      if (isCardDecline(error)) {
        return Result.fail({ kind: 'Declined', reason: error.message });
      }
      return Result.fail({ kind: 'Unavailable' }); // outages are not counted as declines
    }
  }
}
```
A `SequelizeSubscriptionRepository` maps rows to `Subscription` in `findDue` (`status: 'active'`, `renewsAt <= asOf`) and writes `renewsAt`, `failedAttempts` and `status` back in `save`.

#### 4. Scheduler (`src/infrastructure/jobs.ts`)
```typescript
cron.schedule('0 3 * * *', async () => {
  const { renewed, failed, retryLater } = await renewDueSubscriptions.execute();
  logger.info(`renewals: ${renewed} ok, ${failed} declined, ${retryLater} to retry`);
});
```
Like the original, one failing subscription never stops the batch. The difference is that a provider outage no longer counts towards the three-strike limit; those subscriptions are simply picked up again on the next run.

