Our appointment reminder job calls Twilio directly and catches errors by message string. Extract a port for sending text messages and write the Twilio adapter plus an in-memory one:

```typescript
import twilio from 'twilio';

const client = twilio(process.env.TWILIO_SID, process.env.TWILIO_TOKEN);

export async function sendReminders(appointments: Appointment[]) {
  for (const a of appointments) {
    try {
      const msg = await client.messages.create({
        to: a.patientPhone,
        from: process.env.TWILIO_FROM,
        body: `Reminder: ${a.clinic} tomorrow at ${a.time}. Reply STOP to opt out.`,
      });
      await db.reminders.insert({ appointmentId: a.id, sid: msg.sid, status: msg.status });
    } catch (e: any) {
      if (e.message.includes('unsubscribed')) await db.patients.markOptedOut(a.patientId);
      else console.error(e);
    }
  }
}
```

### Problems
1. **Vendor leakage:** the job knows Twilio's `sid`, `status` strings and `from` number, so switching providers means rewriting reminder logic.
2. **Errors by string matching:** `e.message.includes('unsubscribed')` breaks the day Twilio rewords the message. Twilio already returns a stable numeric `code` (21610 for an opted-out recipient).
3. **`catch (e: any)`** disables type checking for the most fragile part of the code.

---

### 1. Port (`src/application/ports/TextMessageSender.ts`)
The application owns this interface and speaks in its own terms: a recipient, a body and a typed failure.

```typescript
import { Result } from '../shared/Result';

export interface OutgoingText {
  readonly to: string; // E.164, validated before reaching the port
  readonly body: string;
}

export interface SentText {
  readonly messageId: string;
}

export type SendTextError =
  | { kind: 'RecipientOptedOut' }
  | { kind: 'InvalidRecipient' }
  | { kind: 'RateLimited'; retryAfterSeconds: number }
  | { kind: 'ProviderUnavailable'; detail: string };

export interface TextMessageSender {
  send(message: OutgoingText): Promise<Result<SentText, SendTextError>>;
}
```

There is no `from` field: the sender number is a configuration detail of the adapter, not a decision the reminder job should make.

### 2. Twilio adapter (`src/infrastructure/sms/TwilioTextSender.ts`)
```typescript
import { Twilio } from 'twilio';

interface TwilioLikeError {
  readonly code: number;
  readonly status: number;
  readonly message: string;
}

function isTwilioError(e: unknown): e is TwilioLikeError {
  return typeof e === 'object' && e !== null && typeof Reflect.get(e, 'code') === 'number';
}

function toSendTextError(e: unknown): SendTextError {
  if (!isTwilioError(e)) return { kind: 'ProviderUnavailable', detail: String(e) };
  switch (e.code) {
    case 21610: return { kind: 'RecipientOptedOut' };
    case 21211:
    case 21614: return { kind: 'InvalidRecipient' };
    case 20429: return { kind: 'RateLimited', retryAfterSeconds: 1 };
    default: return { kind: 'ProviderUnavailable', detail: `${e.code}: ${e.message}` };
  }
}

export class TwilioTextSender implements TextMessageSender {
  constructor(private readonly client: Twilio, private readonly fromNumber: string) {}

  async send(message: OutgoingText): Promise<Result<SentText, SendTextError>> {
    try {
      const sent = await this.client.messages.create({ to: message.to, from: this.fromNumber, body: message.body });
      return Result.ok({ messageId: sent.sid });
    } catch (e: unknown) {
      return Result.fail(toSendTextError(e));
    }
  }
}
```

The `try/catch` lives only here, at the boundary, and converts every vendor failure into a `SendTextError` value. Nothing above this class can see a Twilio type.

### 3. In-memory adapter for tests and local development
```typescript
export class InMemoryTextSender implements TextMessageSender {
  readonly sent: OutgoingText[] = [];
  private readonly optedOut = new Set<string>();

  optOut(phone: string): void {
    this.optedOut.add(phone);
  }

  async send(message: OutgoingText): Promise<Result<SentText, SendTextError>> {
    if (this.optedOut.has(message.to)) return Result.fail({ kind: 'RecipientOptedOut' });
    this.sent.push(message);
    return Result.ok({ messageId: `mem-${this.sent.length}` });
  }
}
```

### 4. The reminder job, now vendor-free
```typescript
export interface ReminderLog {
  record(appointmentId: string, messageId: string): Promise<void>;
  markOptedOut(patientId: string): Promise<void>;
}

export interface DueAppointment {
  readonly id: string;
  readonly patientId: string;
  readonly patientPhone: string;
  readonly clinic: string;
  readonly time: string;
}

export async function sendReminders(
  appointments: readonly DueAppointment[],
  sender: TextMessageSender,
  log: ReminderLog,
): Promise<SendTextError[]> {
  const failures: SendTextError[] = [];
  for (const a of appointments) {
    const body = `Reminder: ${a.clinic} tomorrow at ${a.time}. Reply STOP to opt out.`;
    const result = await sender.send({ to: a.patientPhone, body });
    if (result.success) {
      await log.record(a.id, result.data.messageId);
    } else if (result.error.kind === 'RecipientOptedOut') {
      await log.markOptedOut(a.patientId);
    } else {
      failures.push(result.error);
    }
  }
  return failures;
}
```

The opt-out branch now depends on a named error kind, `InMemoryTextSender.optOut()` makes it trivial to exercise, and swapping Twilio for another SMS vendor is a new adapter plus one line in the composition root.

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  canBeCancelled(): boolean {
    return this.isActive() && !this.isExpired();
  }

  cancel(): Subscription {
    if (!this.canBeCancelled()) {
      throw new SubscriptionCannotBeCancelledError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionCannotBeCancelledError extends Error {
  constructor() {
    super('Cannot cancel an expired subscription');
    this.name = 'SubscriptionCannotBeCancelledError';
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription } from '../Entities/Subscription';
import { SubscriptionCannotBeCancelledError } from '../Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionCannotBeCancelledError | SubscriptionNotFoundError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError());
      }

      if (!subscription.canBeCancelled()) {
        return error(new SubscriptionCannotBeCancelledError());
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof SubscriptionCannotBeCancelledError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

// Result type implementation
export type Result<T, E extends Error> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    isError: false,
    value,
  };
}

export function error<E extends Error>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    isError: true,
    error,
  };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: `Subscription` is a simple entity with no dependencies on external frameworks or infrastructure
2. **Invariant Validation**: The `canBeCancelled()` method enforces that only active subscriptions can be cancelled
3. **Result Pattern**: Use cases return `Result<T, E>` with proper error types
4. **Typed Errors**: Specific domain errors are used instead of generic ones
5. **Dependency Rule**: Domain layer doesn't depend on any external libraries or frameworks
6. **No `any` Type**: All types are explicitly defined with interfaces and types
7. **SOLID Principles**: 
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Interface implementations work correctly
   - Interface Segregation: Clear separation of concerns
   - Dependency Inversion: Dependencies are injected through constructor

The `CancelSubscriptionUseCase` validates that:
- The subscription exists
- The subscription is not already expired
- The subscription is in an active state
- Returns appropriate errors when validation fails

Refactor this Apollo GraphQL resolver for booking clinic appointments. Separate the scheduling rules from Knex and GraphQL:

```typescript
const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const start = new Date(args.startsAt);
      const end = new Date(start.getTime() + 30 * 60000);
      const hour = start.getUTCHours();
      if (hour < 8 || hour >= 17 || start.getUTCMinutes() % 30 !== 0) {
        throw new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
      }
      const clash = await knex('appointments')
        .where({ doctor_id: args.doctorId })
        .andWhere('starts_at', '<', end)
        .andWhere('ends_at', '>', start)
        .first();
      if (clash) throw new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
      const [row] = await knex('appointments')
        .insert({ doctor_id: args.doctorId, patient_id: args.patientId, starts_at: start, ends_at: end })
        .returning('*');
      return row;
    },
  },
};
```

### Architectural Flaws in Original Code
1. **Scheduling policy inside a resolver:** working hours, the 30-minute grid and slot length live next to `GraphQLError`.
2. **Query builder in the API layer:** the overlap rule is expressed only as SQL, so it cannot be tested in memory.
3. **Raw rows returned:** the GraphQL schema is coupled to database column names.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Slot.ts`)
```typescript
import { Result } from '../shared/Result';

export type BookingError = { kind: 'OutsideWorkingHours' } | { kind: 'SlotTaken' };

export class Slot {
  static readonly LENGTH_MINUTES = 30;
  static readonly OPENS_AT_HOUR = 8;
  static readonly CLOSES_AT_HOUR = 17;

  private constructor(readonly start: Date, readonly end: Date) {}

  static at(start: Date): Result<Slot, BookingError> {
    const hour = start.getUTCHours();
    const onGrid = start.getUTCMinutes() % Slot.LENGTH_MINUTES === 0;
    if (hour < Slot.OPENS_AT_HOUR || hour >= Slot.CLOSES_AT_HOUR || !onGrid) {
      return Result.fail({ kind: 'OutsideWorkingHours' });
    }
    return Result.ok(new Slot(start, new Date(start.getTime() + Slot.LENGTH_MINUTES * 60_000)));
  }

  overlaps(other: { start: Date; end: Date }): boolean {
    return other.start < this.end && other.end > this.start;
  }
}

export interface Appointment {
  readonly id?: string;
  readonly doctorId: string;
  readonly patientId: string;
  readonly start: Date;
  readonly end: Date;
}
```

#### 2. Application Layer (`src/application/BookAppointment.ts`)
```typescript
import { Result } from '../shared/Result';
import { Appointment, BookingError, Slot } from '../domain/Slot';

export interface AppointmentRepository {
  forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]>;
  add(appointment: Appointment): Promise<Appointment>;
}

export class BookAppointment {
  constructor(private readonly appointments: AppointmentRepository) {}

  async execute(input: { doctorId: string; patientId: string; startsAt: Date }): Promise<Result<Appointment, BookingError>> {
    const slot = Slot.at(input.startsAt);
    if (!slot.success) return slot;

    const existing = await this.appointments.forDoctorBetween(input.doctorId, slot.data.start, slot.data.end);
    if (existing.some((a) => slot.data.overlaps(a))) return Result.fail({ kind: 'SlotTaken' });

    const booked = await this.appointments.add({
      doctorId: input.doctorId, patientId: input.patientId, start: slot.data.start, end: slot.data.end,
    });
    return Result.ok(booked);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/KnexAppointmentRepository.ts`)
```typescript
import { Knex } from 'knex';
import { Appointment } from '../domain/Slot';
import { AppointmentRepository } from '../application/BookAppointment';

interface AppointmentRow { id: string; doctor_id: string; patient_id: string; starts_at: Date; ends_at: Date; }

const toAppointment = (r: AppointmentRow): Appointment =>
  ({ id: r.id, doctorId: r.doctor_id, patientId: r.patient_id, start: r.starts_at, end: r.ends_at });

export class KnexAppointmentRepository implements AppointmentRepository {
  constructor(private readonly knex: Knex) {}

  async forDoctorBetween(doctorId: string, from: Date, to: Date): Promise<Appointment[]> {
    const rows = await this.knex<AppointmentRow>('appointments')
      .where({ doctor_id: doctorId }).andWhere('starts_at', '<', to).andWhere('ends_at', '>', from);
    return rows.map(toAppointment);
  }

  async add(a: Appointment): Promise<Appointment> {
    const [row] = await this.knex<AppointmentRow>('appointments')
      .insert({ doctor_id: a.doctorId, patient_id: a.patientId, starts_at: a.start, ends_at: a.end })
      .returning('*');
    return toAppointment(row);
  }
}
```

#### 4. Presentation Layer (resolver)
```typescript
function toGraphQLError(error: BookingError): GraphQLError {
  switch (error.kind) {
    case 'OutsideWorkingHours':
      return new GraphQLError('Slot outside working hours', { extensions: { code: 'BAD_SLOT' } });
    case 'SlotTaken':
      return new GraphQLError('Slot taken', { extensions: { code: 'SLOT_TAKEN' } });
  }
}

export const resolvers = {
  Mutation: {
    bookAppointment: async (_: unknown, args: { doctorId: string; patientId: string; startsAt: string }) => {
      const result = await bookAppointment.execute({ ...args, startsAt: new Date(args.startsAt) });
      if (result.success) return result.data;
      throw toGraphQLError(result.error);
    },
  },
};
```

The mutation now returns `{ id, doctorId, patientId, start, end }` instead of raw column names, so the GraphQL `Appointment` type must expose those fields.

### Domain (`src/domain/tipPool.ts`)
The split is a pure function over the pool and the time sheet; the shift aggregate only guards its own lifecycle (closed, not yet distributed).

```typescript
import { Result } from '../shared/Result';

export type Role = 'FRONT' | 'BACK' | 'MANAGER';

export interface TimeEntry {
  readonly employeeId: string;
  readonly role: Role;
  readonly minutes: number;
}

export interface Payout {
  readonly employeeId: string;
  readonly cents: number;
}

export type TipPoolError =
  | { kind: 'ShiftNotFound' }
  | { kind: 'ShiftOpen' }
  | { kind: 'AlreadyDistributed' }
  | { kind: 'NoEligibleStaff' };

export const FRONT_SHARE = 0.7;
export const MIN_MINUTES = 60;

function splitByMinutes(cents: number, staff: readonly TimeEntry[]): Payout[] {
  const total = staff.reduce((sum, e) => sum + e.minutes, 0);
  const payouts = staff.map((e) => ({ employeeId: e.employeeId, cents: Math.floor((cents * e.minutes) / total) }));
  const leftover = cents - payouts.reduce((sum, p) => sum + p.cents, 0);
  const top = [...staff].sort((a, b) => b.minutes - a.minutes || a.employeeId.localeCompare(b.employeeId))[0];
  return payouts.map((p) => (top && p.employeeId === top.employeeId ? { ...p, cents: p.cents + leftover } : p));
}

export function distributeTips(poolCents: number, entries: readonly TimeEntry[]): Result<Payout[], TipPoolError> {
  const eligible = entries.filter((e) => e.role !== 'MANAGER' && e.minutes >= MIN_MINUTES);
  const front = eligible.filter((e) => e.role === 'FRONT');
  const back = eligible.filter((e) => e.role === 'BACK');
  if (front.length === 0 && back.length === 0) return Result.fail({ kind: 'NoEligibleStaff' });
  if (back.length === 0) return Result.ok(splitByMinutes(poolCents, front));
  if (front.length === 0) return Result.ok(splitByMinutes(poolCents, back));

  const frontCents = Math.round(poolCents * FRONT_SHARE);
  return Result.ok([...splitByMinutes(frontCents, front), ...splitByMinutes(poolCents - frontCents, back)]);
}

export class Shift {
  constructor(
    readonly id: string,
    readonly poolCents: number,
    readonly closed: boolean,
    private distributed: boolean,
  ) {}

  get isDistributed(): boolean { return this.distributed; }

  distribute(entries: readonly TimeEntry[]): Result<Payout[], TipPoolError> {
    if (!this.closed) return Result.fail({ kind: 'ShiftOpen' });
    if (this.distributed) return Result.fail({ kind: 'AlreadyDistributed' });
    const payouts = distributeTips(this.poolCents, entries);
    if (payouts.success) this.distributed = true;
    return payouts;
  }
}
```

### Application (`src/application/DistributeTipPool.ts`)
```typescript
import { Result } from '../shared/Result';
import { Payout, Shift, TimeEntry, TipPoolError } from '../domain/tipPool';

export interface ShiftRepository {
  findById(id: string): Promise<Shift | null>;
}

export interface TimesheetReader {
  entriesFor(shiftId: string): Promise<readonly TimeEntry[]>;
}

export interface PayrollLedger {
  /** Persists the payouts and the shift's distributed flag in one transaction. */
  recordTips(shift: Shift, payouts: readonly Payout[]): Promise<void>;
}

export class DistributeTipPool {
  constructor(
    private readonly shifts: ShiftRepository,
    private readonly timesheets: TimesheetReader,
    private readonly ledger: PayrollLedger,
  ) {}

  async execute(shiftId: string): Promise<Result<Payout[], TipPoolError>> {
    const shift = await this.shifts.findById(shiftId);
    if (!shift) return Result.fail({ kind: 'ShiftNotFound' });

    const payouts = shift.distribute(await this.timesheets.entriesFor(shiftId));
    if (!payouts.success) return payouts;

    await this.ledger.recordTips(shift, payouts.data);
    return payouts;
  }
}
```

Example: a pool of 1,000.01 gives front of house 700.01 and back of house 300.00. Two servers with 300 and 200 minutes get 420.00 and 280.00 plus the leftover cent to the first one (420.01). A host with 45 minutes and the manager get nothing. Because each group's payouts sum exactly to its share, the total paid always equals the pool.

Refactor this Kafka consumer so invoice settlement rules can be tested without Kafka or MongoDB:

```typescript
await consumer.run({
  eachMessage: async ({ message }) => {
    const evt = JSON.parse(message.value!.toString());
    const invoices = mongo.db('billing').collection('invoices');
    const invoice = await invoices.findOne({ _id: evt.invoiceId });
    if (!invoice || invoice.status === 'void') return;
    const paid = invoice.paid + evt.amountCents;
    let status = 'partially_paid';
    if (paid >= invoice.totalCents) status = 'paid';
    await invoices.updateOne(
      { _id: evt.invoiceId },
      { $set: { paid, status }, $push: { payments: { ref: evt.paymentRef, amount: evt.amountCents } } },
    );
    if (paid > invoice.totalCents) {
      await producer.send({ topic: 'refunds', messages: [{ value: JSON.stringify({
        invoiceId: evt.invoiceId, amountCents: paid - invoice.totalCents }) }] });
    }
  },
});
```

### Architectural Flaws in Original Code
1. **Settlement logic in the message loop:** status transitions and overpayment detection are tied to `kafkajs` callbacks.
2. **Untyped event:** the payload is `JSON.parse`d and used without validation.
3. **Silent idempotency gap:** a redelivered message is applied twice because the payment reference is never checked.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Invoice.ts`)
```typescript
import { Result } from '../shared/Result';

export type InvoiceStatus = 'open' | 'partially_paid' | 'paid' | 'void';
export type SettlementError = { kind: 'InvoiceVoid' } | { kind: 'DuplicatePayment'; ref: string };

export interface Payment { readonly ref: string; readonly amountCents: number; }

export class Invoice {
  constructor(
    readonly id: string,
    readonly totalCents: number,
    private paidCents: number,
    private currentStatus: InvoiceStatus,
    private readonly payments: Payment[],
  ) {}

  get paid(): number { return this.paidCents; }
  get status(): InvoiceStatus { return this.currentStatus; }

  /** Applies a payment and returns the overpaid amount in cents (0 if none). */
  apply(payment: Payment): Result<number, SettlementError> {
    if (this.currentStatus === 'void') return Result.fail({ kind: 'InvoiceVoid' });
    if (this.payments.some((p) => p.ref === payment.ref)) {
      return Result.fail({ kind: 'DuplicatePayment', ref: payment.ref });
    }
    this.payments.push(payment);
    this.paidCents += payment.amountCents;
    this.currentStatus = this.paidCents >= this.totalCents ? 'paid' : 'partially_paid';
    return Result.ok(Math.max(0, this.paidCents - this.totalCents));
  }
}
```

#### 2. Application Layer (`src/application/SettleInvoice.ts`)
```typescript
import { Result } from '../shared/Result';
import { Invoice, Payment, SettlementError } from '../domain/Invoice';

export type SettleError = SettlementError | { kind: 'InvoiceNotFound' };

export interface InvoiceRepository {
  findById(id: string): Promise<Invoice | null>;
  recordPayment(invoice: Invoice, payment: Payment): Promise<void>;
}

export interface RefundRequester {
  request(invoiceId: string, amountCents: number): Promise<void>;
}

export class SettleInvoice {
  constructor(private readonly invoices: InvoiceRepository, private readonly refunds: RefundRequester) {}

  async execute(invoiceId: string, payment: Payment): Promise<Result<void, SettleError>> {
    const invoice = await this.invoices.findById(invoiceId);
    if (!invoice) return Result.fail({ kind: 'InvoiceNotFound' });

    const overpaid = invoice.apply(payment);
    if (!overpaid.success) return overpaid;

    await this.invoices.recordPayment(invoice, payment);
    if (overpaid.data > 0) await this.refunds.request(invoiceId, overpaid.data);
    return Result.ok(undefined);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection } from 'mongodb';
import { Producer } from 'kafkajs';
import { Invoice, InvoiceStatus, Payment } from '../domain/Invoice';
import { InvoiceRepository, RefundRequester } from '../application/SettleInvoice';

interface InvoiceDoc {
  _id: string; totalCents: number; paid: number; status: InvoiceStatus;
  payments: { ref: string; amount: number }[];
}

export class MongoInvoiceRepository implements InvoiceRepository {
  constructor(private readonly invoices: Collection<InvoiceDoc>) {}

  async findById(id: string): Promise<Invoice | null> {
    const doc = await this.invoices.findOne({ _id: id });
    if (!doc) return null;
    const payments = doc.payments.map((p) => ({ ref: p.ref, amountCents: p.amount }));
    return new Invoice(doc._id, doc.totalCents, doc.paid, doc.status, payments);
  }

  async recordPayment(invoice: Invoice, payment: Payment): Promise<void> {
    await this.invoices.updateOne(
      { _id: invoice.id },
      { $set: { paid: invoice.paid, status: invoice.status },
        $push: { payments: { ref: payment.ref, amount: payment.amountCents } } },
    );
  }
}

export class KafkaRefundRequester implements RefundRequester {
  constructor(private readonly producer: Producer) {}

  async request(invoiceId: string, amountCents: number): Promise<void> {
    await this.producer.send({ topic: 'refunds', messages: [{ value: JSON.stringify({ invoiceId, amountCents }) }] });
  }
}
```

#### 4. Entry Point (consumer)
Malformed messages are rejected at the edge by a type guard.
```typescript
import { EachMessagePayload } from 'kafkajs';

interface PaymentSettled { invoiceId: string; paymentRef: string; amountCents: number; }

function isPaymentSettled(v: unknown): v is PaymentSettled {
  if (typeof v !== 'object' || v === null) return false;
  const e = v as Record<string, unknown>;
  return typeof e.invoiceId === 'string' && typeof e.paymentRef === 'string' && typeof e.amountCents === 'number';
}

await consumer.run({
  eachMessage: async ({ message }: EachMessagePayload) => {
    const evt: unknown = JSON.parse(message.value?.toString() ?? 'null');
    if (!isPaymentSettled(evt)) return;
    await settleInvoice.execute(evt.invoiceId, { ref: evt.paymentRef, amountCents: evt.amountCents });
  },
});
```

