```typescript
// Domain/ValueObjects/Money.ts
export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: string
  ) {
    if (_amount < 0) {
      throw new Error("Amount must be positive");
    }
  }

  static create(amount: number, currency: string): Money {
    return new Money(amount, currency);
  }

  get amount(): number {
    return this._amount;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    if (this._currency !== other._currency) {
      throw new Error("Cannot add money with different currencies");
    }
    return new Money(this._amount + other._amount, this._currency);
  }

  equals(other: Money): boolean {
    return this._amount === other._amount && this._currency === other._currency;
  }
}
```

```typescript
// Domain/ValueObjects/Money.spec.ts
import { Money } from "./Money";

describe("Money", () => {
  describe("creation", () => {
    it("should create a valid money instance", () => {
      const money = Money.create(100, "USD");
      expect(money.amount).toBe(100);
      expect(money.currency).toBe("USD");
    });

    it("should throw an error when amount is negative", () => {
      expect(() => Money.create(-10, "USD")).toThrow("Amount must be positive");
    });
  });

  describe("addition", () => {
    it("should add money with same currency", () => {
      const money1 = Money.create(50, "USD");
      const money2 = Money.create(30, "USD");
      const result = money1.add(money2);

      expect(result.amount).toBe(80);
      expect(result.currency).toBe("USD");
    });

    it("should throw an error when adding different currencies", () => {
      const money1 = Money.create(50, "USD");
      const money2 = Money.create(30, "EUR");

      expect(() => money1.add(money2)).toThrow("Cannot add money with different currencies");
    });
  });

  describe("equality", () => {
    it("should be equal when amount and currency are the same", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(100, "USD");

      expect(money1.equals(money2)).toBe(true);
    });

    it("should not be equal when amounts differ", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(50, "USD");

      expect(money1.equals(money2)).toBe(false);
    });

    it("should not be equal when currencies differ", () => {
      const money1 = Money.create(100, "USD");
      const money2 = Money.create(100, "EUR");

      expect(money1.equals(money2)).toBe(false);
    });
  });
});
```

This implementation follows Clean Architecture principles:

1. **Pure Value Object**: The `Money` class is immutable and has no behavior beyond value representation
2. **Domain Layer Only**: No dependencies on external libraries or frameworks
3. **Validation**: Enforces positive amounts at construction time
4. **Currency Safety**: Prevents addition of different currencies
5. **No External Dependencies**: Uses only TypeScript built-in features
6. **Immutability**: All properties are private and readonly
7. **Type Safety**: Strong typing for amount and currency
8. **Test Coverage**: Includes comprehensive tests for all behaviors

The implementation uses the Result pattern implicitly through exceptions for error handling, which is appropriate for value objects where invalid states should not be allowed. The class is designed to be used within the domain layer without any infrastructure dependencies.

Refactor this upload endpoint toward a layered architecture. The document rules depend on multer, the AWS SDK and Postgres:

```typescript
const upload = multer({ storage: multer.memoryStorage() });

app.post('/claims/:claimId/documents', upload.single('file'), async (req, res) => {
  const file = req.file;
  if (!file) return res.status(400).json({ error: 'No file' });
  const allowed = ['application/pdf', 'image/jpeg', 'image/png'];
  if (!allowed.includes(file.mimetype)) return res.status(415).json({ error: 'Unsupported type' });
  if (file.size > 10 * 1024 * 1024) return res.status(413).json({ error: 'File too large' });
  const { rows } = await pg.query('SELECT status, (SELECT COUNT(*) FROM claim_documents WHERE claim_id = $1) AS docs FROM claims WHERE id = $1', [req.params.claimId]);
  if (!rows[0]) return res.status(404).json({ error: 'Claim not found' });
  if (rows[0].status === 'closed') return res.status(409).json({ error: 'Claim is closed' });
  if (Number(rows[0].docs) >= 20) return res.status(409).json({ error: 'Too many documents' });
  const key = `claims/${req.params.claimId}/${Date.now()}-${file.originalname}`;
  await s3.send(new PutObjectCommand({ Bucket: 'claims-docs', Key: key, Body: file.buffer, ContentType: file.mimetype }));
  await pg.query('INSERT INTO claim_documents (claim_id, s3_key, mime) VALUES ($1, $2, $3)', [req.params.claimId, key, file.mimetype]);
  res.status(201).json({ key });
});
```

### Architectural Flaws in Original Code
1. **Insurance rules in the route:** accepted file types, the 10 MB limit and the 20-document cap are not reusable outside Express.
2. **Vendor SDKs in the request path:** `PutObjectCommand` and SQL strings make the flow untestable without AWS and Postgres.
3. **Storage key format leaks** into the business flow.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/ClaimDocuments.ts`)
```typescript
import { Result } from '../shared/Result';

export type UploadError =
  | { kind: 'UnsupportedType' }
  | { kind: 'TooLarge'; maxBytes: number }
  | { kind: 'ClaimNotFound' }
  | { kind: 'ClaimClosed' }
  | { kind: 'TooManyDocuments'; max: number };

export interface IncomingDocument {
  readonly fileName: string;
  readonly mimeType: string;
  readonly sizeBytes: number;
  readonly content: Uint8Array;
}

export const ACCEPTED_TYPES: readonly string[] = ['application/pdf', 'image/jpeg', 'image/png'];
export const MAX_BYTES = 10 * 1024 * 1024;
export const MAX_DOCUMENTS = 20;

export function checkDocument(doc: IncomingDocument): Result<IncomingDocument, UploadError> {
  if (!ACCEPTED_TYPES.includes(doc.mimeType)) return Result.fail({ kind: 'UnsupportedType' });
  if (doc.sizeBytes > MAX_BYTES) return Result.fail({ kind: 'TooLarge', maxBytes: MAX_BYTES });
  return Result.ok(doc);
}

export interface Claim {
  readonly id: string;
  readonly status: 'open' | 'closed';
  readonly documentCount: number;
}

export function canAttach(claim: Claim): Result<Claim, UploadError> {
  if (claim.status === 'closed') return Result.fail({ kind: 'ClaimClosed' });
  if (claim.documentCount >= MAX_DOCUMENTS) return Result.fail({ kind: 'TooManyDocuments', max: MAX_DOCUMENTS });
  return Result.ok(claim);
}
```

#### 2. Application Layer (`src/application/AttachClaimDocument.ts`)
```typescript
import { Result } from '../shared/Result';
import { Claim, IncomingDocument, UploadError, canAttach, checkDocument } from '../domain/ClaimDocuments';

export interface ClaimRepository {
  find(claimId: string): Promise<Claim | null>;
  addDocument(claimId: string, storageKey: string, mimeType: string): Promise<void>;
}

export interface DocumentStorage {
  /** Stores the content and returns its storage key. */
  put(claimId: string, doc: IncomingDocument): Promise<string>;
}

export class AttachClaimDocument {
  constructor(private readonly claims: ClaimRepository, private readonly storage: DocumentStorage) {}

  async execute(claimId: string, doc: IncomingDocument): Promise<Result<string, UploadError>> {
    const valid = checkDocument(doc);
    if (!valid.success) return valid;

    const claim = await this.claims.find(claimId);
    if (!claim) return Result.fail({ kind: 'ClaimNotFound' });
    const open = canAttach(claim);
    if (!open.success) return open;

    const key = await this.storage.put(claimId, doc);
    await this.claims.addDocument(claimId, key, doc.mimeType);
    return Result.ok(key);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/S3DocumentStorage.ts`)
```typescript
import { PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { IncomingDocument } from '../domain/ClaimDocuments';
import { DocumentStorage } from '../application/AttachClaimDocument';

export class S3DocumentStorage implements DocumentStorage {
  constructor(private readonly s3: S3Client, private readonly bucket: string, private readonly now: () => number) {}

  async put(claimId: string, doc: IncomingDocument): Promise<string> {
    const key = `claims/${claimId}/${this.now()}-${doc.fileName}`;
    await this.s3.send(new PutObjectCommand({ Bucket: this.bucket, Key: key, Body: doc.content, ContentType: doc.mimeType }));
    return key;
  }
}
```
`PgClaimRepository` implements `ClaimRepository` with the same `SELECT` and `INSERT` statements as before.

#### 4. Presentation Layer (route)
```typescript
function toHttp(error: UploadError): [number, string] {
  switch (error.kind) {
    case 'UnsupportedType': return [415, 'Unsupported type'];
    case 'TooLarge': return [413, 'File too large'];
    case 'ClaimNotFound': return [404, 'Claim not found'];
    case 'ClaimClosed': return [409, 'Claim is closed'];
    case 'TooManyDocuments': return [409, 'Too many documents'];
  }
}

app.post('/claims/:claimId/documents', upload.single('file'), async (req, res) => {
  const file = req.file;
  if (!file) return res.status(400).json({ error: 'No file' });
  const result = await attachDocument.execute(req.params.claimId, {
    fileName: file.originalname, mimeType: file.mimetype, sizeBytes: file.size, content: file.buffer,
  });
  if (result.success) return res.status(201).json({ key: result.data });
  const [status, error] = toHttp(result.error);
  res.status(status).json({ error });
});
```

Critique this class using SOLID and refactor it:

```typescript
class ShapeAreaService {
  area(shape: { kind: string; w?: number; h?: number; r?: number }): number {
    if (shape.kind === 'rect') return shape.w! * shape.h!;
    if (shape.kind === 'circle') return Math.PI * shape.r! ** 2;
    throw new Error('Unknown shape');
  }
}
```

### SOLID Critique
- **OCP (violated):** every new shape edits `area`.
- **Type safety:** optional fields plus non-null assertions (`!`) hide missing data until runtime.
- **SRP (borderline):** one class knows the geometry of every shape.

---

### Refactoring: polymorphism instead of a `kind` switch
```typescript
export interface Shape {
  area(): number;
}

export class Rectangle implements Shape {
  constructor(private readonly width: number, private readonly height: number) {}
  area(): number { return this.width * this.height; }
}

export class Circle implements Shape {
  constructor(private readonly radius: number) {}
  area(): number { return Math.PI * this.radius ** 2; }
}

export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + shape.area(), 0);
}
```

A triangle is now one new class. `totalArea` never changes (OCP), and each shape owns exactly the data it needs, so no optional fields or `!` are required.

Write Arrange-Act-Assert tests for the warehouse transfer below. The stock ledger should be an in-memory fake so we can check both balances after the move.

```typescript
import { Result } from '../shared/Result';

export interface StockLedger {
  quantity(warehouseId: string, sku: string): Promise<number | null>;
  move(from: string, to: string, sku: string, qty: number, at: Date): Promise<void>;
}

export type TransferError =
  | { kind: 'InvalidQuantity' }
  | { kind: 'SameWarehouse' }
  | { kind: 'UnknownWarehouse'; warehouseId: string }
  | { kind: 'InsufficientStock'; available: number };

export interface TransferCommand {
  from: string;
  to: string;
  sku: string;
  qty: number;
}

export class TransferStock {
  constructor(private readonly ledger: StockLedger, private readonly now: () => Date) {}

  async execute(cmd: TransferCommand): Promise<Result<void, TransferError>> {
    if (!Number.isInteger(cmd.qty) || cmd.qty <= 0) return Result.fail({ kind: 'InvalidQuantity' });
    if (cmd.from === cmd.to) return Result.fail({ kind: 'SameWarehouse' });
    const available = await this.ledger.quantity(cmd.from, cmd.sku);
    if (available === null) return Result.fail({ kind: 'UnknownWarehouse', warehouseId: cmd.from });
    const target = await this.ledger.quantity(cmd.to, cmd.sku);
    if (target === null) return Result.fail({ kind: 'UnknownWarehouse', warehouseId: cmd.to });
    if (available < cmd.qty) return Result.fail({ kind: 'InsufficientStock', available });
    await this.ledger.move(cmd.from, cmd.to, cmd.sku, cmd.qty, this.now());
    return Result.ok(undefined);
  }
}
```

The fake ledger keeps one map of warehouses and their stock, and logs each move with its timestamp, so tests assert on final balances instead of on calls. A `transfer()` factory supplies a valid command that each test overrides.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { TransferStock, StockLedger, TransferCommand } from './TransferStock';

class InMemoryStockLedger implements StockLedger {
  private readonly stock = new Map<string, Map<string, number>>();
  readonly moves: Array<{ sku: string; qty: number; at: Date }> = [];

  addWarehouse(id: string, items: Record<string, number> = {}): void {
    this.stock.set(id, new Map(Object.entries(items)));
  }

  async quantity(warehouseId: string, sku: string): Promise<number | null> {
    const wh = this.stock.get(warehouseId);
    return wh ? wh.get(sku) ?? 0 : null;
  }

  async move(from: string, to: string, sku: string, qty: number, at: Date): Promise<void> {
    const src = this.stock.get(from);
    const dst = this.stock.get(to);
    if (!src || !dst) throw new Error('fake misused: unknown warehouse');
    src.set(sku, (src.get(sku) ?? 0) - qty);
    dst.set(sku, (dst.get(sku) ?? 0) + qty);
    this.moves.push({ sku, qty, at });
  }
}

const NOW = new Date('2024-07-15T08:30:00Z');
const transfer = (overrides: Partial<TransferCommand> = {}): TransferCommand => ({
  from: 'MAD', to: 'BCN', sku: 'CHAIR-01', qty: 5, ...overrides,
});

describe('TransferStock', () => {
  let ledger: InMemoryStockLedger;
  let useCase: TransferStock;

  beforeEach(() => {
    ledger = new InMemoryStockLedger();
    ledger.addWarehouse('MAD', { 'CHAIR-01': 8 });
    ledger.addWarehouse('BCN');
    useCase = new TransferStock(ledger, () => NOW);
  });

  it('moves the quantity and stamps the move with the clock', async () => {
    // Arrange
    const cmd = transfer();

    // Act
    const result = await useCase.execute(cmd);

    // Assert
    expect(result.success).toBe(true);
    expect(await ledger.quantity('MAD', 'CHAIR-01')).toBe(3);
    expect(await ledger.quantity('BCN', 'CHAIR-01')).toBe(5);
    expect(ledger.moves).toEqual([{ sku: 'CHAIR-01', qty: 5, at: NOW }]);
  });

  it('allows moving the entire available stock', async () => {
    // Arrange
    const everything = transfer({ qty: 8 });

    // Act
    const result = await useCase.execute(everything);

    // Assert
    expect(result.success).toBe(true);
    expect(await ledger.quantity('MAD', 'CHAIR-01')).toBe(0);
  });

  it.each([0, -2, 1.5])('rejects quantity %s', async (qty) => {
    // Arrange
    const cmd = transfer({ qty });

    // Act
    const result = await useCase.execute(cmd);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('InvalidQuantity');
  });

  it('rejects a transfer to the same warehouse', async () => {
    // Arrange
    const cmd = transfer({ to: 'MAD' });

    // Act
    const result = await useCase.execute(cmd);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('SameWarehouse');
  });

  it.each([
    { cmd: transfer({ from: 'XXX' }), missing: 'XXX' },
    { cmd: transfer({ to: 'YYY' }), missing: 'YYY' },
  ])('reports $missing as an unknown warehouse', async ({ cmd, missing }) => {
    // Arrange: cmd names a warehouse the ledger does not know

    // Act
    const result = await useCase.execute(cmd);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'UnknownWarehouse', warehouseId: missing });
  });

  it('refuses to move more than is available and changes nothing', async () => {
    // Arrange
    const tooMany = transfer({ qty: 9 });

    // Act
    const result = await useCase.execute(tooMany);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'InsufficientStock', available: 8 });
    expect(ledger.moves).toHaveLength(0);
  });
});
```

Refactor this recipe scaling function. It mixes the conversion math with i18next and localStorage:

```typescript
export function scaledIngredients(recipe: Recipe, servings: number): string[] {
  const unitSystem = localStorage.getItem('units') ?? 'metric';
  const factor = servings / recipe.servings;
  return recipe.ingredients.map((ing) => {
    let qty = ing.quantity * factor;
    let unit = ing.unit;
    if (unitSystem === 'imperial' && unit === 'g') { qty = qty / 28.35; unit = 'oz'; }
    if (unitSystem === 'imperial' && unit === 'ml') { qty = qty / 29.57; unit = 'fl oz'; }
    if (unit === 'pcs') qty = Math.ceil(qty);
    else qty = Math.round(qty * 10) / 10;
    return i18next.t('ingredient', { qty, unit, name: ing.name });
  });
}
```

### Architectural Flaws
1. **Scaling and unit conversion are coupled to the browser:** `localStorage` makes the function untestable in Node.
2. **Presentation inside the calculation:** `i18next.t` returns display strings, so other screens cannot reuse the numbers.

### Domain (`src/domain/recipeScaling.ts`)
```typescript
export type UnitSystem = 'metric' | 'imperial';

export interface Ingredient {
  readonly name: string;
  readonly quantity: number;
  readonly unit: string;
}

const IMPERIAL: Readonly<Record<string, { unit: string; divisor: number }>> = {
  g: { unit: 'oz', divisor: 28.35 },
  ml: { unit: 'fl oz', divisor: 29.57 },
};

export function scale(ingredients: readonly Ingredient[], fromServings: number, toServings: number, system: UnitSystem): Ingredient[] {
  const factor = toServings / fromServings;
  return ingredients.map((ing) => {
    let quantity = ing.quantity * factor;
    let unit = ing.unit;
    const conversion = system === 'imperial' ? IMPERIAL[unit] : undefined;
    if (conversion) {
      quantity /= conversion.divisor;
      unit = conversion.unit;
    }
    quantity = unit === 'pcs' ? Math.ceil(quantity) : Math.round(quantity * 10) / 10;
    return { name: ing.name, quantity, unit };
  });
}
```

### Presentation (`src/ui/ingredients.ts`)
```typescript
import i18next from 'i18next';
import { Ingredient, UnitSystem, scale } from '../domain/recipeScaling';

export function readUnitPreference(): UnitSystem {
  return localStorage.getItem('units') === 'imperial' ? 'imperial' : 'metric';
}

export function ingredientLines(recipe: { servings: number; ingredients: readonly Ingredient[] }, servings: number): string[] {
  return scale(recipe.ingredients, recipe.servings, servings, readUnitPreference())
    .map((i) => i18next.t('ingredient', { qty: i.quantity, unit: i.unit, name: i.name }));
}
```
No application layer or repository is needed: there is no persistence or external service involved, only a pure transformation and a view. `scale([{ name: 'flour', quantity: 500, unit: 'g' }], 4, 2, 'imperial')` returns `8.8 oz` of flour.

Cover the fine waiver rules with AAA unit tests. Librarians have a cap and a once-a-year rule, head librarians don't; I want that difference to be obvious from the test table.

```typescript
import { Result } from '../shared/Result';

export type StaffRole = 'librarian' | 'head_librarian';

export interface Fine {
  id: string;
  patronId: string;
  amountCents: number;
  status: 'unpaid' | 'paid' | 'waived';
  waivedAt?: Date;
}

export interface FineRepository {
  get(id: string): Promise<Fine | null>;
  save(fine: Fine): Promise<void>;
  waiversSince(patronId: string, since: Date): Promise<number>;
}

export type WaiverError =
  | { kind: 'FineNotFound' }
  | { kind: 'NotUnpaid' }
  | { kind: 'AboveLibrarianLimit'; limitCents: number }
  | { kind: 'RecentWaiver' };

const LIBRARIAN_LIMIT_CENTS = 1_000;
const YEAR_MS = 365 * 86_400_000;

export class WaiveOverdueFine {
  constructor(private readonly fines: FineRepository, private readonly now: () => Date) {}

  async execute(fineId: string, role: StaffRole): Promise<Result<void, WaiverError>> {
    const fine = await this.fines.get(fineId);
    if (!fine) return Result.fail({ kind: 'FineNotFound' });
    if (fine.status !== 'unpaid') return Result.fail({ kind: 'NotUnpaid' });
    const now = this.now();
    if (role === 'librarian') {
      if (fine.amountCents > LIBRARIAN_LIMIT_CENTS) {
        return Result.fail({ kind: 'AboveLibrarianLimit', limitCents: LIBRARIAN_LIMIT_CENTS });
      }
      const recent = await this.fines.waiversSince(fine.patronId, new Date(now.getTime() - YEAR_MS));
      if (recent > 0) return Result.fail({ kind: 'RecentWaiver' });
    }
    await this.fines.save({ ...fine, status: 'waived', waivedAt: now });
    return Result.ok(undefined);
  }
}
```

`waiversSince` is implemented by the fake over the fines it stores, so a "recent waiver" is simply an earlier waived fine in the same map. The table runs the same fine through both roles to make the role difference visible.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { WaiveOverdueFine, Fine, FineRepository, StaffRole } from './WaiveOverdueFine';

class InMemoryFines implements FineRepository {
  readonly fines = new Map<string, Fine>();
  async get(id: string): Promise<Fine | null> {
    return this.fines.get(id) ?? null;
  }
  async save(fine: Fine): Promise<void> {
    this.fines.set(fine.id, fine);
  }
  async waiversSince(patronId: string, since: Date): Promise<number> {
    return [...this.fines.values()].filter(
      (f) => f.patronId === patronId && f.status === 'waived' && f.waivedAt !== undefined && f.waivedAt >= since,
    ).length;
  }
}

const NOW = new Date('2024-09-30T14:00:00Z');
const daysAgo = (d: number): Date => new Date(NOW.getTime() - d * 86_400_000);
const unpaidFine = (amountCents: number): Fine => ({ id: 'f-new', patronId: 'p-1', amountCents, status: 'unpaid' });
const pastWaiver = (waivedAt: Date): Fine => ({
  id: 'f-old', patronId: 'p-1', amountCents: 300, status: 'waived', waivedAt,
});

describe('WaiveOverdueFine', () => {
  let fines: InMemoryFines;
  let useCase: WaiveOverdueFine;

  beforeEach(() => {
    fines = new InMemoryFines();
    useCase = new WaiveOverdueFine(fines, () => NOW);
  });

  it.each<{ role: StaffRole; amount: number; recentWaiver: boolean; expected: string }>([
    { role: 'librarian', amount: 1_000, recentWaiver: false, expected: 'waived' },
    { role: 'librarian', amount: 1_001, recentWaiver: false, expected: 'AboveLibrarianLimit' },
    { role: 'librarian', amount: 500, recentWaiver: true, expected: 'RecentWaiver' },
    { role: 'head_librarian', amount: 5_000, recentWaiver: false, expected: 'waived' },
    { role: 'head_librarian', amount: 500, recentWaiver: true, expected: 'waived' },
  ])('$role, $amount cents, recent waiver: $recentWaiver -> $expected', async ({ role, amount, recentWaiver, expected }) => {
    // Arrange
    await fines.save(unpaidFine(amount));
    if (recentWaiver) await fines.save(pastWaiver(daysAgo(100)));

    // Act
    const result = await useCase.execute('f-new', role);

    // Assert
    expect(result.success ? 'waived' : result.error.kind).toBe(expected);
    expect(fines.fines.get('f-new')?.status).toBe(result.success ? 'waived' : 'unpaid');
  });

  it('records the waiver time from the clock', async () => {
    // Arrange
    await fines.save(unpaidFine(400));

    // Act
    await useCase.execute('f-new', 'librarian');

    // Assert
    expect(fines.fines.get('f-new')?.waivedAt).toEqual(NOW);
  });

  it('lets a librarian waive again once the last waiver is over a year old', async () => {
    // Arrange
    await fines.save(unpaidFine(400));
    await fines.save(pastWaiver(daysAgo(366)));

    // Act
    const result = await useCase.execute('f-new', 'librarian');

    // Assert
    expect(result.success).toBe(true);
  });

  it('fails with FineNotFound', async () => {
    // Arrange: no fines

    // Act
    const result = await useCase.execute('nope', 'head_librarian');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('FineNotFound');
  });

  it('fails with NotUnpaid for a fine that was already paid', async () => {
    // Arrange
    await fines.save({ ...unpaidFine(400), status: 'paid' });

    // Act
    const result = await useCase.execute('f-new', 'head_librarian');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('NotUnpaid');
  });
});
