Give me Arrange-Act-Assert tests for the no-show policy below. Build appointments with a small builder, keep everything in memory, and cover the third strike that blocks online booking.

```typescript
import { Result } from '../shared/Result';

export type AppointmentStatus = 'booked' | 'attended' | 'no_show' | 'cancelled';

export interface Appointment {
  id: string;
  patientId: string;
  startsAt: Date;
  status: AppointmentStatus;
}

export interface AppointmentRepository {
  get(id: string): Promise<Appointment | null>;
  save(appointment: Appointment): Promise<void>;
  countNoShows(patientId: string, since: Date): Promise<number>;
}

export interface BookingRestrictions {
  blockOnline(patientId: string, until: Date): Promise<void>;
}

export type NoShowError =
  | { kind: 'AppointmentNotFound' }
  | { kind: 'NotBooked'; status: AppointmentStatus }
  | { kind: 'GracePeriod'; minutesLate: number };

const GRACE_MINUTES = 15;
const DAY_MS = 86_400_000;

export class MarkNoShow {
  constructor(
    private readonly appointments: AppointmentRepository,
    private readonly restrictions: BookingRestrictions,
    private readonly now: () => Date,
  ) {}

  async execute(appointmentId: string): Promise<Result<{ blocked: boolean }, NoShowError>> {
    const appt = await this.appointments.get(appointmentId);
    if (!appt) return Result.fail({ kind: 'AppointmentNotFound' });
    if (appt.status !== 'booked') return Result.fail({ kind: 'NotBooked', status: appt.status });
    const now = this.now();
    const minutesLate = (now.getTime() - appt.startsAt.getTime()) / 60_000;
    if (minutesLate < GRACE_MINUTES) return Result.fail({ kind: 'GracePeriod', minutesLate });
    await this.appointments.save({ ...appt, status: 'no_show' });
    const strikes = await this.appointments.countNoShows(appt.patientId, new Date(now.getTime() - 90 * DAY_MS));
    if (strikes < 3) return Result.ok({ blocked: false });
    await this.restrictions.blockOnline(appt.patientId, new Date(now.getTime() + 30 * DAY_MS));
    return Result.ok({ blocked: true });
  }
}
```

The appointment fake implements `countNoShows` over its own stored data, so strikes come from real history rather than a stubbed number, and the 90-day window is actually exercised. `BookingRestrictions` is a fake that records the block per patient.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { MarkNoShow, Appointment, AppointmentRepository, AppointmentStatus, BookingRestrictions } from './MarkNoShow';

class InMemoryAppointments implements AppointmentRepository {
  readonly rows = new Map<string, Appointment>();
  async get(id: string): Promise<Appointment | null> {
    return this.rows.get(id) ?? null;
  }
  async save(appointment: Appointment): Promise<void> {
    this.rows.set(appointment.id, appointment);
  }
  async countNoShows(patientId: string, since: Date): Promise<number> {
    return [...this.rows.values()].filter(
      (a) => a.patientId === patientId && a.status === 'no_show' && a.startsAt >= since,
    ).length;
  }
}

class FakeRestrictions implements BookingRestrictions {
  readonly blockedUntil = new Map<string, Date>();
  async blockOnline(patientId: string, until: Date): Promise<void> {
    this.blockedUntil.set(patientId, until);
  }
}

const NOW = new Date('2024-05-20T10:30:00Z');
const DAY = 86_400_000;
let seq = 0;
const anAppointment = (minutesAgo: number, status: AppointmentStatus = 'booked'): Appointment => ({
  id: `a${++seq}`, patientId: 'p-1', startsAt: new Date(NOW.getTime() - minutesAgo * 60_000), status,
});

describe('MarkNoShow', () => {
  let appointments: InMemoryAppointments;
  let restrictions: FakeRestrictions;
  let useCase: MarkNoShow;

  beforeEach(() => {
    appointments = new InMemoryAppointments();
    restrictions = new FakeRestrictions();
    useCase = new MarkNoShow(appointments, restrictions, () => NOW);
  });

  it('marks a first no-show without blocking the patient', async () => {
    // Arrange
    const appt = anAppointment(30);
    await appointments.save(appt);

    // Act
    const result = await useCase.execute(appt.id);

    // Assert
    expect(result).toEqual({ success: true, data: { blocked: false } });
    expect(appointments.rows.get(appt.id)?.status).toBe('no_show');
    expect(restrictions.blockedUntil.size).toBe(0);
  });

  it('blocks online booking for 30 days on the third strike within 90 days', async () => {
    // Arrange
    await appointments.save(anAppointment(10 * 24 * 60, 'no_show'));
    await appointments.save(anAppointment(60 * 24 * 60, 'no_show'));
    const today = anAppointment(20);
    await appointments.save(today);

    // Act
    const result = await useCase.execute(today.id);

    // Assert
    expect(result).toEqual({ success: true, data: { blocked: true } });
    expect(restrictions.blockedUntil.get('p-1')).toEqual(new Date(NOW.getTime() + 30 * DAY));
  });

  it('ignores no-shows older than 90 days', async () => {
    // Arrange
    await appointments.save(anAppointment(91 * 24 * 60, 'no_show'));
    await appointments.save(anAppointment(5 * 24 * 60, 'no_show'));
    const today = anAppointment(20);
    await appointments.save(today);

    // Act
    const result = await useCase.execute(today.id);

    // Assert
    expect(result).toEqual({ success: true, data: { blocked: false } });
  });

  it('refuses within the 15-minute grace period', async () => {
    // Arrange
    const appt = anAppointment(14);
    await appointments.save(appt);

    // Act
    const result = await useCase.execute(appt.id);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'GracePeriod', minutesLate: 14 });
    expect(appointments.rows.get(appt.id)?.status).toBe('booked');
  });

  it('refuses an appointment that is not booked', async () => {
    // Arrange
    const appt = anAppointment(60, 'attended');
    await appointments.save(appt);

    // Act
    const result = await useCase.execute(appt.id);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'NotBooked', status: 'attended' });
  });

  it('fails with AppointmentNotFound', async () => {
    // Arrange: empty schedule

    // Act
    const result = await useCase.execute('missing');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AppointmentNotFound');
  });
});
