// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Entities/User.ts
export class User {
  constructor(
    public id: string,
    public email: string,
    private _passwordHash: string
  ) {}

  get passwordHash(): string {
    return this._passwordHash;
  }

  updatePassword(newPasswordHash: string): void {
    this._passwordHash = newPasswordHash;
  }
}

// Application/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  save(user: User): Promise<void>;
}

// Application/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, err } from '../Result';
import { DomainError, InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';
import { User } from '../../Domain/Entities/User';
import { IUserRepository } from '../Ports/IUserRepository';
import { IPasswordHasher } from '../Ports/IPasswordHasher';

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(
    userId: string,
    currentPassword: string,
    newPassword: string
  ): Promise<Result<void, DomainError>> {
    // Validate input
    if (!userId || !currentPassword || !newPassword) {
      return err(new InvalidPasswordError('All fields are required'));
    }

    // Business rule: new password cannot be empty
    if (newPassword.trim().length === 0) {
      return err(new InvalidPasswordError('New password cannot be empty'));
    }

    // Business rule: new password cannot equal old password
    if (currentPassword === newPassword) {
      return err(new PasswordMismatchError('New password cannot be the same as current password'));
    }

    // Fetch user
    const user = await this.userRepository.findById(userId);
    if (!user) {
      return err(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(currentPassword, user.passwordHash);
    if (!isPasswordValid) {
      return err(new PasswordMismatchError('Current password is incorrect'));
    }

    // Hash new password
    const newHashedPassword = await this.passwordHasher.hash(newPassword);

    // Update user password
    user.updatePassword(newHashedPassword);
    await this.userRepository.save(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends Error> = { success: true; value: T } | { success: false; error: E };

export const ok = <T>(value: T): Result<T, never> => ({ success: true, value });

export const err = <E extends Error>(error: E): Result<never, E> => ({ success: false, error });
```

This implementation follows Clean Architecture principles with:

1. **Dependency Rule Enforcement**: The use case depends only on ports (interfaces) from the application layer, not concrete implementations
2. **Domain Error Handling**: Uses typed domain errors for specific business rule violations
3. **Result Pattern**: Returns `Result<void, DomainError>` as required
4. **Business Rules**:
   - New password cannot equal old password
   - All fields are required
   - New password cannot be empty
   - Current password must be valid
5. **SOLID Principles**:
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Interfaces can be substituted with implementations
   - Interface Segregation: Small, focused interfaces
   - Dependency Inversion: High-level modules depend on abstractions

The use case enforces all business rules through validation before performing any operations, ensuring data integrity and following the dependency rule that domain/application layers don't depend on infrastructure.

