Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import express from 'express';
import { Pool } from 'pg';

const pool = new Pool();
export const router = express.Router();

router.post('/prescriptions/:id/refill', async (req, res) => {
  const { rows } = await pool.query('SELECT * FROM prescriptions WHERE id = $1', [req.params.id]);
  const rx = rows[0];
  if (!rx) return res.status(404).send('Not found');
  if (rx.refills_left <= 0) return res.status(409).send('No refills left');
  if (new Date(rx.expires_at) < new Date()) return res.status(410).send('Prescription expired');
  const daysSinceLast = (Date.now() - new Date(rx.last_filled_at).getTime()) / 86400000;
  if (daysSinceLast < rx.days_supply * 0.75) return res.status(429).send('Too early to refill');
  await pool.query(
    'UPDATE prescriptions SET refills_left = refills_left - 1, last_filled_at = now() WHERE id = $1',
    [rx.id],
  );
  res.json({ refillsLeft: rx.refills_left - 1 });
});

```

### Architectural Flaws in Original Code
1. **Clinical rules in a router:** refill count, expiry and the 75%-of-supply waiting period are only reachable through Express.
2. **SQL rows as the model:** `rx.refills_left` and friends are untyped database columns.
3. **Two clocks:** `new Date()` in the handler and `now()` in SQL can disagree.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Prescription.ts`)
```typescript
import { Result } from '../shared/Result';

export type RefillError =
  | { kind: 'NotFound' }
  | { kind: 'NoRefillsLeft' }
  | { kind: 'Expired' }
  | { kind: 'TooEarly'; earliest: Date };

export class Prescription {
  static readonly EARLY_REFILL_RATIO = 0.75;

  constructor(
    readonly id: string,
    private refillsLeft: number,
    readonly expiresAt: Date,
    private lastFilledAt: Date | null, // null: never filled
    readonly daysSupply: number,
  ) {}

  get remainingRefills(): number { return this.refillsLeft; }
  get lastFilled(): Date | null { return this.lastFilledAt; }

  refill(now: Date): Result<void, RefillError> {
    if (this.refillsLeft <= 0) return Result.fail({ kind: 'NoRefillsLeft' });
    if (this.expiresAt < now) return Result.fail({ kind: 'Expired' });
    if (this.lastFilledAt) {
      const waitMs = this.daysSupply * Prescription.EARLY_REFILL_RATIO * 86_400_000;
      const earliest = new Date(this.lastFilledAt.getTime() + waitMs);
      if (now < earliest) return Result.fail({ kind: 'TooEarly', earliest });
    }
    this.refillsLeft -= 1;
    this.lastFilledAt = now;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/RefillPrescription.ts`)
```typescript
import { Result } from '../shared/Result';
import { Prescription, RefillError } from '../domain/Prescription';

export interface PrescriptionRepository {
  findById(id: string): Promise<Prescription | null>;
  /** Persists a refill only if a refill is still available; false if another request took it first. */
  recordRefill(prescription: Prescription): Promise<boolean>;
}

export class RefillPrescription {
  constructor(private readonly prescriptions: PrescriptionRepository, private readonly now: () => Date) {}

  async execute(id: string): Promise<Result<number, RefillError>> {
    const rx = await this.prescriptions.findById(id);
    if (!rx) return Result.fail({ kind: 'NotFound' });
    const refilled = rx.refill(this.now());
    if (!refilled.success) return refilled;
    if (!(await this.prescriptions.recordRefill(rx))) return Result.fail({ kind: 'NoRefillsLeft' });
    return Result.ok(rx.remainingRefills);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PgPrescriptionRepository.ts`)
```typescript
import { Pool } from 'pg';
import { Prescription } from '../domain/Prescription';
import { PrescriptionRepository } from '../application/RefillPrescription';

interface PrescriptionRow {
  id: string; refills_left: number; expires_at: Date; last_filled_at: Date | null; days_supply: number;
}

export class PgPrescriptionRepository implements PrescriptionRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Prescription | null> {
    const { rows } = await this.pool.query<PrescriptionRow>('SELECT * FROM prescriptions WHERE id = $1', [id]);
    const r = rows[0];
    return r ? new Prescription(r.id, r.refills_left, r.expires_at, r.last_filled_at, r.days_supply) : null;
  }

  async recordRefill(rx: Prescription): Promise<boolean> {
    // Decrement in SQL, guarded, so two concurrent refills cannot both succeed on the last one.
    const { rowCount } = await this.pool.query(
      'UPDATE prescriptions SET refills_left = refills_left - 1, last_filled_at = $2 WHERE id = $1 AND refills_left > 0',
      [rx.id, rx.lastFilled]);
    return rowCount === 1;
  }
}
```
The domain decides whether a refill is allowed; the repository keeps the original atomic `refills_left - 1` update, so the rule cannot be bypassed by a race.

#### 4. Presentation Layer (`src/http/prescriptionRouter.ts`)
```typescript
import express from 'express';
import { RefillError } from '../domain/Prescription';
import { RefillPrescription } from '../application/RefillPrescription';

function toHttp(error: RefillError): [number, string] {
  switch (error.kind) {
    case 'NotFound': return [404, 'Not found'];
    case 'NoRefillsLeft': return [409, 'No refills left'];
    case 'Expired': return [410, 'Prescription expired'];
    case 'TooEarly': return [429, 'Too early to refill'];
  }
}

export function prescriptionRouter(refill: RefillPrescription): express.Router {
  const router = express.Router();
  router.post('/prescriptions/:id/refill', async (req, res) => {
    const result = await refill.execute(req.params.id);
    if (result.success) return res.json({ refillsLeft: result.data });
    const [status, message] = toHttp(result.error);
    res.status(status).send(message);
  });
  return router;
}
```
The router is now built from an injected use case; the `Pool` is created only in the composition root.

Critique this class against SRP and the rest of SOLID, then split it properly:

```typescript
class UserManager {
  register(name: string, password: string) {
    if (password.length < 8) throw new Error('Weak password');
    const hash = crypto.createHash('sha256').update(password).digest('hex');
    db.run('INSERT INTO users (name, hash) VALUES (?, ?)', [name, hash]);
    smtp.send('welcome@app.com', name, 'Welcome!');
    console.log('registered ' + name);
  }
}
```

### SOLID Critique
- **SRP (violated):** `UserManager` changes for four reasons: password policy, hashing, persistence and notification.
- **DIP (violated):** it uses `db`, `smtp` and `crypto` directly, so none of them can be replaced in tests.
- **Security smell:** plain SHA-256 is not a password hashing scheme. It needs a slow, salted algorithm, and being behind an interface makes that fix local.

---

### Refactoring: one responsibility per collaborator
```typescript
export class PasswordPolicy {
  assertValid(password: string): void {
    if (password.length < 8) throw new Error('Weak password');
  }
}

export interface PasswordHasher { hash(password: string): Promise<string> }
export interface UserStore { add(name: string, hash: string): Promise<void> }
export interface WelcomeNotifier { welcome(name: string): Promise<void> }

export class RegisterUser {
  constructor(
    private readonly policy: PasswordPolicy,
    private readonly hasher: PasswordHasher,
    private readonly users: UserStore,
    private readonly notifier: WelcomeNotifier,
  ) {}

  async execute(name: string, password: string): Promise<void> {
    this.policy.assertValid(password);
    await this.users.add(name, await this.hasher.hash(password));
    await this.notifier.welcome(name);
  }
}
```

`RegisterUser` only orchestrates. Each rule or side effect has one reason to change, can be faked in tests, and the hashing algorithm can be upgraded behind `PasswordHasher` without touching the use case.

### Domain layer
The campaign is the aggregate: it knows its schedule, its creator, its backers and its tiers' stock, so it validates and records the pledge in one consistent step.

```typescript
import { Result } from '../shared/Result';

export const MIN_PLEDGE_CENTS = 500;

export interface RewardTier {
  readonly id: string;
  readonly minCents: number;
  readonly remaining: number | null; // null = unlimited
}

export interface Pledge {
  readonly id: string;
  readonly backerId: string;
  readonly amountCents: number;
  readonly tierId: string | null;
  readonly authorizationId: string;
}

export type PledgeError =
  | { kind: 'CampaignNotFound' }
  | { kind: 'NotLive' }
  | { kind: 'BelowMinimum'; minCents: number }
  | { kind: 'UnknownTier' }
  | { kind: 'TierSoldOut' }
  | { kind: 'OwnCampaign' }
  | { kind: 'AlreadyPledged' }
  | { kind: 'AuthorizationDeclined'; reason: string }
  | { kind: 'NotSaved' };

export class Campaign {
  constructor(
    readonly id: string,
    readonly creatorId: string,
    readonly launchAt: Date,
    readonly deadline: Date,
    readonly cancelled: boolean,
    private readonly tiers: RewardTier[],
    private readonly pledges: Pledge[],
  ) {}

  get allPledges(): readonly Pledge[] { return this.pledges; }

  canAccept(backerId: string, amountCents: number, tierId: string | null, now: Date): Result<void, PledgeError> {
    if (this.cancelled || now < this.launchAt || now >= this.deadline) return Result.fail({ kind: 'NotLive' });
    if (backerId === this.creatorId) return Result.fail({ kind: 'OwnCampaign' });
    if (this.pledges.some((p) => p.backerId === backerId)) return Result.fail({ kind: 'AlreadyPledged' });
    if (amountCents < MIN_PLEDGE_CENTS) return Result.fail({ kind: 'BelowMinimum', minCents: MIN_PLEDGE_CENTS });
    if (tierId === null) return Result.ok(undefined);

    const tier = this.tiers.find((t) => t.id === tierId);
    if (!tier) return Result.fail({ kind: 'UnknownTier' });
    if (amountCents < tier.minCents) return Result.fail({ kind: 'BelowMinimum', minCents: tier.minCents });
    if (tier.remaining !== null && tier.remaining <= 0) return Result.fail({ kind: 'TierSoldOut' });
    return Result.ok(undefined);
  }

  record(pledge: Pledge): void {
    const index = this.tiers.findIndex((t) => t.id === pledge.tierId);
    const tier = this.tiers[index];
    if (tier && tier.remaining !== null) this.tiers[index] = { ...tier, remaining: tier.remaining - 1 };
    this.pledges.push(pledge);
  }
}
```
Validation and recording are split because the card authorization has to happen between them: we must not touch the card for an invalid pledge, nor record a pledge whose authorization failed.

### Application layer
```typescript
import { Result } from '../shared/Result';
import { Campaign, Pledge, PledgeError } from '../domain/Campaign';

export interface CampaignRepository {
  findById(id: string): Promise<Campaign | null>;
  /** Returns false on a version conflict (someone else changed the campaign meanwhile). */
  save(campaign: Campaign): Promise<boolean>;
}

export type Authorization = { approved: true; authorizationId: string } | { approved: false; reason: string };

export interface CardAuthorizer {
  authorize(backerId: string, amountCents: number, reference: string): Promise<Authorization>;
  release(authorizationId: string): Promise<void>;
}

export interface PledgeInput {
  readonly campaignId: string;
  readonly backerId: string;
  readonly amountCents: number;
  readonly tierId: string | null;
}

export class PledgeToCampaign {
  constructor(
    private readonly campaigns: CampaignRepository,
    private readonly cards: CardAuthorizer,
    private readonly now: () => Date,
    private readonly newId: () => string,
  ) {}

  async execute(input: PledgeInput): Promise<Result<Pledge, PledgeError>> {
    const campaign = await this.campaigns.findById(input.campaignId);
    if (!campaign) return Result.fail({ kind: 'CampaignNotFound' });

    const allowed = campaign.canAccept(input.backerId, input.amountCents, input.tierId, this.now());
    if (!allowed.success) return allowed;

    const pledgeId = this.newId();
    const auth = await this.cards.authorize(input.backerId, input.amountCents, pledgeId);
    if (!auth.approved) return Result.fail({ kind: 'AuthorizationDeclined', reason: auth.reason });

    const pledge: Pledge = { id: pledgeId, backerId: input.backerId, amountCents: input.amountCents, tierId: input.tierId, authorizationId: auth.authorizationId };
    campaign.record(pledge);
    const saved = await this.campaigns.save(campaign);
    if (!saved) {
      await this.cards.release(auth.authorizationId);
      return Result.fail({ kind: 'NotSaved' });
    }
    return Result.ok(pledge);
  }
}
```
If saving hits an optimistic-lock conflict (for example someone took the last tier unit in the meantime), the authorization is released so the backer is not left with a hold on their card, and `NotSaved` tells the caller to retry. `CardAuthorizer` is implemented in infrastructure on top of the payment provider's SDK.

