// Domain/ValueObjects/Money.ts

export interface Currency {
  readonly code: string;
  readonly symbol: string;
  readonly decimalPlaces: number;
}

export interface MoneyError {
  readonly type: 'InvalidAmount' | 'CurrencyMismatch' | 'InvalidCurrency';
  readonly message: string;
}

export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: Currency
  ) {}

  public static create(amount: number, currency: Currency): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure({
        type: 'InvalidAmount',
        message: 'Amount must be positive'
      });
    }

    if (!currency || !currency.code) {
      return Result.failure({
        type: 'InvalidCurrency',
        message: 'Invalid currency provided'
      });
    }

    return Result.success(new Money(amount, currency));
  }

  public get amount(): number {
    return this._amount;
  }

  public get currency(): Currency {
    return this._currency;
  }

  public add(other: Money): Result<Money, MoneyError> {
    if (this._currency.code !== other._currency.code) {
      return Result.failure({
        type: 'CurrencyMismatch',
        message: `Cannot add money with different currencies: ${this._currency.code} and ${other._currency.code}`
      });
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  public equals(other: Money): boolean {
    return this._amount === other._amount && this._currency.code === other._currency.code;
  }

  public toString(): string {
    return `${this._currency.symbol}${this._amount.toFixed(this._currency.decimalPlaces)}`;
  }
}

// Result type implementation
export class Result<T, E> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  public static success<T, E>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  public static failure<T, E>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }

  public map<U>(fn: (value: T) => U): Result<U, E> {
    if (this.isSuccess) {
      return Result.success(fn(this.value!));
    }
    return Result.failure(this.error!);
  }

  public bind<U>(fn: (value: T) => Result<U, E>): Result<U, E> {
    if (this.isSuccess) {
      return fn(this.value!);
    }
    return Result.failure(this.error!);
  }
}
```

Write unit tests for this use case. I want each test split into Arrange, Act and Assert, and no real database or mail provider involved:

```typescript
import { Result } from '../shared/Result';

export interface PendingSubscription {
  token: string;
  address: string;
  requestedAt: Date;
  confirmed: boolean;
}

export interface SubscriptionRepository {
  findByToken(token: string): Promise<PendingSubscription | null>;
  save(sub: PendingSubscription): Promise<void>;
}

export interface WelcomeSender {
  sendWelcome(address: string): Promise<void>;
}

export type ConfirmError =
  | { kind: 'UnknownToken' }
  | { kind: 'AlreadyConfirmed' }
  | { kind: 'TokenExpired'; hoursOld: number };

const MAX_AGE_HOURS = 48;

export class ConfirmSubscription {
  constructor(
    private readonly subs: SubscriptionRepository,
    private readonly welcome: WelcomeSender,
    private readonly now: () => Date,
  ) {}

  async execute(token: string): Promise<Result<void, ConfirmError>> {
    const sub = await this.subs.findByToken(token);
    if (!sub) return Result.fail({ kind: 'UnknownToken' });
    if (sub.confirmed) return Result.fail({ kind: 'AlreadyConfirmed' });
    const hoursOld = (this.now().getTime() - sub.requestedAt.getTime()) / 3_600_000;
    if (hoursOld > MAX_AGE_HOURS) return Result.fail({ kind: 'TokenExpired', hoursOld });
    await this.subs.save({ ...sub, confirmed: true });
    await this.welcome.sendWelcome(sub.address);
    return Result.ok(undefined);
  }
}
```

The repository is replaced by an in-memory fake (so the tests can read back what was saved), the welcome sender by a `vi.fn` spy, and the clock is a fixed date so the 48-hour window is deterministic. There is one test for the happy path and one per error kind, plus a boundary test at exactly 48 hours.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import {
  ConfirmSubscription,
  PendingSubscription,
  SubscriptionRepository,
  WelcomeSender,
} from './ConfirmSubscription';

class InMemorySubscriptionRepository implements SubscriptionRepository {
  readonly items = new Map<string, PendingSubscription>();

  async findByToken(token: string): Promise<PendingSubscription | null> {
    return this.items.get(token) ?? null;
  }

  async save(sub: PendingSubscription): Promise<void> {
    this.items.set(sub.token, sub);
  }
}

const NOW = new Date('2024-05-10T12:00:00Z');
const hoursBefore = (h: number): Date => new Date(NOW.getTime() - h * 3_600_000);

describe('ConfirmSubscription', () => {
  let repo: InMemorySubscriptionRepository;
  let sendWelcome: ReturnType<typeof vi.fn<WelcomeSender['sendWelcome']>>;
  let useCase: ConfirmSubscription;

  beforeEach(() => {
    repo = new InMemorySubscriptionRepository();
    sendWelcome = vi.fn<WelcomeSender['sendWelcome']>().mockResolvedValue(undefined);
    useCase = new ConfirmSubscription(repo, { sendWelcome }, () => NOW);
  });

  const givenPending = (overrides: Partial<PendingSubscription> = {}): PendingSubscription => {
    const sub: PendingSubscription = {
      token: 'tok-1',
      address: 'reader@example.com',
      requestedAt: hoursBefore(2),
      confirmed: false,
      ...overrides,
    };
    repo.items.set(sub.token, sub);
    return sub;
  };

  it('confirms a fresh subscription and sends the welcome message', async () => {
    // Arrange
    givenPending();

    // Act
    const result = await useCase.execute('tok-1');

    // Assert
    expect(result.success).toBe(true);
    expect(repo.items.get('tok-1')?.confirmed).toBe(true);
    expect(sendWelcome).toHaveBeenCalledWith('reader@example.com');
  });

  it('still accepts a token that is exactly 48 hours old', async () => {
    // Arrange
    givenPending({ requestedAt: hoursBefore(48) });

    // Act
    const result = await useCase.execute('tok-1');

    // Assert
    expect(result.success).toBe(true);
  });

  it('fails with UnknownToken when no subscription matches', async () => {
    // Arrange: repository is empty

    // Act
    const result = await useCase.execute('missing');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('UnknownToken');
    expect(sendWelcome).not.toHaveBeenCalled();
  });

  it('fails with AlreadyConfirmed and does not send a second welcome', async () => {
    // Arrange
    givenPending({ confirmed: true });

    // Act
    const result = await useCase.execute('tok-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AlreadyConfirmed');
    expect(sendWelcome).not.toHaveBeenCalled();
  });

  it('fails with TokenExpired after 48 hours and leaves the record unconfirmed', async () => {
    // Arrange
    givenPending({ requestedAt: hoursBefore(49) });

    // Act
    const result = await useCase.execute('tok-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'TokenExpired', hoursOld: 49 });
    expect(repo.items.get('tok-1')?.confirmed).toBe(false);
    expect(sendWelcome).not.toHaveBeenCalled();
  });
});
```

Apply Clean Architecture to this Cloudflare Worker (Hono + KV) that creates short links:

```typescript
const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const { url, alias, ttlDays } = await c.req.json();
  let target: URL;
  try { target = new URL(url); } catch { return c.json({ error: 'Invalid URL' }, 400); }
  if (target.protocol !== 'https:') return c.json({ error: 'Only https links' }, 400);
  const reserved = ['admin', 'api', 'links'];
  const slug = alias ?? Math.random().toString(36).slice(2, 8);
  if (!/^[a-z0-9-]{3,32}$/.test(slug) || reserved.includes(slug)) {
    return c.json({ error: 'Invalid alias' }, 400);
  }
  if (await c.env.LINKS.get(slug)) return c.json({ error: 'Alias taken' }, 409);
  const days = Math.min(ttlDays ?? 30, 365);
  await c.env.LINKS.put(slug, target.toString(), { expirationTtl: days * 86400 });
  return c.json({ slug, expiresInDays: days }, 201);
});
```

### Architectural Flaws in Original Code
1. **Link policy tied to the Worker runtime:** https-only, alias format, reserved words and the TTL cap need Hono and KV to run.
2. **Randomness is hidden:** `Math.random()` inside the handler makes generated slugs untestable.
3. **Untyped body:** `c.req.json()` is destructured without validation.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/ShortLink.ts`)
```typescript
import { Result } from '../shared/Result';

export type LinkError =
  | { kind: 'InvalidUrl' }
  | { kind: 'InsecureUrl' }
  | { kind: 'InvalidAlias' }
  | { kind: 'AliasTaken' };

const RESERVED = new Set(['admin', 'api', 'links']);
const SLUG = /^[a-z0-9-]{3,32}$/;
export const DEFAULT_TTL_DAYS = 30;
export const MAX_TTL_DAYS = 365;

export interface ShortLink {
  readonly slug: string;
  readonly target: string;
  readonly ttlDays: number;
}

export function createShortLink(input: { url: string; slug: string; ttlDays?: number }): Result<ShortLink, LinkError> {
  let target: URL;
  try {
    target = new URL(input.url);
  } catch {
    return Result.fail({ kind: 'InvalidUrl' });
  }
  if (target.protocol !== 'https:') return Result.fail({ kind: 'InsecureUrl' });
  if (!SLUG.test(input.slug) || RESERVED.has(input.slug)) return Result.fail({ kind: 'InvalidAlias' });
  const ttlDays = Math.min(input.ttlDays ?? DEFAULT_TTL_DAYS, MAX_TTL_DAYS);
  return Result.ok({ slug: input.slug, target: target.toString(), ttlDays });
}
```

#### 2. Application Layer (`src/application/ShortenLink.ts`)
```typescript
import { Result } from '../shared/Result';
import { LinkError, ShortLink, createShortLink } from '../domain/ShortLink';

export interface LinkStore {
  exists(slug: string): Promise<boolean>;
  save(link: ShortLink): Promise<void>;
}

export interface SlugGenerator {
  next(): string;
}

export class ShortenLink {
  constructor(private readonly links: LinkStore, private readonly slugs: SlugGenerator) {}

  async execute(input: { url: string; alias?: string; ttlDays?: number }): Promise<Result<ShortLink, LinkError>> {
    const link = createShortLink({ url: input.url, slug: input.alias ?? this.slugs.next(), ttlDays: input.ttlDays });
    if (!link.success) return link;
    if (await this.links.exists(link.data.slug)) return Result.fail({ kind: 'AliasTaken' });
    await this.links.save(link.data);
    return link;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/kv.ts`)
```typescript
import { ShortLink } from '../domain/ShortLink';
import { LinkStore, SlugGenerator } from '../application/ShortenLink';

export class KvLinkStore implements LinkStore {
  constructor(private readonly kv: KVNamespace) {}

  async exists(slug: string): Promise<boolean> {
    return (await this.kv.get(slug)) !== null;
  }

  async save(link: ShortLink): Promise<void> {
    await this.kv.put(link.slug, link.target, { expirationTtl: link.ttlDays * 86_400 });
  }
}

export const randomSlugs: SlugGenerator = { next: () => Math.random().toString(36).slice(2, 8) };
```

#### 4. Presentation Layer (`src/worker.ts`)
```typescript
function toHttp(error: LinkError): [400 | 409, string] {
  switch (error.kind) {
    case 'InvalidUrl': return [400, 'Invalid URL'];
    case 'InsecureUrl': return [400, 'Only https links'];
    case 'InvalidAlias': return [400, 'Invalid alias'];
    case 'AliasTaken': return [409, 'Alias taken'];
  }
}

const app = new Hono<{ Bindings: { LINKS: KVNamespace } }>();

app.post('/links', async (c) => {
  const body = (await c.req.json()) as { url?: unknown; alias?: unknown; ttlDays?: unknown };
  if (typeof body.url !== 'string') return c.json({ error: 'Invalid URL' }, 400);

  const shorten = new ShortenLink(new KvLinkStore(c.env.LINKS), randomSlugs);
  const result = await shorten.execute({
    url: body.url,
    alias: typeof body.alias === 'string' ? body.alias : undefined,
    ttlDays: typeof body.ttlDays === 'number' ? body.ttlDays : undefined,
  });
  if (result.success) return c.json({ slug: result.data.slug, expiresInDays: result.data.ttlDays }, 201);
  const [status, error] = toHttp(result.error);
  return c.json({ error }, status);
});
```

```typescript
// Domain layer - Interfaces and types

/**
 * Domain Event interface - represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly id: string;
  readonly occurredAt: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  /**
   * Publishes a domain event
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>>;
}

// Domain Errors
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventPublishingError";
  }
}

// Application layer - Use case example
export interface IEventPublishingUseCase {
  execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>>;
}

// Application layer implementation
export class EventPublishingUseCase implements IEventPublishingUseCase {
  constructor(private readonly eventPublisher: IEventPublisher) {}

  async execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    return await this.eventPublisher.publish(event);
  }
}

// Infrastructure layer - In-memory test double adapter
export class InMemoryEventPublisher implements IEventPublisher {
  private readonly events: IDomainEvent[] = [];
  private readonly subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event to in-memory storage
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      this.events.push(event);

      // Notify subscribers
      this.subscribers.forEach(subscriber => subscriber(event));

      return Result.success<void>(undefined);
    } catch (error) {
      return Result.failure<EventPublishingError>(
        new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`)
      );
    }
  }

  /**
   * Gets all published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clears all published events
   */
  clearEvents(): void {
    this.events.length = 0;
  }

  /**
   * Subscribe to events
   */
  subscribe(callback: (event: IDomainEvent) => void): void {
    this.subscribers.push(callback);
  }

  /**
   * Unsubscribe from events
   */
  unsubscribe(callback: (event: IDomainEvent) => void): void {
    const index = this.subscribers.indexOf(callback);
    if (index > -1) {
      this.subscribers.splice(index, 1);
    }
  }
}

// Result type implementation
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
