```typescript
// Domain/Entities/Subscription.ts
export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly status: SubscriptionStatus,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      customerId,
      startDate,
      endDate,
      SubscriptionStatus.Active,
      plan
    );
  }

  static from(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    status: SubscriptionStatus,
    plan: string
  ): Subscription {
    return new Subscription(id, customerId, startDate, endDate, status, plan);
  }

  isExpired(): boolean {
    return new Date() > this.endDate;
  }

  isActive(): boolean {
    return this.status === SubscriptionStatus.Active;
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.customerId,
      this.startDate,
      this.endDate,
      SubscriptionStatus.Cancelled,
      this.plan
    );
  }
}

export enum SubscriptionStatus {
  Active = 'ACTIVE',
  Cancelled = 'CANCELLED',
  Expired = 'EXPIRED'
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionError';
  }
}

export class SubscriptionAlreadyExpiredError extends SubscriptionError {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, Ok, Err } from '../Types/Result';
import { Subscription } from '../../Domain/Entities/Subscription';
import { SubscriptionError, SubscriptionAlreadyExpiredError } from '../../Domain/Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return Err(new SubscriptionNotFoundError(subscriptionId));
      }

      const cancelledSubscription = subscription.cancel();

      await this.subscriptionRepository.save(cancelledSubscription);

      return Ok(cancelledSubscription);
    } catch (error) {
      if (error instanceof SubscriptionAlreadyExpiredError) {
        return Err(error);
      }
      return Err(new CancelSubscriptionFailedError());
    }
  }
}

// Domain/Errors/SubscriptionNotFoundError.ts
export class SubscriptionNotFoundError extends SubscriptionError {
  constructor(subscriptionId: string) {
    super(`Subscription with ID ${subscriptionId} not found`);
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/Errors/CancelSubscriptionFailedError.ts
export class CancelSubscriptionFailedError extends SubscriptionError {
  constructor() {
    super('Failed to cancel subscription');
    this.name = 'CancelSubscriptionFailedError';
  }
}

// Application/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: `Subscription` contains only business logic and data, with no dependencies on external frameworks
2. **Invariant Validation**: The `cancel()` method validates that subscriptions cannot be cancelled if they're already expired
3. **Result Pattern**: Use cases return `Result<Subscription, SubscriptionError>` to handle success/failure cases
4. **Typed Domain Errors**: Specific error types for different failure scenarios
5. **Dependency Rule Compliance**: Domain layer (entities, errors) has no dependencies on infrastructure or external libraries
6. **SOLID Principles**: 
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: Error inheritance maintains contract
   - Interface Segregation: Clear repository interface
   - Dependency Inversion: Use cases depend on abstractions

The `CancelSubscriptionUseCase` properly handles the invariant rule by checking if the subscription is expired before attempting cancellation, returning appropriate error types through the Result pattern.

This release CLI decides the next version from git commits. Refactor it so the versioning rules are independent of git, yargs and the filesystem:

```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean' }).parseSync();
const git = simpleGit();
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
const lastTag = (await git.tags()).latest ?? 'v0.0.0';
const log = await git.log({ from: lastTag, to: 'HEAD' });
let bump = 'none';
for (const c of log.all) {
  if (/BREAKING CHANGE/.test(c.body) || /^\w+(\(.+\))?!:/.test(c.message)) { bump = 'major'; break; }
  if (/^feat(\(.+\))?:/.test(c.message)) bump = 'minor';
  else if (/^fix(\(.+\))?:/.test(c.message) && bump === 'none') bump = 'patch';
}
if (bump === 'none') { console.log('Nothing to release'); process.exit(0); }
const [maj, min, pat] = pkg.version.split('.').map(Number);
const next = bump === 'major' ? `${maj + 1}.0.0` : bump === 'minor' ? `${maj}.${min + 1}.0` : `${maj}.${min}.${pat + 1}`;
if (!argv['dry-run']) {
  pkg.version = next;
  fs.writeFileSync('package.json', JSON.stringify(pkg, null, 2) + '\n');
  await git.addTag(`v${next}`);
}
console.log(`Next version: ${next}`);
```

### Architectural Flaws in Original Code
1. **Versioning policy in a script body:** the Conventional Commits rules cannot be tested without a git repository.
2. **Tooling everywhere:** `yargs`, `simple-git` and `fs` are used in the same flow that decides the bump.
3. **`process.exit` in the middle of logic** makes the flow impossible to reuse from another command.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/version.ts`)
```typescript
export type Bump = 'none' | 'patch' | 'minor' | 'major';

export interface Commit {
  readonly subject: string;
  readonly body: string;
}

const RANK: { readonly [B in Bump]: number } = { none: 0, patch: 1, minor: 2, major: 3 };

export function bumpFor(commit: Commit): Bump {
  if (/BREAKING CHANGE/.test(commit.body) || /^\w+(\(.+\))?!:/.test(commit.subject)) return 'major';
  if (/^feat(\(.+\))?:/.test(commit.subject)) return 'minor';
  if (/^fix(\(.+\))?:/.test(commit.subject)) return 'patch';
  return 'none';
}

export function releaseBump(commits: readonly Commit[]): Bump {
  return commits.map(bumpFor).reduce<Bump>((a, b) => (RANK[b] > RANK[a] ? b : a), 'none');
}

export function nextVersion(current: string, bump: Exclude<Bump, 'none'>): string {
  const [major, minor, patch] = current.split('.').map(Number);
  if (bump === 'major') return `${major + 1}.0.0`;
  if (bump === 'minor') return `${major}.${minor + 1}.0`;
  return `${major}.${minor}.${patch + 1}`;
}
```

#### 2. Application Layer (`src/application/PrepareRelease.ts`)
```typescript
import { Result } from '../shared/Result';
import { Commit, nextVersion, releaseBump } from '../domain/version';

export type ReleaseError = { kind: 'NothingToRelease' };

export interface Repository {
  latestTag(): Promise<string | null>;
  commitsSince(tag: string): Promise<Commit[]>;
  tag(name: string): Promise<void>;
}

export interface Manifest {
  currentVersion(): Promise<string>;
  setVersion(version: string): Promise<void>;
}

export class PrepareRelease {
  constructor(private readonly repo: Repository, private readonly manifest: Manifest) {}

  async execute(options: { dryRun: boolean }): Promise<Result<string, ReleaseError>> {
    const since = (await this.repo.latestTag()) ?? 'v0.0.0';
    const bump = releaseBump(await this.repo.commitsSince(since));
    if (bump === 'none') return Result.fail({ kind: 'NothingToRelease' });

    const next = nextVersion(await this.manifest.currentVersion(), bump);
    if (!options.dryRun) {
      await this.manifest.setVersion(next);
      await this.repo.tag(`v${next}`);
    }
    return Result.ok(next);
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { readFile, writeFile } from 'node:fs/promises';
import { SimpleGit } from 'simple-git';
import { Commit } from '../domain/version';
import { Manifest, Repository } from '../application/PrepareRelease';

export class SimpleGitRepository implements Repository {
  constructor(private readonly git: SimpleGit) {}
  async latestTag(): Promise<string | null> { return (await this.git.tags()).latest ?? null; }
  async commitsSince(tag: string): Promise<Commit[]> {
    const log = await this.git.log({ from: tag, to: 'HEAD' });
    return log.all.map((c) => ({ subject: c.message, body: c.body }));
  }
  async tag(name: string): Promise<void> { await this.git.addTag(name); }
}

export class PackageJsonManifest implements Manifest {
  constructor(private readonly path = 'package.json') {}
  async currentVersion(): Promise<string> {
    return (JSON.parse(await readFile(this.path, 'utf8')) as { version: string }).version;
  }
  async setVersion(version: string): Promise<void> {
    const pkg = JSON.parse(await readFile(this.path, 'utf8')) as Record<string, unknown>;
    await writeFile(this.path, JSON.stringify({ ...pkg, version }, null, 2) + '\n');
  }
}
```

#### 4. CLI Entry Point (`src/cli.ts`)
```typescript
const argv = yargs(hideBin(process.argv)).option('dry-run', { type: 'boolean', default: false }).parseSync();
const release = new PrepareRelease(new SimpleGitRepository(simpleGit()), new PackageJsonManifest());
const result = await release.execute({ dryRun: argv['dry-run'] });
console.log(result.success ? `Next version: ${result.data}` : 'Nothing to release');
```

The invoice download route launches Puppeteer itself. Put PDF generation behind a port, with Puppeteer as the adapter:

```typescript
app.get('/invoices/:id.pdf', async (req, res) => {
  const inv = await db.invoice.findUnique({ where: { id: req.params.id }, include: { lines: true } });
  if (!inv) return res.sendStatus(404);
  const html = `<h1>Invoice ${inv.number}</h1><table>${inv.lines
    .map((l) => `<tr><td>${l.description}</td><td>${(l.totalCents / 100).toFixed(2)}</td></tr>`)
    .join('')}</table><p>Total: ${(inv.totalCents / 100).toFixed(2)} ${inv.currency}</p>`;
  const browser = await puppeteer.launch();
  const page = await browser.newPage();
  await page.setContent(html);
  const pdf = await page.pdf({ format: 'A4' });
  await browser.close();
  res.type('application/pdf').send(pdf);
});
```

### Issues in the route
1. **A browser per request.** `puppeteer.launch()` costs hundreds of milliseconds and ~100 MB; under load the server runs out of memory.
2. **Leaked browsers.** If `setContent` or `pdf` throws, `browser.close()` never runs and a Chromium process is orphaned.
3. **HTML injection.** `l.description` is interpolated unescaped; a line containing `<script>` runs inside the headless browser.
4. **Presentation rules mixed with I/O.** Formatting `totalCents / 100` lives in the route, so the PDF and the web view can disagree.

---

### 1. Port (`src/application/ports/InvoicePdfRenderer.ts`)
The port receives a view model already prepared by the application, and returns bytes. It knows nothing of HTML or Chromium.

```typescript
import { Result } from '../shared/Result';

export interface InvoiceLineView {
  readonly description: string;
  readonly amount: string; // already formatted, e.g. "1,250.00"
}

export interface InvoiceView {
  readonly number: string;
  readonly lines: readonly InvoiceLineView[];
  readonly total: string;
  readonly currency: string;
}

export type PdfError = { kind: 'RenderFailed'; detail: string } | { kind: 'Timeout'; afterMs: number };

export interface InvoicePdfRenderer {
  render(invoice: InvoiceView): Promise<Result<Uint8Array, PdfError>>;
}

export function formatCents(cents: number): string {
  return (cents / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}
```

### 2. Puppeteer adapter (`src/infrastructure/pdf/PuppeteerInvoiceRenderer.ts`)
One browser is launched at startup and shared; each render opens and always closes its own page.

```typescript
import { Browser } from 'puppeteer';

function escapeHtml(text: string): string {
  return text.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

function invoiceHtml(inv: InvoiceView): string {
  const rows = inv.lines
    .map((l) => `<tr><td>${escapeHtml(l.description)}</td><td class="num">${escapeHtml(l.amount)}</td></tr>`)
    .join('');
  return `<!doctype html><html><head><style>td.num{text-align:right}</style></head><body>
    <h1>Invoice ${escapeHtml(inv.number)}</h1><table>${rows}</table>
    <p>Total: ${escapeHtml(inv.total)} ${escapeHtml(inv.currency)}</p></body></html>`;
}

export class PuppeteerInvoiceRenderer implements InvoicePdfRenderer {
  constructor(private readonly browser: Browser, private readonly timeoutMs = 10_000) {}

  async render(invoice: InvoiceView): Promise<Result<Uint8Array, PdfError>> {
    const page = await this.browser.newPage();
    try {
      await page.setJavaScriptEnabled(false);
      await page.setContent(invoiceHtml(invoice), { timeout: this.timeoutMs });
      const pdf: Uint8Array = await page.pdf({ format: 'A4', timeout: this.timeoutMs });
      return Result.ok(pdf);
    } catch (e: unknown) {
      const name = e instanceof Error ? e.name : '';
      return Result.fail(
        name === 'TimeoutError'
          ? { kind: 'Timeout', afterMs: this.timeoutMs }
          : { kind: 'RenderFailed', detail: e instanceof Error ? e.message : String(e) },
      );
    } finally {
      await page.close();
    }
  }
}
```

The template lives inside the adapter on purpose: it is a rendering detail. If you later move to a hosted HTML-to-PDF API, that adapter can reuse `invoiceHtml`, and a LaTeX-based adapter would not use HTML at all; the port is unaffected either way.

### 3. Application function and thin route
```typescript
import { Request, Response } from 'express';

export interface InvoiceRecord {
  readonly number: string;
  readonly currency: string;
  readonly totalCents: number;
  readonly lines: readonly { description: string; totalCents: number }[];
}

export interface InvoiceReader {
  find(id: string): Promise<InvoiceRecord | null>;
}

export type InvoicePdfError = { kind: 'NotFound' } | PdfError;

export async function invoicePdf(id: string, reader: InvoiceReader, renderer: InvoicePdfRenderer): Promise<Result<Uint8Array, InvoicePdfError>> {
  const inv = await reader.find(id);
  if (!inv) return Result.fail({ kind: 'NotFound' });
  return renderer.render({
    number: inv.number,
    currency: inv.currency,
    total: formatCents(inv.totalCents),
    lines: inv.lines.map((l) => ({ description: l.description, amount: formatCents(l.totalCents) })),
  });
}

export function invoicePdfRoute(reader: InvoiceReader, renderer: InvoicePdfRenderer) {
  return async (req: Request, res: Response) => {
    const result = await invoicePdf(req.params.id, reader, renderer);
    if (result.success) return res.type('application/pdf').send(Buffer.from(result.data));
    return res.sendStatus(result.error.kind === 'NotFound' ? 404 : 503);
  };
}
```

For tests, a `FakePdfRenderer` that returns `new TextEncoder().encode(JSON.stringify(invoice))` lets you assert on the exact view model passed to the renderer, without launching Chromium.

```typescript
// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be a positive number");
  }
}

export class InvalidCurrencyError extends MoneyError {
  constructor() {
    super("Currency must be a non-empty string");
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Cannot add money with different currencies");
  }
}

export class MoneyValueObject {
  private constructor(private readonly value: Money) {
    // Private constructor to enforce creation through factory methods
  }

  public static create(amount: number, currency: string): Money {
    if (amount < 0 || !Number.isFinite(amount)) {
      throw new InvalidAmountError();
    }

    if (!currency || typeof currency !== 'string') {
      throw new InvalidCurrencyError();
    }

    return {
      amount,
      currency
    };
  }

  public static createFrom(value: Money): Money {
    return this.create(value.amount, value.currency);
  }

  public add(other: Money): Money {
    if (this.value.currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    const newAmount = this.value.amount + other.amount;
    return {
      amount: newAmount,
      currency: this.value.currency
    };
  }

  public get amount(): number {
    return this.value.amount;
  }

  public get currency(): string {
    return this.value.currency;
  }

  public equals(other: Money): boolean {
    return this.value.amount === other.amount && 
           this.value.currency === other.currency;
  }
}
```

This implementation provides:

1. A clean Value Object `Money` with immutable properties
2. Strong typing with interfaces and dedicated error types
3. Validation for positive amounts and valid currencies
4. Currency checking in the `add` method
5. Proper encapsulation with private constructor and factory methods
6. No dependencies on external libraries or frameworks
7. Use of the Result pattern through exceptions (which is appropriate for value objects)
8. Strict typing with no `any` types
9. Implementation of the Dependency Rule - domain layer is completely independent

The implementation enforces:
- Amounts must be positive finite numbers
- Currency must be a non-empty string
- Addition only works with same currencies
- Value object immutability
- Proper error handling with typed domain errors

Decouple the bidding rules in this Socket.IO handler from MongoDB and the socket layer:

```typescript
io.on('connection', (socket) => {
  socket.on('bid', async ({ auctionId, bidderId, amount }) => {
    const auction = await db.collection('auctions').findOne({ _id: new ObjectId(auctionId) });
    if (!auction) return socket.emit('bid:error', 'Auction not found');
    if (Date.now() > auction.endsAt.getTime()) return socket.emit('bid:error', 'Auction closed');
    if (auction.sellerId === bidderId) return socket.emit('bid:error', 'Sellers cannot bid');
    const current = auction.highestBid ?? auction.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    if (amount < current + step) return socket.emit('bid:error', `Minimum bid is ${current + step}`);
    let endsAt = auction.endsAt;
    if (auction.endsAt.getTime() - Date.now() < 120000) endsAt = new Date(Date.now() + 120000);
    await db.collection('auctions').updateOne({ _id: auction._id },
      { $set: { highestBid: amount, highestBidderId: bidderId, endsAt } });
    io.to(auctionId).emit('bid:accepted', { amount, bidderId, endsAt });
  });
});
```

### Architectural Flaws in Original Code
1. **Auction rules live in a socket listener:** bid increments, seller restrictions and the anti-sniping extension depend on Socket.IO.
2. **Persistence and broadcasting mixed with decisions:** MongoDB updates and room emits are interleaved with validation.
3. **Clock read four times:** `Date.now()` is called repeatedly, so a single bid can see different "now" values.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Auction.ts`)
```typescript
import { Result } from '../shared/Result';

export type BidError =
  | { kind: 'AuctionNotFound' }
  | { kind: 'AuctionClosed' }
  | { kind: 'SellerCannotBid' }
  | { kind: 'BidTooLow'; minimum: number };

export interface AcceptedBid { readonly amount: number; readonly bidderId: string; readonly endsAt: Date; }

export class Auction {
  static readonly EXTENSION_MS = 120_000;

  constructor(
    readonly id: string,
    readonly sellerId: string,
    readonly startingPrice: number,
    private endTime: Date,
    private highest: { amount: number; bidderId: string } | null,
  ) {}

  get endsAt(): Date { return this.endTime; }

  minimumNextBid(): number {
    const current = this.highest?.amount ?? this.startingPrice;
    const step = current < 100 ? 1 : current < 1000 ? 10 : 50;
    return current + step;
  }

  placeBid(bidderId: string, amount: number, now: Date): Result<AcceptedBid, BidError> {
    if (now > this.endTime) return Result.fail({ kind: 'AuctionClosed' });
    if (bidderId === this.sellerId) return Result.fail({ kind: 'SellerCannotBid' });
    const minimum = this.minimumNextBid();
    if (amount < minimum) return Result.fail({ kind: 'BidTooLow', minimum });

    this.highest = { amount, bidderId };
    if (this.endTime.getTime() - now.getTime() < Auction.EXTENSION_MS) {
      this.endTime = new Date(now.getTime() + Auction.EXTENSION_MS); // anti-sniping
    }
    return Result.ok({ amount, bidderId, endsAt: this.endTime });
  }
}
```

#### 2. Application Layer (`src/application/PlaceBid.ts`)
```typescript
import { Result } from '../shared/Result';
import { AcceptedBid, Auction, BidError } from '../domain/Auction';

export interface AuctionRepository {
  findById(id: string): Promise<Auction | null>;
  saveBid(auction: Auction, bid: AcceptedBid): Promise<void>;
}

export interface BidBroadcaster {
  accepted(auctionId: string, bid: AcceptedBid): void;
}

export class PlaceBid {
  constructor(
    private readonly auctions: AuctionRepository,
    private readonly broadcaster: BidBroadcaster,
    private readonly clock: () => Date,
  ) {}

  async execute(auctionId: string, bidderId: string, amount: number): Promise<Result<AcceptedBid, BidError>> {
    const auction = await this.auctions.findById(auctionId);
    if (!auction) return Result.fail({ kind: 'AuctionNotFound' });

    const bid = auction.placeBid(bidderId, amount, this.clock());
    if (!bid.success) return bid;

    await this.auctions.saveBid(auction, bid.data);
    this.broadcaster.accepted(auctionId, bid.data);
    return bid;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
```typescript
import { Collection, ObjectId } from 'mongodb';
import { Server } from 'socket.io';
import { AcceptedBid, Auction } from '../domain/Auction';
import { AuctionRepository, BidBroadcaster } from '../application/PlaceBid';

interface AuctionDoc {
  _id: ObjectId; sellerId: string; startingPrice: number; endsAt: Date;
  highestBid?: number; highestBidderId?: string;
}

export class MongoAuctionRepository implements AuctionRepository {
  constructor(private readonly auctions: Collection<AuctionDoc>) {}

  async findById(id: string): Promise<Auction | null> {
    const d = await this.auctions.findOne({ _id: new ObjectId(id) });
    if (!d) return null;
    const highest = d.highestBid !== undefined && d.highestBidderId !== undefined
      ? { amount: d.highestBid, bidderId: d.highestBidderId } : null;
    return new Auction(id, d.sellerId, d.startingPrice, d.endsAt, highest);
  }

  async saveBid(auction: Auction, bid: AcceptedBid): Promise<void> {
    await this.auctions.updateOne({ _id: new ObjectId(auction.id) },
      { $set: { highestBid: bid.amount, highestBidderId: bid.bidderId, endsAt: bid.endsAt } });
  }
}

export class SocketBidBroadcaster implements BidBroadcaster {
  constructor(private readonly io: Server) {}
  accepted(auctionId: string, bid: AcceptedBid): void { this.io.to(auctionId).emit('bid:accepted', bid); }
}
