// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly customerId: string;
  readonly status: SubscriptionStatus;
  readonly startDate: Date;
  readonly endDate: Date;
  readonly createdAt: Date;
  readonly updatedAt: Date;
}

export type SubscriptionStatus = 'active' | 'cancelled' | 'expired';

export class SubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SubscriptionError';
  }
}

export class SubscriptionAlreadyExpiredError extends SubscriptionError {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from '../Result';
import { Subscription, SubscriptionStatus, SubscriptionAlreadyExpiredError } from '../Entities/Subscription';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionAlreadyExpiredError>>;
}

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, SubscriptionAlreadyExpiredError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        // Note: In a real implementation, you'd want to return a proper error type for missing subscription
        throw new Error('Subscription not found');
      }

      // Invariant rule: Cannot cancel already expired subscription
      if (subscription.status === 'expired') {
        return error(new SubscriptionAlreadyExpiredError());
      }

      // Update subscription status to cancelled
      const updatedSubscription = {
        ...subscription,
        status: 'cancelled' as SubscriptionStatus,
        updatedAt: new Date()
      };

      // Save the updated subscription
      const savedSubscription = await this.subscriptionRepository.save(updatedSubscription);

      return ok(savedSubscription);
    } catch (err) {
      if (err instanceof SubscriptionAlreadyExpiredError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
import { Subscription } from '../Entities/Subscription';

export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<Subscription>;
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value
  };
}

export function error<E>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error
  };
}
