```typescript
import { Result } from '../shared/Result';

export interface RegistryItem {
  sku: string;
  wanted: number;
  purchased: number;
}

export interface Registry {
  id: string;
  eventDate: Date;
  items: RegistryItem[];
}

export interface RegistryRepository {
  load(id: string): Promise<Registry | null>;
  store(registry: Registry): Promise<void>;
}

export interface CoupleNotifier {
  giftPurchased(registryId: string, sku: string, buyerName: string): Promise<void>;
}

export type PurchaseError =
  | { kind: 'RegistryNotFound' }
  | { kind: 'RegistryClosed' }
  | { kind: 'ItemNotListed' }
  | { kind: 'NotEnoughRemaining'; remaining: number };

export class PurchaseRegistryGift {
  constructor(
    private readonly registries: RegistryRepository,
    private readonly notifier: CoupleNotifier,
    private readonly now: () => Date,
  ) {}

  async execute(registryId: string, sku: string, qty: number, buyerName: string): Promise<Result<void, PurchaseError>> {
    const registry = await this.registries.load(registryId);
    if (!registry) return Result.fail({ kind: 'RegistryNotFound' });
    if (this.now() > registry.eventDate) return Result.fail({ kind: 'RegistryClosed' });
    const item = registry.items.find((i) => i.sku === sku);
    if (!item) return Result.fail({ kind: 'ItemNotListed' });
    const remaining = item.wanted - item.purchased;
    if (qty > remaining) return Result.fail({ kind: 'NotEnoughRemaining', remaining });
    const items = registry.items.map((i) => (i.sku === sku ? { ...i, purchased: i.purchased + qty } : i));
    await this.registries.store({ ...registry, items });
    await this.notifier.giftPurchased(registryId, sku, buyerName);
    return Result.ok(undefined);
  }
}
```

The registry fake keeps whole `Registry` values so the tests can check the updated `purchased` count. The notifier is a `vi.fn` because only its call matters. The fixed clock sits a week before the event by default.

