Our carpool matcher needs tests. Write them Arrange-Act-Assert style with vitest: fake offer store, stubbed detour estimator, frozen clock. Check the 15-minute window and the 5 km detour limit at their edges.

```typescript
import { Result } from '../shared/Result';

export interface RideOffer {
  id: string;
  departsAt: Date;
  freeSeats: number;
  riders: string[];
}

export interface RideOffers {
  open(): Promise<RideOffer[]>;
  save(offer: RideOffer): Promise<void>;
}

export interface DetourEstimator {
  extraKm(offerId: string, pickup: string): Promise<number>;
}

export type MatchError = { kind: 'InThePast' } | { kind: 'AlreadyBooked'; offerId: string } | { kind: 'NoMatch' };

const WINDOW_MS = 15 * 60_000;
const MAX_DETOUR_KM = 5;

export class MatchRider {
  constructor(
    private readonly offers: RideOffers,
    private readonly detours: DetourEstimator,
    private readonly now: () => Date,
  ) {}

  async execute(riderId: string, pickup: string, wantedAt: Date): Promise<Result<string, MatchError>> {
    if (wantedAt < this.now()) return Result.fail({ kind: 'InThePast' });
    const open = await this.offers.open();
    const booked = open.find((o) => o.riders.includes(riderId));
    if (booked) return Result.fail({ kind: 'AlreadyBooked', offerId: booked.id });
    const gap = (o: RideOffer): number => Math.abs(o.departsAt.getTime() - wantedAt.getTime());
    for (const offer of [...open].sort((a, b) => gap(a) - gap(b))) {
      if (offer.freeSeats < 1 || gap(offer) > WINDOW_MS) continue;
      if ((await this.detours.extraKm(offer.id, pickup)) > MAX_DETOUR_KM) continue;
      await this.offers.save({ ...offer, freeSeats: offer.freeSeats - 1, riders: [...offer.riders, riderId] });
      return Result.ok(offer.id);
    }
    return Result.fail({ kind: 'NoMatch' });
  }
}
```

Detours are a lookup table keyed by offer id, so each test decides the distance per offer. Requests are made for 08:00 on a day after the frozen clock, and offers are placed in minutes relative to that time.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { MatchRider, DetourEstimator, RideOffer, RideOffers } from './MatchRider';

class InMemoryOffers implements RideOffers {
  readonly offers = new Map<string, RideOffer>();
  async open(): Promise<RideOffer[]> {
    return [...this.offers.values()];
  }
  async save(offer: RideOffer): Promise<void> {
    this.offers.set(offer.id, offer);
  }
}

class TableDetours implements DetourEstimator {
  constructor(private readonly km: Record<string, number>) {}
  async extraKm(offerId: string): Promise<number> {
    return this.km[offerId] ?? 0;
  }
}

const NOW = new Date('2024-02-05T18:00:00Z');
const WANTED = new Date('2024-02-06T08:00:00Z');
const at = (minutes: number): Date => new Date(WANTED.getTime() + minutes * 60_000);
const offer = (id: string, minutes: number, overrides: Partial<RideOffer> = {}): RideOffer => ({
  id, departsAt: at(minutes), freeSeats: 2, riders: [], ...overrides,
});

describe('MatchRider', () => {
  let store: InMemoryOffers;
  const build = (km: Record<string, number> = {}): MatchRider => new MatchRider(store, new TableDetours(km), () => NOW);

  beforeEach(() => {
    store = new InMemoryOffers();
  });

  it('books the closest offer in time and takes one seat', async () => {
    // Arrange
    [offer('far', 12), offer('near', -3)].forEach((o) => store.offers.set(o.id, o));

    // Act
    const result = await build().execute('rider-1', 'Main St', WANTED);

    // Assert
    expect(result).toEqual({ success: true, data: 'near' });
    expect(store.offers.get('near')).toMatchObject({ freeSeats: 1, riders: ['rider-1'] });
  });

  it.each([
    { minutes: 15, km: 5, matched: true },
    { minutes: -15, km: 0, matched: true },
    { minutes: 16, km: 0, matched: false },
    { minutes: 0, km: 5.1, matched: false },
  ])('offer at $minutes min with $km km detour -> matched: $matched', async ({ minutes, km, matched }) => {
    // Arrange
    store.offers.set('o1', offer('o1', minutes));

    // Act
    const result = await build({ o1: km }).execute('rider-1', 'Main St', WANTED);

    // Assert
    expect(result.success).toBe(matched);
    if (!result.success) expect(result.error.kind).toBe('NoMatch');
  });

  it('skips offers without free seats', async () => {
    // Arrange
    store.offers.set('full', offer('full', 0, { freeSeats: 0 }));

    // Act
    const result = await build().execute('rider-1', 'Main St', WANTED);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('NoMatch');
  });

  it('rejects a request for a time before now', async () => {
    // Arrange
    const yesterday = new Date('2024-02-04T08:00:00Z');

    // Act
    const result = await build().execute('rider-1', 'Main St', yesterday);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('InThePast');
  });

  it('rejects a rider who already holds a seat', async () => {
    // Arrange
    store.offers.set('o1', offer('o1', 60, { riders: ['rider-1'] }));
    store.offers.set('o2', offer('o2', 0));

    // Act
    const result = await build().execute('rider-1', 'Main St', WANTED);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'AlreadyBooked', offerId: 'o1' });
  });
});
