Triage is a pure decision over the policy, the claim and its history. The use case gathers those three inputs, persists the decision and tells the assignment queue.

#### 1. Domain (`src/domain/triage.ts`)
```typescript
import { Result } from '../shared/Result';

export interface Policy {
  readonly id: string;
  readonly startsOn: Date;
  readonly endsOn: Date;
  readonly cancelledOn: Date | null;
}

export interface ClaimFacts {
  readonly incidentOn: Date;
  readonly reportedOn: Date;
  readonly amountCents: number;
  readonly priorClaimsLast12Months: number;
}

export type FraudIndicator = 'LateReport' | 'EarlyInPolicy' | 'FrequentClaims';

export type TriageDecision =
  | { queue: 'SPECIAL_INVESTIGATION'; indicators: readonly FraudIndicator[] }
  | { queue: 'FAST_TRACK' }
  | { queue: 'SENIOR_ADJUSTER' }
  | { queue: 'STANDARD' };

export type TriageError =
  | { kind: 'PolicyNotFound' }
  | { kind: 'IncidentInFuture' }
  | { kind: 'PolicyInactive' };

const DAY_MS = 86_400_000;
const daysBetween = (from: Date, to: Date): number => Math.floor((to.getTime() - from.getTime()) / DAY_MS);

export const FAST_TRACK_MAX_CENTS = 100_000;
export const SENIOR_ABOVE_CENTS = 2_500_000;

export function triage(policy: Policy, claim: ClaimFacts): Result<TriageDecision, TriageError> {
  if (claim.incidentOn > claim.reportedOn) return Result.fail({ kind: 'IncidentInFuture' });
  const cancelledBefore = policy.cancelledOn !== null && policy.cancelledOn <= claim.incidentOn;
  if (claim.incidentOn < policy.startsOn || claim.incidentOn > policy.endsOn || cancelledBefore) {
    return Result.fail({ kind: 'PolicyInactive' });
  }

  const indicators: FraudIndicator[] = [];
  if (daysBetween(claim.incidentOn, claim.reportedOn) > 30) indicators.push('LateReport');
  if (daysBetween(policy.startsOn, claim.incidentOn) < 14) indicators.push('EarlyInPolicy');
  if (claim.priorClaimsLast12Months >= 3) indicators.push('FrequentClaims');
  if (indicators.length > 0) return Result.ok({ queue: 'SPECIAL_INVESTIGATION', indicators });

  if (claim.amountCents <= FAST_TRACK_MAX_CENTS) return Result.ok({ queue: 'FAST_TRACK' });
  if (claim.amountCents > SENIOR_ABOVE_CENTS) return Result.ok({ queue: 'SENIOR_ADJUSTER' });
  return Result.ok({ queue: 'STANDARD' });
}
```

#### 2. Application (`src/application/TriageClaim.ts`)
```typescript
import { Result } from '../shared/Result';
import { Policy, TriageDecision, TriageError, triage } from '../domain/triage';

export interface PolicyRepository {
  findById(id: string): Promise<Policy | null>;
}

export interface ClaimRepository {
  countSince(policyId: string, since: Date): Promise<number>;
  saveTriage(claimId: string, decision: TriageDecision): Promise<void>;
}

export interface AssignmentQueue {
  enqueue(claimId: string, decision: TriageDecision): Promise<void>;
}

export interface TriageClaimInput {
  readonly claimId: string;
  readonly policyId: string;
  readonly incidentOn: Date;
  readonly amountCents: number;
}

export class TriageClaim {
  constructor(
    private readonly policies: PolicyRepository,
    private readonly claims: ClaimRepository,
    private readonly queue: AssignmentQueue,
    private readonly now: () => Date,
  ) {}

  async execute(input: TriageClaimInput): Promise<Result<TriageDecision, TriageError>> {
    const policy = await this.policies.findById(input.policyId);
    if (!policy) return Result.fail({ kind: 'PolicyNotFound' });

    const reportedOn = this.now();
    const yearAgo = new Date(reportedOn);
    yearAgo.setFullYear(yearAgo.getFullYear() - 1);

    const decision = triage(policy, {
      incidentOn: input.incidentOn,
      reportedOn,
      amountCents: input.amountCents,
      priorClaimsLast12Months: await this.claims.countSince(policy.id, yearAgo),
    });
    if (!decision.success) return decision;

    await this.claims.saveTriage(input.claimId, decision.data);
    await this.queue.enqueue(input.claimId, decision.data);
    return decision;
  }
}
```

The report date comes from the injected clock, not from the claimant, so "reported 30 days late" cannot be faked by the form. `countSince` must exclude the claim being triaged, otherwise every claim would count itself. A 500.00 claim filed 40 days after the incident goes to special investigation even though it would otherwise be fast-tracked, because indicators are checked first.

### 1. Port (`src/application/ports/Geocoder.ts`)

Route planning needs coordinates and some confidence that they point at a building, not at the centre of a city. The port expresses that in domain terms; neither Google's `location_type` nor Nominatim's `importance` leaks out.

```typescript
import { Result } from '../shared/Result';

export interface Coordinates {
  readonly lat: number;
  readonly lng: number;
}

export type Precision = 'rooftop' | 'street' | 'area';

export interface GeocodedAddress {
  readonly coordinates: Coordinates;
  readonly formatted: string;
  readonly precision: Precision;
}

export type GeocodeError =
  | { kind: 'NoMatch' }
  | { kind: 'QuotaExceeded' }
  | { kind: 'ServiceUnavailable'; detail: string };

export interface Geocoder {
  geocode(address: string, countryCode: string): Promise<Result<GeocodedAddress, GeocodeError>>;
}
```

### 2. Google adapter (`src/infrastructure/geocoding/GoogleGeocoder.ts`)
```typescript
type HttpGet = (url: string) => Promise<{ status: number; json: () => Promise<unknown> }>;

interface GoogleResponse {
  status: string;
  results: { formatted_address: string; geometry: { location: Coordinates; location_type: string } }[];
}

function isGoogleResponse(body: unknown): body is GoogleResponse {
  return typeof body === 'object' && body !== null
    && typeof Reflect.get(body, 'status') === 'string'
    && Array.isArray(Reflect.get(body, 'results'));
}

function googlePrecision(locationType: string): Precision {
  if (locationType === 'ROOFTOP') return 'rooftop';
  if (locationType === 'RANGE_INTERPOLATED') return 'street';
  return 'area';
}

export class GoogleGeocoder implements Geocoder {
  constructor(private readonly get: HttpGet, private readonly apiKey: string) {}

  async geocode(address: string, countryCode: string): Promise<Result<GeocodedAddress, GeocodeError>> {
    const params = new URLSearchParams({ address, components: `country:${countryCode}`, key: this.apiKey });
    const res = await this.get(`https://maps.googleapis.com/maps/api/geocode/json?${params.toString()}`);
    const body = await res.json();
    if (!isGoogleResponse(body)) return Result.fail({ kind: 'ServiceUnavailable', detail: `HTTP ${res.status}` });

    switch (body.status) {
      case 'OK': {
        const top = body.results[0];
        if (!top) return Result.fail({ kind: 'NoMatch' });
        return Result.ok({
          coordinates: top.geometry.location,
          formatted: top.formatted_address,
          precision: googlePrecision(top.geometry.location_type),
        });
      }
      case 'ZERO_RESULTS': return Result.fail({ kind: 'NoMatch' });
      case 'OVER_QUERY_LIMIT':
      case 'OVER_DAILY_LIMIT': return Result.fail({ kind: 'QuotaExceeded' });
      default: return Result.fail({ kind: 'ServiceUnavailable', detail: body.status });
    }
  }
}
```

Google reports quota problems with HTTP 200 and a `status` field, which is exactly the kind of quirk an adapter exists to absorb.

### 3. Nominatim adapter (`src/infrastructure/geocoding/NominatimGeocoder.ts`)
```typescript
interface NominatimPlace {
  lat: string;
  lon: string;
  display_name: string;
  addresstype?: string;
}

function isPlaceList(body: unknown): body is NominatimPlace[] {
  return Array.isArray(body) && body.every((p) => typeof p === 'object' && p !== null && typeof Reflect.get(p, 'lat') === 'string');
}

export class NominatimGeocoder implements Geocoder {
  constructor(private readonly get: HttpGet) {}

  async geocode(address: string, countryCode: string): Promise<Result<GeocodedAddress, GeocodeError>> {
    const params = new URLSearchParams({ q: address, countrycodes: countryCode.toLowerCase(), format: 'jsonv2', limit: '1' });
    const res = await this.get(`https://nominatim.openstreetmap.org/search?${params.toString()}`);
    if (res.status === 429) return Result.fail({ kind: 'QuotaExceeded' });
    const body = await res.json();
    if (!isPlaceList(body)) return Result.fail({ kind: 'ServiceUnavailable', detail: `HTTP ${res.status}` });

    const place = body[0];
    if (!place) return Result.fail({ kind: 'NoMatch' });
    const precision: Precision =
      place.addresstype === 'building' || place.addresstype === 'house' ? 'rooftop'
      : place.addresstype === 'road' ? 'street' : 'area';
    return Result.ok({
      coordinates: { lat: Number(place.lat), lng: Number(place.lon) },
      formatted: place.display_name,
      precision,
    });
  }
}
```

### 4. Fallback as one more adapter
The fallback policy is itself a `Geocoder`, so use cases stay unaware of it:

```typescript
export class FallbackGeocoder implements Geocoder {
  constructor(private readonly primary: Geocoder, private readonly secondary: Geocoder) {}

  async geocode(address: string, countryCode: string): Promise<Result<GeocodedAddress, GeocodeError>> {
    const first = await this.primary.geocode(address, countryCode);
    if (first.success || first.error.kind === 'NoMatch') return first;
    return this.secondary.geocode(address, countryCode);
  }
}
```

A `NoMatch` from Google is a real answer and is returned as is; only quota and availability failures fall through to Nominatim. Wire it as `new FallbackGeocoder(new GoogleGeocoder(get, key), new NominatimGeocoder(get))`, where `get` wraps `fetch` and, for Nominatim, sets the identifying `User-Agent` its usage policy requires.

Can you cover `ResetPassword` with isolated unit tests? Use fakes for the token store and the hasher, a fixed clock, and check the password length rule at its edges.

```typescript
import { Result } from '../shared/Result';

export interface ResetToken {
  value: string;
  userId: string;
  issuedAt: Date;
  usedAt: Date | null;
}

export interface ResetTokenStore {
  find(value: string): Promise<ResetToken | null>;
  markUsed(value: string, at: Date): Promise<void>;
}

export interface PasswordHasher {
  hash(plain: string): Promise<string>;
}

export interface CredentialRepository {
  updateHash(userId: string, hash: string): Promise<void>;
}

export type ResetError =
  | { kind: 'InvalidToken' }
  | { kind: 'TokenUsed' }
  | { kind: 'TokenExpired' }
  | { kind: 'PasswordTooShort'; min: number };

const TOKEN_TTL_MS = 30 * 60 * 1000;
const MIN_LENGTH = 12;

export class ResetPassword {
  constructor(
    private readonly tokens: ResetTokenStore,
    private readonly hasher: PasswordHasher,
    private readonly credentials: CredentialRepository,
    private readonly now: () => Date,
  ) {}

  async execute(tokenValue: string, newPassword: string): Promise<Result<void, ResetError>> {
    const token = await this.tokens.find(tokenValue);
    if (!token) return Result.fail({ kind: 'InvalidToken' });
    if (token.usedAt) return Result.fail({ kind: 'TokenUsed' });
    const at = this.now();
    if (at.getTime() - token.issuedAt.getTime() > TOKEN_TTL_MS) return Result.fail({ kind: 'TokenExpired' });
    if (newPassword.length < MIN_LENGTH) return Result.fail({ kind: 'PasswordTooShort', min: MIN_LENGTH });
    await this.credentials.updateHash(token.userId, await this.hasher.hash(newPassword));
    await this.tokens.markUsed(token.value, at);
    return Result.ok(undefined);
  }
}
```

Strategy: three small in-memory fakes that record state (the store remembers `usedAt`, the credential repository remembers the stored hash), a deterministic hasher so the stored value can be asserted, and a fixed `now`. `it.each` drives the 12-character boundary.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ResetPassword, ResetToken, ResetTokenStore, PasswordHasher, CredentialRepository } from './ResetPassword';

class FakeTokenStore implements ResetTokenStore {
  readonly tokens = new Map<string, ResetToken>();
  async find(value: string): Promise<ResetToken | null> {
    return this.tokens.get(value) ?? null;
  }
  async markUsed(value: string, at: Date): Promise<void> {
    const token = this.tokens.get(value);
    if (token) this.tokens.set(value, { ...token, usedAt: at });
  }
}

class PrefixHasher implements PasswordHasher {
  async hash(plain: string): Promise<string> {
    return `hashed:${plain}`;
  }
}

class FakeCredentials implements CredentialRepository {
  readonly hashes = new Map<string, string>();
  async updateHash(userId: string, hash: string): Promise<void> {
    this.hashes.set(userId, hash);
  }
}

const NOW = new Date('2024-03-01T09:00:00Z');
const minutesAgo = (m: number): Date => new Date(NOW.getTime() - m * 60_000);
const STRONG = 'correct-horse-battery';

describe('ResetPassword', () => {
  let store: FakeTokenStore;
  let credentials: FakeCredentials;
  let useCase: ResetPassword;

  beforeEach(() => {
    store = new FakeTokenStore();
    credentials = new FakeCredentials();
    useCase = new ResetPassword(store, new PrefixHasher(), credentials, () => NOW);
    store.tokens.set('t1', { value: 't1', userId: 'u1', issuedAt: minutesAgo(10), usedAt: null });
  });

  it('stores the new hash and marks the token as used', async () => {
    // Arrange: valid token t1 issued 10 minutes ago

    // Act
    const result = await useCase.execute('t1', STRONG);

    // Assert
    expect(result.success).toBe(true);
    expect(credentials.hashes.get('u1')).toBe(`hashed:${STRONG}`);
    expect(store.tokens.get('t1')?.usedAt).toEqual(NOW);
  });

  it.each([
    { password: 'a'.repeat(11), ok: false },
    { password: 'a'.repeat(12), ok: true },
  ])('length $password.length accepted: $ok', async ({ password, ok }) => {
    // Arrange: token t1 from beforeEach

    // Act
    const result = await useCase.execute('t1', password);

    // Assert
    expect(result.success).toBe(ok);
    if (!result.success) expect(result.error).toEqual({ kind: 'PasswordTooShort', min: 12 });
  });

  it('rejects an unknown token', async () => {
    // Arrange
    const unknown = 'nope';

    // Act
    const result = await useCase.execute(unknown, STRONG);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('InvalidToken');
  });

  it('rejects a token that was already used', async () => {
    // Arrange
    store.tokens.set('t2', { value: 't2', userId: 'u1', issuedAt: minutesAgo(5), usedAt: minutesAgo(1) });

    // Act
    const result = await useCase.execute('t2', STRONG);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('TokenUsed');
  });

  it('rejects a token older than 30 minutes without touching credentials', async () => {
    // Arrange
    store.tokens.set('old', { value: 'old', userId: 'u1', issuedAt: minutesAgo(31), usedAt: null });
    const updateSpy = vi.spyOn(credentials, 'updateHash');

    // Act
    const result = await useCase.execute('old', STRONG);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('TokenExpired');
    expect(updateSpy).not.toHaveBeenCalled();
  });
});
