```typescript
import { Result } from '../shared/Result';

export type TimesheetStatus = 'Draft' | 'Submitted' | 'Approved' | 'Rejected';

export interface Timesheet {
  id: string;
  employeeId: string;
  managerId: string;
  status: TimesheetStatus;
  hours: number[];
  approvedAt?: Date;
}

export interface TimesheetRepository {
  get(id: string): Promise<Timesheet | null>;
  save(sheet: Timesheet): Promise<void>;
}

export type ApprovalError =
  | { kind: 'NotFound' }
  | { kind: 'NotYourReport' }
  | { kind: 'NotSubmitted'; status: TimesheetStatus }
  | { kind: 'ExcessiveHours'; total: number };

const WEEKLY_LIMIT = 60;

export class ApproveTimesheet {
  constructor(private readonly sheets: TimesheetRepository, private readonly now: () => Date) {}

  async execute(sheetId: string, approverId: string): Promise<Result<Timesheet, ApprovalError>> {
    const sheet = await this.sheets.get(sheetId);
    if (!sheet) return Result.fail({ kind: 'NotFound' });
    if (sheet.managerId !== approverId) return Result.fail({ kind: 'NotYourReport' });
    if (sheet.status !== 'Submitted') return Result.fail({ kind: 'NotSubmitted', status: sheet.status });
    const total = sheet.hours.reduce((sum, h) => sum + h, 0);
    if (total > WEEKLY_LIMIT) return Result.fail({ kind: 'ExcessiveHours', total });
    const approved: Timesheet = { ...sheet, status: 'Approved', approvedAt: this.now() };
    await this.sheets.save(approved);
    return Result.ok(approved);
  }
