The decision tree is pure: given the bin's stock record and the counted quantity it yields one outcome. The use case handles the pick-task check, persistence and the side effects of each outcome.

#### 1. Domain (`src/domain/cycleCount.ts`)
```typescript
export const MIN_TOLERANCE_UNITS = 2;
export const TOLERANCE_RATIO = 0.01;
export const APPROVAL_THRESHOLD_CENTS = 50_000;

export interface BinStock {
  readonly binId: string;
  readonly sku: string;
  readonly systemQty: number;
  readonly unitCostCents: number;
  readonly recountPending: boolean;
}

export type CountOutcome =
  | { kind: 'Matched' }
  | { kind: 'Adjusted'; delta: number }
  | { kind: 'RecountRequired'; delta: number }
  | { kind: 'PendingApproval'; delta: number; valueCents: number };

export function toleranceFor(systemQty: number): number {
  return Math.max(MIN_TOLERANCE_UNITS, Math.floor(systemQty * TOLERANCE_RATIO));
}

export function evaluateCount(stock: BinStock, counted: number): CountOutcome {
  const delta = counted - stock.systemQty;
  if (delta === 0) return { kind: 'Matched' };
  if (Math.abs(delta) <= toleranceFor(stock.systemQty)) return { kind: 'Adjusted', delta };
  if (!stock.recountPending) return { kind: 'RecountRequired', delta };
  const valueCents = Math.abs(delta) * stock.unitCostCents;
  return valueCents > APPROVAL_THRESHOLD_CENTS
    ? { kind: 'PendingApproval', delta, valueCents }
    : { kind: 'Adjusted', delta };
}

export function applyOutcome(stock: BinStock, outcome: CountOutcome): BinStock {
  switch (outcome.kind) {
    case 'Matched': return { ...stock, recountPending: false };
    case 'Adjusted': return { ...stock, systemQty: stock.systemQty + outcome.delta, recountPending: false };
    case 'RecountRequired': return { ...stock, recountPending: true };
    case 'PendingApproval': return { ...stock, recountPending: false };
  }
}
```

#### 2. Application (`src/application/SubmitCycleCount.ts`)
```typescript
import { Result } from '../shared/Result';
import { BinStock, CountOutcome, applyOutcome, evaluateCount } from '../domain/cycleCount';

export type CycleCountError =
  | { kind: 'BinNotFound' }
  | { kind: 'BinBusy'; openTasks: number }
  | { kind: 'InvalidQuantity' };

export interface BinStockRepository {
  find(binId: string, sku: string): Promise<BinStock | null>;
  save(stock: BinStock): Promise<void>;
}

export interface PickTaskQuery {
  openTaskCount(binId: string): Promise<number>;
}

export interface InventoryLedger {
  recordAdjustment(binId: string, sku: string, delta: number, countedBy: string, at: Date): Promise<void>;
}

export interface ApprovalQueue {
  submit(binId: string, sku: string, delta: number, valueCents: number, countedBy: string): Promise<void>;
}

export interface CycleCountInput {
  readonly binId: string;
  readonly sku: string;
  readonly counted: number;
  readonly counterId: string;
}

export class SubmitCycleCount {
  constructor(
    private readonly stock: BinStockRepository,
    private readonly pickTasks: PickTaskQuery,
    private readonly ledger: InventoryLedger,
    private readonly approvals: ApprovalQueue,
    private readonly now: () => Date,
  ) {}

  async execute(input: CycleCountInput): Promise<Result<CountOutcome, CycleCountError>> {
    if (!Number.isInteger(input.counted) || input.counted < 0) return Result.fail({ kind: 'InvalidQuantity' });

    const current = await this.stock.find(input.binId, input.sku);
    if (!current) return Result.fail({ kind: 'BinNotFound' });

    const openTasks = await this.pickTasks.openTaskCount(input.binId);
    if (openTasks > 0) return Result.fail({ kind: 'BinBusy', openTasks });

    const outcome = evaluateCount(current, input.counted);
    await this.stock.save(applyOutcome(current, outcome));

    if (outcome.kind === 'Adjusted') {
      await this.ledger.recordAdjustment(input.binId, input.sku, outcome.delta, input.counterId, this.now());
    } else if (outcome.kind === 'PendingApproval') {
      await this.approvals.submit(input.binId, input.sku, outcome.delta, outcome.valueCents, input.counterId);
    }
    return Result.ok(outcome);
  }
}
```

Example: system quantity 400, tolerance 4. Counting 397 adjusts by −3. Counting 380 first returns `RecountRequired`; if the recount is again 380 with a unit cost of 30.00, the value is 600.00, so it becomes `PendingApproval` and the 400 units stay on the books until a supervisor decides. Costs are kept in integer cents to avoid floating-point drift.

Critique this image processing class in terms of SOLID. Keep it practical:

```typescript
import sharp from 'sharp';

interface Options {
  resize?: { width: number; height: number };
  grayscale?: boolean;
  watermark?: string;
  format?: 'jpeg' | 'webp' | 'avif';
  quality?: number;
  stripMetadata?: boolean;
}

export class ImageProcessor {
  async process(input: Buffer, opts: Options): Promise<Buffer> {
    let img = sharp(input);
    if (opts.stripMetadata !== false) img = img.withMetadata({});
    if (opts.resize) img = img.resize(opts.resize.width, opts.resize.height, { fit: 'inside' });
    if (opts.grayscale) img = img.grayscale();
    if (opts.watermark) {
      const svg = Buffer.from(`<svg><text x="10" y="20">${opts.watermark}</text></svg>`);
      img = img.composite([{ input: svg, gravity: 'southeast' }]);
    }
    if (opts.format === 'webp') img = img.webp({ quality: opts.quality ?? 80 });
    else if (opts.format === 'avif') img = img.avif({ quality: opts.quality ?? 50 });
    else img = img.jpeg({ quality: opts.quality ?? 85 });
    return img.toBuffer();
  }
}
```

### Practical SOLID Critique

#### Open/Closed — the main issue
Every new operation (blur, crop, rotate) adds a field to `Options` and an `if` to `process()`. The order of operations is hard-coded by the order of the `if`s: you cannot watermark *before* resizing (so the watermark gets shrunk with the image) without editing the class and changing behaviour for every caller.

#### Single Responsibility — violated, mildly
`process()` decides *which* operations run, *in which order*, *how* each one is done, and the default quality per format. The defaults (80/50/85) are product decisions mixed with library calls.

#### Not violated: Liskov and Interface Segregation
There is no hierarchy, and the public surface is a single method. Don't invent an inheritance tree to "fix" problems that aren't there.

#### Dependency Inversion — a judgement call
`sharp` is imported directly. For an image processing module, `sharp` *is* the implementation, so wrapping every call behind your own abstraction would be ceremony. What matters is that callers (an upload handler, a thumbnail job) depend on a small abstraction and not on `sharp`, so they can be tested with a fake.

#### A real bug hiding in it
`opts.watermark` goes unescaped into SVG. A watermark like `Tom & Jerry` produces invalid XML and the whole call throws; a user-controlled value can inject arbitrary SVG.

---

### Refactoring: a pipeline of steps

```typescript
import sharp, { Sharp } from 'sharp';

export type ImageStep = (img: Sharp) => Sharp;

export const resize = (width: number, height: number): ImageStep =>
  (img) => img.resize(width, height, { fit: 'inside' });

export const grayscale = (): ImageStep => (img) => img.grayscale();

function escapeXml(text: string): string {
  return text.replace(/[<>&"']/g, (c) => `&#${c.charCodeAt(0)};`);
}

export const watermark = (text: string): ImageStep => (img) => {
  const svg = Buffer.from(`<svg><text x="10" y="20">${escapeXml(text)}</text></svg>`);
  return img.composite([{ input: svg, gravity: 'southeast' }]);
};

export type OutputFormat = 'jpeg' | 'webp' | 'avif';

const DEFAULT_QUALITY: Record<OutputFormat, number> = { jpeg: 85, webp: 80, avif: 50 };

export const encode = (format: OutputFormat, quality = DEFAULT_QUALITY[format]): ImageStep => (img) => {
  switch (format) {
    case 'jpeg': return img.jpeg({ quality });
    case 'webp': return img.webp({ quality });
    case 'avif': return img.avif({ quality });
  }
};

export class ImagePipeline {
  constructor(private readonly steps: readonly ImageStep[]) {}

  run(input: Buffer): Promise<Buffer> {
    return this.steps.reduce((img, step) => step(img), sharp(input)).toBuffer();
  }
}
```

Callers depend on a one-method abstraction, so an upload handler can be tested with a fake that returns the input unchanged:

```typescript
export interface ImageTransformer {
  run(input: Buffer): Promise<Buffer>;
}

export const thumbnail: ImageTransformer = new ImagePipeline([
  resize(320, 320),
  watermark('© Acme'),
  encode('webp'),
]);

export const printReady: ImageTransformer = new ImagePipeline([
  watermark('PROOF'),
  resize(2480, 3508),
  encode('jpeg', 95),
]);
```

What you get:
- **New operation = new `ImageStep` function.** `ImagePipeline` never changes.
- **Order is explicit per use**: `printReady` watermarks before resizing, `thumbnail` after, without flags.
- **Defaults live in one table** (`DEFAULT_QUALITY`) instead of three inline literals.
- **Metadata is stripped by default** because `sharp` drops it unless `withMetadata()` is called; the original `withMetadata({})` actually *kept* it. Add a `keepMetadata()` step only where it is wanted.

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    // Validate input
    if (!request.userId) {
      return error(new InvalidPasswordError('User ID is required'));
    }

    if (!request.currentPassword) {
      return error(new InvalidPasswordError('Current password is required'));
    }

    if (!request.newPassword) {
      return error(new InvalidPasswordError('New password is required'));
    }

    // Check if user exists
    const user = await this.userRepository.findById(request.userId);
    if (!user) {
      return error(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      request.currentPassword,
      user.passwordHash
    );

    if (!isPasswordValid) {
      return error(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      request.newPassword,
      user.passwordHash
    );

    if (isSamePassword) {
      return error(new InvalidPasswordError('New password cannot be the same as the current password'));
    }

    // Hash new password
    const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = Success<T> | Failure<E>;

interface Success<T> {
  isSuccess: true;
  value: T;
  error?: never;
}

interface Failure<E extends DomainError> {
  isSuccess: false;
  value?: never;
  error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error
  };
}
```

```typescript
// Domain/ValueObjects/Money.ts
export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: string
  ) {}

  public static create(amount: number, currency: string): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure(new MoneyError("Amount must be positive"));
    }

    if (!currency || currency.trim().length === 0) {
      return Result.failure(new MoneyError("Currency must be provided"));
    }

    return Result.success(new Money(amount, currency));
  }

  public add(other: Money): Result<Money, MoneyError> {
    if (this._currency !== other._currency) {
      return Result.failure(new MoneyError("Currencies must match"));
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  public get amount(): number {
    return this._amount;
  }

  public get currency(): string {
    return this._currency;
  }

  public equals(other: Money): boolean {
    return this._amount === other._amount && this._currency === other._currency;
  }
}

// Domain/Errors/MoneyError.ts
export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

// Domain/Result.ts
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  public static success<T, E extends Error>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  public static failure<T, E extends Error>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Value Object**: `Money` is immutable and has no identity
2. **Domain Validation**: 
   - Enforces positive amounts
   - Validates currency is provided
3. **Currency Safety**: 
   - `add` method checks currency match
   - Returns typed errors via `Result` pattern
4. **No External Dependencies**: 
   - No framework or infrastructure dependencies
   - Pure TypeScript with no external libraries
5. **Typed Errors**: 
   - `MoneyError` extends `Error` for proper error handling
   - `Result<T, E>` pattern for safe error propagation
6. **SOLID Compliance**:
   - Single Responsibility: `Money` handles only money-related logic
   - Open/Closed: Can be extended without modifying existing code
   - Liskov Substitution: `Result` can be used consistently
   - Interface Segregation: No unnecessary interfaces
   - Dependency Inversion: Dependencies are to abstractions (interfaces) not concretions

The `Result` pattern ensures that all operations that might fail return either a success with the result or a failure with an error, making error handling explicit and preventing silent failures.

Critique this class against the SOLID principles and refactor it:

```typescript
class PriceCalculator {
  calculate(customerType: string, base: number): number {
    switch (customerType) {
      case 'regular': return base;
      case 'vip': return base * 0.8;
      case 'employee': return base * 0.5;
      default: throw new Error('Unknown customer type');
    }
  }
}
```

### SOLID Critique
- **OCP (violated):** every new customer type forces an edit to `calculate`, risking regressions in existing branches.
- **SRP (borderline):** the class knows every pricing policy, so it changes for each business decision.
- **Stringly-typed input:** `customerType: string` allows typos that only fail at runtime.

---

### Refactoring: Strategy per customer type
```typescript
export interface PricingStrategy {
  apply(base: number): number;
}

export class RegularPricing implements PricingStrategy {
  apply(base: number): number { return base; }
}

export class VipPricing implements PricingStrategy {
  apply(base: number): number { return base * 0.8; }
}

export class EmployeePricing implements PricingStrategy {
  apply(base: number): number { return base * 0.5; }
}

export class PriceCalculator {
  constructor(private readonly strategies: ReadonlyMap<string, PricingStrategy>) {}

  calculate(customerType: string, base: number): number {
    const strategy = this.strategies.get(customerType);
    if (!strategy) throw new Error('Unknown customer type');
    return strategy.apply(base);
  }
}
```

Adding a `student` discount now means adding one class and one map entry. `PriceCalculator` stays closed for modification (OCP), and each strategy can be tested in isolation.

Critique this class with SOLID, focusing on Single Responsibility, and split it:

```typescript
class InvoiceService {
  create(items: Item[]) {
    const total = items.reduce((s, i) => s + i.price, 0);
    const html = `<h1>Invoice</h1><p>Total: ${total}</p>`;
    fs.writeFileSync('/tmp/invoice.html', html);
    printer.print(html);
    return total;
  }
}
```

### SOLID Critique
- **SRP (violated):** `InvoiceService` calculates totals, renders HTML, writes to disk and prints. It changes for four unrelated reasons.
- **DIP (violated):** `fs` and `printer` are used directly, with a hardcoded path.
- **Testability:** testing the total requires a filesystem and a printer.

---

### Refactoring: separate calculation, rendering and delivery
```typescript
export class Invoice {
  constructor(public readonly items: readonly Item[]) {}
  total(): number { return this.items.reduce((sum, item) => sum + item.price, 0); }
}

export interface InvoiceRenderer { render(invoice: Invoice): string }
export interface InvoiceOutput { deliver(content: string): Promise<void> }

export class HtmlInvoiceRenderer implements InvoiceRenderer {
  render(invoice: Invoice): string {
    return `<h1>Invoice</h1><p>Total: ${invoice.total()}</p>`;
  }
}

export class IssueInvoice {
  constructor(
    private readonly renderer: InvoiceRenderer,
    private readonly outputs: readonly InvoiceOutput[],
  ) {}

  async execute(items: Item[]): Promise<number> {
    const invoice = new Invoice(items);
    const content = this.renderer.render(invoice);
    await Promise.all(this.outputs.map((output) => output.deliver(content)));
    return invoice.total();
  }
}
```

`Invoice` holds the rule, the renderer holds the format, and each output (file, printer) is injected. Adding PDF output or a new destination does not touch the calculation.

Refactor this Express route that mixes payment and booking rules with direct Redis and Stripe calls:

```typescript
app.post('/api/bookings/:id/cancel', async (req, res) => {
  const booking = JSON.parse(await redis.get('booking:' + req.params.id));
  const hoursLeft = (new Date(booking.start).getTime() - Date.now()) / 3600000;
  const refund = hoursLeft > 48 ? booking.price : hoursLeft > 12 ? booking.price / 2 : 0;
  if (refund > 0) await stripe.refunds.create({ charge: booking.chargeId, amount: refund * 100 });
  await redis.del('booking:' + req.params.id);
  res.json({ refunded: refund });
