```typescript
// Domain/ValueObjects/Money.ts

export interface Currency {
  readonly code: string;
  readonly symbol: string;
  readonly decimalPlaces: number;
}

export interface MoneyError {
  readonly type: 'InvalidAmount' | 'CurrencyMismatch' | 'InvalidCurrency';
  readonly message: string;
}

export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: Currency
  ) {}

  get amount(): number {
    return this._amount;
  }

  get currency(): Currency {
    return this._currency;
  }

  /**
   * Creates a new Money instance with validation
   */
  static create(amount: number, currency: Currency): Result<Money, MoneyError> {
    if (amount < 0) {
      return Result.failure({
        type: 'InvalidAmount',
        message: 'Amount must be positive'
      });
    }

    if (!currency || !currency.code) {
      return Result.failure({
        type: 'InvalidCurrency',
        message: 'Currency must be valid'
      });
    }

    return Result.success(new Money(amount, currency));
  }

  /**
   * Adds two Money instances with currency validation
   */
  add(other: Money): Result<Money, MoneyError> {
    if (this._currency.code !== other._currency.code) {
      return Result.failure({
        type: 'CurrencyMismatch',
        message: `Cannot add money in different currencies: ${this._currency.code} and ${other._currency.code}`
      });
    }

    const newAmount = this._amount + other._amount;
    return Result.success(new Money(newAmount, this._currency));
  }

  /**
   * Checks if two Money instances are equal
   */
  equals(other: Money): boolean {
    return (
      this._amount === other._amount &&
      this._currency.code === other._currency.code
    );
  }

  /**
   * Returns a string representation of the Money instance
   */
  toString(): string {
    return `${this._currency.symbol}${this._amount.toFixed(this._currency.decimalPlaces)}`;
  }
}

// Result type implementation
export class Result<T, E> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T, E>(value: T): Result<T, E> {
    return new Result<T, E>(true, value);
  }

  static failure<T, E>(error: E): Result<T, E> {
    return new Result<T, E>(false, undefined, error);
  }

  map<U>(fn: (value: T) => U): Result<U, E> {
    if (this.isSuccess) {
      return Result.success(fn(this.value!));
    }
    return Result.failure(this.error!);
  }

  flatMap<U>(fn: (value: T) => Result<U, E>): Result<U, E> {
    if (this.isSuccess) {
      return fn(this.value!);
    }
    return Result.failure(this.error!);
  }
}
```

Separate the one-time-code rules in these two Express routes from Twilio and Redis:

```typescript
app.post('/otp/send', async (req, res) => {
  const phone = String(req.body.phone).replace(/\s+/g, '');
  if (!/^\+[1-9]\d{7,14}$/.test(phone)) return res.status(400).json({ error: 'Invalid phone' });
  const code = String(Math.floor(100000 + Math.random() * 900000));
  await redis.set(`otp:${phone}`, JSON.stringify({ code, attempts: 0 }), 'EX', 300);
  await twilio.messages.create({ to: phone, from: process.env.TWILIO_FROM, body: `Your code is ${code}` });
  res.status(202).end();
});

app.post('/otp/verify', async (req, res) => {
  const phone = String(req.body.phone).replace(/\s+/g, '');
  const raw = await redis.get(`otp:${phone}`);
  if (!raw) return res.status(410).json({ error: 'Code expired' });
  const otp = JSON.parse(raw);
  if (otp.attempts >= 5) return res.status(429).json({ error: 'Too many attempts' });
  if (otp.code !== req.body.code) {
    await redis.set(`otp:${phone}`, JSON.stringify({ ...otp, attempts: otp.attempts + 1 }), 'KEEPTTL');
    return res.status(401).json({ error: 'Wrong code' });
  }
  await redis.del(`otp:${phone}`);
  res.json({ verified: true });
});
```

### Architectural Flaws in Original Code
1. **Verification policy split across routes:** phone format, code length, five attempts and the five-minute expiry live in HTTP callbacks.
2. **Vendor calls inline:** Twilio and Redis are used directly, so neither flow can run in a test.
3. **Duplicated normalisation:** the phone clean-up is copy-pasted in both handlers.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/otp.ts`)
```typescript
import { Result } from '../shared/Result';

export type OtpError =
  | { kind: 'InvalidPhone' }
  | { kind: 'Expired' }
  | { kind: 'TooManyAttempts' }
  | { kind: 'WrongCode' };

export class PhoneNumber {
  private constructor(readonly value: string) {}

  static parse(raw: string): Result<PhoneNumber, OtpError> {
    const value = raw.replace(/\s+/g, '');
    return /^\+[1-9]\d{7,14}$/.test(value) ? Result.ok(new PhoneNumber(value)) : Result.fail({ kind: 'InvalidPhone' });
  }
}

export const OTP_TTL_SECONDS = 300;
export const MAX_ATTEMPTS = 5;

export interface PendingCode {
  readonly code: string;
  readonly attempts: number;
}

/** Returns the state to store after a wrong guess, or null when the code matched. */
export function checkCode(pending: PendingCode, guess: string): Result<PendingCode | null, OtpError> {
  if (pending.attempts >= MAX_ATTEMPTS) return Result.fail({ kind: 'TooManyAttempts' });
  if (pending.code !== guess) return Result.ok({ ...pending, attempts: pending.attempts + 1 });
  return Result.ok(null);
}
```

#### 2. Application Layer (`src/application/otp.ts`)
```typescript
import { Result } from '../shared/Result';
import { OTP_TTL_SECONDS, OtpError, PendingCode, PhoneNumber, checkCode } from '../domain/otp';

export interface CodeStore {
  put(phone: PhoneNumber, pending: PendingCode, ttlSeconds: number): Promise<void>;
  get(phone: PhoneNumber): Promise<PendingCode | null>;
  update(phone: PhoneNumber, pending: PendingCode): Promise<void>; // keeps the TTL
  remove(phone: PhoneNumber): Promise<void>;
}

export interface TextMessenger {
  send(to: PhoneNumber, text: string): Promise<void>;
}

export class OneTimeCodes {
  constructor(
    private readonly store: CodeStore,
    private readonly messenger: TextMessenger,
    private readonly generate: () => string,
  ) {}

  async send(rawPhone: string): Promise<Result<void, OtpError>> {
    const phone = PhoneNumber.parse(rawPhone);
    if (!phone.success) return phone;
    const code = this.generate();
    await this.store.put(phone.data, { code, attempts: 0 }, OTP_TTL_SECONDS);
    await this.messenger.send(phone.data, `Your code is ${code}`);
    return Result.ok(undefined);
  }

  async verify(rawPhone: string, guess: string): Promise<Result<void, OtpError>> {
    const phone = PhoneNumber.parse(rawPhone);
    if (!phone.success) return phone;
    const pending = await this.store.get(phone.data);
    if (!pending) return Result.fail({ kind: 'Expired' });

    const checked = checkCode(pending, guess);
    if (!checked.success) return checked;
    if (checked.data) {
      await this.store.update(phone.data, checked.data);
      return Result.fail({ kind: 'WrongCode' });
    }
    await this.store.remove(phone.data);
    return Result.ok(undefined);
  }
}
```

#### 3. Infrastructure Layer
`RedisCodeStore` keeps the `otp:<phone>` key with `EX` / `KEEPTTL`, and the messenger wraps Twilio:
```typescript
import { Twilio } from 'twilio';

export class TwilioMessenger implements TextMessenger {
  constructor(private readonly client: Twilio, private readonly from: string) {}

  async send(to: PhoneNumber, text: string): Promise<void> {
    await this.client.messages.create({ to: to.value, from: this.from, body: text });
  }
}

export const sixDigits = (): string => String(Math.floor(100000 + Math.random() * 900000));
```

#### 4. Presentation Layer
```typescript
function toHttp(error: OtpError): [number, string] {
  switch (error.kind) {
    case 'InvalidPhone': return [400, 'Invalid phone'];
    case 'Expired': return [410, 'Code expired'];
    case 'TooManyAttempts': return [429, 'Too many attempts'];
    case 'WrongCode': return [401, 'Wrong code'];
  }
}

app.post('/otp/send', async (req, res) => {
  const result = await otp.send(String(req.body.phone));
  if (result.success) return res.status(202).end();
  const [status, error] = toHttp(result.error);
  res.status(status).json({ error });
});

app.post('/otp/verify', async (req, res) => {
  const code = typeof req.body.code === 'string' ? req.body.code : ''; // codes are strings, as before
  const result = await otp.verify(String(req.body.phone), code);
  if (result.success) return res.json({ verified: true });
  const [status, error] = toHttp(result.error);
  res.status(status).json({ error });
});
```

One deliberate change: `/otp/verify` now validates the phone number like `/otp/send` and answers 400 `Invalid phone` for a malformed one, where the original answered 410 `Code expired`.

This BullMQ worker computes reorder alerts for a store. Refactor it so the replenishment math is pure and the queue, Prisma and Slack are replaceable:

```typescript
new Worker('reorder-check', async (job) => {
  const since = new Date(Date.now() - 28 * 86400000);
  const products = await prisma.product.findMany({ where: { storeId: job.data.storeId, discontinued: false } });
  const alerts: string[] = [];
  for (const p of products) {
    const sold = await prisma.sale.aggregate({ _sum: { qty: true }, where: { productId: p.id, soldAt: { gte: since } } });
    const dailyDemand = (sold._sum.qty ?? 0) / 28;
    const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * 3);
    if (p.onHand <= reorderPoint) {
      const qty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * 14) - p.onHand);
      alerts.push(`${p.sku}: on hand ${p.onHand}, order ${qty}`);
    }
  }
  if (alerts.length) {
    await fetch(process.env.SLACK_WEBHOOK!, { method: 'POST', body: JSON.stringify({ text: alerts.join('\n') }) });
  }
}, { connection });
```

### Architectural Flaws in Original Code
1. **Replenishment formula hidden in a job:** the 28-day window, 3 days of safety stock and the 14-day order target can only be checked by running BullMQ.
2. **N+1 queries in the business loop:** sales are aggregated per product inside the decision logic.
3. **Notification format coupled to Slack:** alerts are built as Slack text strings.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/replenishment.ts`)
```typescript
export interface StockPosition {
  readonly sku: string;
  readonly onHand: number;
  readonly leadTimeDays: number;
  readonly minOrderQty: number;
  readonly unitsSold: number; // within the demand window
}

export interface ReorderSuggestion {
  readonly sku: string;
  readonly onHand: number;
  readonly orderQty: number;
}

export const DEMAND_WINDOW_DAYS = 28;
export const SAFETY_STOCK_DAYS = 3;
export const COVERAGE_DAYS = 14;

export function suggestReorder(p: StockPosition): ReorderSuggestion | null {
  const dailyDemand = p.unitsSold / DEMAND_WINDOW_DAYS;
  const reorderPoint = Math.ceil(dailyDemand * p.leadTimeDays + dailyDemand * SAFETY_STOCK_DAYS);
  if (p.onHand > reorderPoint) return null;
  const orderQty = Math.max(p.minOrderQty, Math.ceil(dailyDemand * COVERAGE_DAYS) - p.onHand);
  return { sku: p.sku, onHand: p.onHand, orderQty };
}
```

#### 2. Application Layer (`src/application/CheckReorders.ts`)
```typescript
import { ReorderSuggestion, StockPosition, DEMAND_WINDOW_DAYS, suggestReorder } from '../domain/replenishment';

export interface StockReader {
  /** Active products of the store with units sold since `since`. */
  positions(storeId: string, since: Date): Promise<StockPosition[]>;
}

export interface ReorderNotifier {
  notify(storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void>;
}

export class CheckReorders {
  constructor(
    private readonly stock: StockReader,
    private readonly notifier: ReorderNotifier,
    private readonly now: () => Date,
  ) {}

  async execute(storeId: string): Promise<ReorderSuggestion[]> {
    const since = new Date(this.now().getTime() - DEMAND_WINDOW_DAYS * 86_400_000);
    const suggestions = (await this.stock.positions(storeId, since))
      .map(suggestReorder)
      .filter((s): s is ReorderSuggestion => s !== null);
    if (suggestions.length > 0) await this.notifier.notify(storeId, suggestions);
    return suggestions;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure`)
One grouped query replaces the per-product aggregate.
```typescript
import { PrismaClient } from '@prisma/client';
import { ReorderSuggestion, StockPosition } from '../domain/replenishment';
import { ReorderNotifier, StockReader } from '../application/CheckReorders';

export class PrismaStockReader implements StockReader {
  constructor(private readonly prisma: PrismaClient) {}

  async positions(storeId: string, since: Date): Promise<StockPosition[]> {
    const products = await this.prisma.product.findMany({ where: { storeId, discontinued: false } });
    const sales = await this.prisma.sale.groupBy({
      by: ['productId'], _sum: { qty: true },
      where: { productId: { in: products.map((p) => p.id) }, soldAt: { gte: since } },
    });
    const sold = new Map(sales.map((s) => [s.productId, s._sum.qty ?? 0]));
    return products.map((p) => ({
      sku: p.sku, onHand: p.onHand, leadTimeDays: p.leadTimeDays,
      minOrderQty: p.minOrderQty, unitsSold: sold.get(p.id) ?? 0,
    }));
  }
}

export class SlackReorderNotifier implements ReorderNotifier {
  constructor(private readonly webhookUrl: string) {}

  async notify(_storeId: string, suggestions: readonly ReorderSuggestion[]): Promise<void> {
    const text = suggestions.map((s) => `${s.sku}: on hand ${s.onHand}, order ${s.orderQty}`).join('\n');
    await fetch(this.webhookUrl, { method: 'POST', body: JSON.stringify({ text }) });
  }
}
```

#### 4. Worker (`src/jobs/reorderWorker.ts`)
```typescript
import { Job, Worker } from 'bullmq';

const checkReorders = new CheckReorders(
  new PrismaStockReader(prisma),
  new SlackReorderNotifier(config.slackWebhookUrl),
  () => new Date(),
);

new Worker('reorder-check', async (job: Job<{ storeId: string }>) => {
  await checkReorders.execute(job.data.storeId);
}, { connection: config.redis });
```
The webhook URL is now read once into `config` at startup instead of with a non-null assertion inside the job.

```typescript
// Domain/ValueObjects/Money.ts
export interface Money {
  readonly amount: number;
  readonly currency: string;
}

export class MoneyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MoneyError";
  }
}

export class InvalidAmountError extends MoneyError {
  constructor() {
    super("Amount must be positive");
    this.name = "InvalidAmountError";
  }
}

export class CurrencyMismatchError extends MoneyError {
  constructor() {
    super("Currencies must match for addition");
    this.name = "CurrencyMismatchError";
  }
}

export class MoneyValueObject {
  private constructor(private readonly _amount: number, private readonly _currency: string) {
    if (_amount < 0) {
      throw new InvalidAmountError();
    }
  }

  static create(amount: number, currency: string): Money {
    return new MoneyValueObject(amount, currency);
  }

  get amount(): number {
    return this._amount;
  }

  get currency(): string {
    return this._currency;
  }

  add(other: Money): Money {
    if (this._currency !== other.currency) {
      throw new CurrencyMismatchError();
    }

    return new MoneyValueObject(
      this._amount + other.amount,
      this._currency
    );
  }

  equals(other: Money): boolean {
    return this._amount === other.amount && this._currency === other.currency;
  }
}
