Refactor this React component. The shipping cost rules are mixed with fetching and rendering:

```tsx
export function ShippingQuote({ cartId }: { cartId: string }) {
  const [cart, setCart] = useState<{ weightKg: number; subtotal: number; country: string } | null>(null);

  useEffect(() => {
    axios.get(`/api/carts/${cartId}`).then((r) => setCart(r.data));
  }, [cartId]);

  if (!cart) return <p>Loading…</p>;

  let cost = 0;
  if (cart.subtotal >= 75) cost = 0;
  else if (cart.weightKg <= 1) cost = 4.99;
  else if (cart.weightKg <= 5) cost = 8.99;
  else cost = 8.99 + Math.ceil(cart.weightKg - 5) * 1.5;
  if (cart.country !== 'US' && cart.subtotal < 75) cost += 12;

  return <p>Shipping: {cost === 0 ? 'Free' : `$${cost.toFixed(2)}`}</p>;
}
```

### Architectural Flaws in Original Code
1. **Pricing rules inside a render function:** the free-shipping threshold, weight tiers and international surcharge can only be tested by rendering React.
2. **Transport in the view:** `axios` is called from the component, so the UI cannot be reused with another data source.
3. **Untyped response:** `r.data` is trusted as the cart shape without validation.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/shipping.ts`)
Pure function, no React, no HTTP.
```typescript
export interface CartSummary {
  readonly weightKg: number;
  readonly subtotal: number;
  readonly country: string;
}

export const FREE_SHIPPING_THRESHOLD = 75;
const INTERNATIONAL_SURCHARGE = 12;

export function shippingCost(cart: CartSummary): number {
  if (cart.subtotal >= FREE_SHIPPING_THRESHOLD) return 0;
  let cost: number;
  if (cart.weightKg <= 1) cost = 4.99;
  else if (cart.weightKg <= 5) cost = 8.99;
  else cost = 8.99 + Math.ceil(cart.weightKg - 5) * 1.5;
  if (cart.country !== 'US') cost += INTERNATIONAL_SURCHARGE;
  return cost;
}
```

#### 2. Application Layer (`src/application/getShippingQuote.ts`)
```typescript
import { Result } from '../shared/Result';
import { CartSummary, shippingCost } from '../domain/shipping';

export type QuoteError = { kind: 'CartUnavailable'; cartId: string };

export interface CartReader {
  summary(cartId: string): Promise<CartSummary | null>;
}

export async function getShippingQuote(
  carts: CartReader,
  cartId: string,
): Promise<Result<number, QuoteError>> {
  const cart = await carts.summary(cartId);
  if (!cart) return Result.fail({ kind: 'CartUnavailable', cartId });
  return Result.ok(shippingCost(cart));
}
```

#### 3. Infrastructure Layer (`src/infrastructure/HttpCartReader.ts`)
```typescript
import axios from 'axios';
import { CartSummary } from '../domain/shipping';
import { CartReader } from '../application/getShippingQuote';

function isCartSummary(value: unknown): value is CartSummary {
  if (typeof value !== 'object' || value === null) return false;
  const v = value as Record<string, unknown>;
  return typeof v.weightKg === 'number' && typeof v.subtotal === 'number' && typeof v.country === 'string';
}

export class HttpCartReader implements CartReader {
  async summary(cartId: string): Promise<CartSummary | null> {
    const response = await axios.get<unknown>(`/api/carts/${cartId}`);
    return isCartSummary(response.data) ? response.data : null;
  }
}
```

#### 4. Presentation Layer (`src/ui/ShippingQuote.tsx`)
The component receives the reader and only renders.
```tsx
export function ShippingQuote({ cartId, carts }: { cartId: string; carts: CartReader }) {
  const [quote, setQuote] = useState<Result<number, QuoteError> | null>(null);

  useEffect(() => {
    getShippingQuote(carts, cartId).then(setQuote);
  }, [cartId, carts]);

  if (!quote) return <p>Loading…</p>;
  if (!quote.success) return <p>Shipping unavailable</p>;
  return <p>Shipping: {quote.data === 0 ? 'Free' : `$${quote.data.toFixed(2)}`}</p>;
}
```

`shippingCost` can now be unit-tested with plain objects, for example `{ weightKg: 7.2, subtotal: 40, country: 'CA' }` → `8.99 + 3 * 1.5 + 12 = 25.49`.

Write unit tests for the plan change below using Arrange-Act-Assert. Upgrades are prorated and charged right away, downgrades wait for the end of the period; the tests should prove both with real numbers.

```typescript
import { Result } from '../shared/Result';

export interface Plan {
  id: string;
  monthlyCents: number;
}

export interface Subscription {
  id: string;
  planId: string;
  periodStart: Date;
  periodEnd: Date;
  pendingPlanId: string | null;
}

export interface PlanCatalog {
  plan(id: string): Promise<Plan | null>;
}

export interface SubscriptionRepository {
  get(id: string): Promise<Subscription | null>;
  save(sub: Subscription): Promise<void>;
}

export interface Invoicer {
  charge(subscriptionId: string, cents: number): Promise<void>;
}

export type ChangeError = { kind: 'SubscriptionNotFound' } | { kind: 'UnknownPlan' } | { kind: 'SamePlan' };
export type ChangeOutcome = { effective: 'now' | 'period_end'; chargedCents: number };

export class ChangePlan {
  constructor(
    private readonly subs: SubscriptionRepository,
    private readonly catalog: PlanCatalog,
    private readonly invoicer: Invoicer,
    private readonly now: () => Date,
  ) {}

  async execute(subId: string, newPlanId: string): Promise<Result<ChangeOutcome, ChangeError>> {
    const sub = await this.subs.get(subId);
    if (!sub) return Result.fail({ kind: 'SubscriptionNotFound' });
    if (sub.planId === newPlanId) return Result.fail({ kind: 'SamePlan' });
    const current = await this.catalog.plan(sub.planId);
    const next = await this.catalog.plan(newPlanId);
    if (!current || !next) return Result.fail({ kind: 'UnknownPlan' });
    if (next.monthlyCents < current.monthlyCents) {
      await this.subs.save({ ...sub, pendingPlanId: next.id });
      return Result.ok({ effective: 'period_end', chargedCents: 0 });
    }
    const total = sub.periodEnd.getTime() - sub.periodStart.getTime();
    const remaining = sub.periodEnd.getTime() - this.now().getTime();
    const chargedCents = Math.round((next.monthlyCents - current.monthlyCents) * (remaining / total));
    await this.invoicer.charge(sub.id, chargedCents);
    await this.subs.save({ ...sub, planId: next.id, pendingPlanId: null });
    return Result.ok({ effective: 'now', chargedCents });
  }
}
```

I use a 30-day period (1 to 31 March) and move the frozen clock inside it, so the remaining fraction is easy to read: on 11 March, 10 days in, 20 of 30 days are left. The catalog is a fixed fake with three plans; the invoicer is a spy.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ChangePlan, Invoicer, Plan, PlanCatalog, Subscription, SubscriptionRepository } from './ChangePlan';

class InMemorySubscriptions implements SubscriptionRepository {
  readonly subs = new Map<string, Subscription>();
  async get(id: string): Promise<Subscription | null> {
    return this.subs.get(id) ?? null;
  }
  async save(sub: Subscription): Promise<void> {
    this.subs.set(sub.id, sub);
  }
}

class FixedCatalog implements PlanCatalog {
  private readonly plans = new Map<string, Plan>(
    [{ id: 'basic', monthlyCents: 1_000 }, { id: 'pro', monthlyCents: 3_000 }, { id: 'team', monthlyCents: 6_000 }]
      .map((p) => [p.id, p]),
  );
  async plan(id: string): Promise<Plan | null> {
    return this.plans.get(id) ?? null;
  }
}

const day = (d: number): Date => new Date(Date.UTC(2024, 2, d));
const proSub = (): Subscription => ({
  id: 'sub-1', planId: 'pro', periodStart: day(1), periodEnd: day(31), pendingPlanId: null,
});

describe('ChangePlan', () => {
  let subs: InMemorySubscriptions;
  let charge: ReturnType<typeof vi.fn<Invoicer['charge']>>;
  const changePlanAt = (now: Date): ChangePlan => new ChangePlan(subs, new FixedCatalog(), { charge }, () => now);

  beforeEach(async () => {
    subs = new InMemorySubscriptions();
    charge = vi.fn<Invoicer['charge']>().mockResolvedValue(undefined);
    await subs.save(proSub());
  });

  it.each([
    { today: 1, charged: 3_000 },
    { today: 11, charged: 2_000 },
    { today: 31, charged: 0 },
  ])('upgrading pro -> team on March $today charges $charged', async ({ today, charged }) => {
    // Arrange
    const useCase = changePlanAt(day(today));

    // Act
    const result = await useCase.execute('sub-1', 'team');

    // Assert
    expect(result).toEqual({ success: true, data: { effective: 'now', chargedCents: charged } });
    expect(charge).toHaveBeenCalledWith('sub-1', charged);
    expect(subs.subs.get('sub-1')?.planId).toBe('team');
  });

  it('schedules a downgrade for the period end without charging', async () => {
    // Arrange
    const useCase = changePlanAt(day(11));

    // Act
    const result = await useCase.execute('sub-1', 'basic');

    // Assert
    expect(result).toEqual({ success: true, data: { effective: 'period_end', chargedCents: 0 } });
    expect(subs.subs.get('sub-1')).toMatchObject({ planId: 'pro', pendingPlanId: 'basic' });
    expect(charge).not.toHaveBeenCalled();
  });

  it.each([
    { subId: 'missing', planId: 'team', kind: 'SubscriptionNotFound' },
    { subId: 'sub-1', planId: 'pro', kind: 'SamePlan' },
    { subId: 'sub-1', planId: 'enterprise', kind: 'UnknownPlan' },
  ])('fails with $kind', async ({ subId, planId, kind }) => {
    // Arrange
    const useCase = changePlanAt(day(11));

    // Act
    const result = await useCase.execute(subId, planId);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe(kind);
    expect(charge).not.toHaveBeenCalled();
  });
});
```

Refactor this nightly job so the business rule is isolated from scheduling and storage:

```typescript
cron.schedule('0 2 * * *', async () => {
  const rows = await pool.query("SELECT id, last_login FROM users WHERE active = true");
  const cutoff = Date.now() - 90 * 24 * 3600 * 1000;
  for (const r of rows.rows) {
