### Architectural Flaws in Original Code
1. **Accrual rules inside a Lambda handler:** multipliers and tier thresholds can only be exercised by sending SQS events.
2. **Database rows as the model:** the default account and tier logic are expressed against raw MySQL result rows.
3. **No typing:** the message body and query results are untyped JavaScript objects.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/LoyaltyAccount.ts`)
```typescript
export type Tier = 'bronze' | 'silver' | 'gold';

const MULTIPLIER: { readonly [T in Tier]: number } = { bronze: 1, silver: 1.5, gold: 2 };

export class LoyaltyAccount {
  static readonly SILVER_FROM = 2_500;
  static readonly GOLD_FROM = 10_000;

  constructor(readonly customerId: string, private balance: number, private level: Tier) {}

  static opened(customerId: string): LoyaltyAccount {
    return new LoyaltyAccount(customerId, 0, 'bronze');
  }

  get points(): number { return this.balance; }
  get tier(): Tier { return this.level; }

  /** Earns points for a purchase using the tier held before the purchase. Returns the points earned. */
  earn(purchaseCents: number): number {
    const earned = Math.floor(purchaseCents / 100) * MULTIPLIER[this.level];
    this.balance += earned;
    this.level = this.balance >= LoyaltyAccount.GOLD_FROM ? 'gold'
      : this.balance >= LoyaltyAccount.SILVER_FROM ? 'silver' : 'bronze';
    return earned;
  }
}
```

#### 2. Application Layer (`src/application/AccruePoints.ts`)
```typescript
import { LoyaltyAccount } from '../domain/LoyaltyAccount';

export interface LoyaltyRepository {
  find(customerId: string): Promise<LoyaltyAccount | null>;
  save(account: LoyaltyAccount): Promise<void>;
}

export class AccruePoints {
  constructor(private readonly accounts: LoyaltyRepository) {}

  async execute(customerId: string, purchaseCents: number): Promise<number> {
    const account = (await this.accounts.find(customerId)) ?? LoyaltyAccount.opened(customerId);
    const earned = account.earn(purchaseCents);
    await this.accounts.save(account);
    return earned;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/MySqlLoyaltyRepository.ts`)
```typescript
import type { Pool, RowDataPacket } from 'mysql2/promise';
import { LoyaltyAccount, Tier } from '../domain/LoyaltyAccount';
import { LoyaltyRepository } from '../application/AccruePoints';

interface LoyaltyRow extends RowDataPacket { points: number; tier: Tier; }

export class MySqlLoyaltyRepository implements LoyaltyRepository {
  constructor(private readonly db: Pool) {}

  async find(customerId: string): Promise<LoyaltyAccount | null> {
    const [rows] = await this.db.execute<LoyaltyRow[]>(
      'SELECT points, tier FROM loyalty WHERE customer_id = ?', [customerId]);
    return rows[0] ? new LoyaltyAccount(customerId, rows[0].points, rows[0].tier) : null;
  }

  async save(a: LoyaltyAccount): Promise<void> {
    await this.db.execute(
      'INSERT INTO loyalty (customer_id, points, tier) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE points = ?, tier = ?',
      [a.customerId, a.points, a.tier, a.points, a.tier]);
  }
}
```

#### 4. Entry Point (`src/handlers/accruePoints.ts`)
```typescript
import type { SQSEvent } from 'aws-lambda';

interface OrderPlaced { customerId: string; totalCents: number; }

function isOrderPlaced(v: unknown): v is OrderPlaced {
  if (typeof v !== 'object' || v === null) return false;
  const o = v as Record<string, unknown>;
  return typeof o.customerId === 'string' && typeof o.totalCents === 'number';
}

const accruePoints = new AccruePoints(new MySqlLoyaltyRepository(pool));

export const handler = async (event: SQSEvent): Promise<void> => {
  for (const record of event.Records) {
    const order: unknown = JSON.parse(record.body);
    if (isOrderPlaced(order)) await accruePoints.execute(order.customerId, order.totalCents);
  }
};
```
The tier is promoted after the purchase, exactly as before, but now `new LoyaltyAccount('c1', 2400, 'bronze').earn(15000)` can be asserted directly (150 points, new tier `silver`).

We already use the strategy pattern for discounts, so I assumed this was SOLID. A colleague disagrees. Critique it:

```typescript
interface DiscountStrategy {
  apply(cart: Cart): number; // returns discount in cents
}

class PercentageOff implements DiscountStrategy {
  constructor(private percent: number) {}
  apply(cart: Cart) { return Math.round(cart.subtotalCents * this.percent / 100); }
}

class BuyXGetY implements DiscountStrategy {
  constructor(private sku: string, private x: number, private y: number) {}
  apply(cart: Cart) {
    const line = cart.lines.find((l) => l.sku === this.sku);
    if (!line) return 0;
    const free = Math.floor(line.qty / (this.x + this.y)) * this.y;
    return free * line.unitCents;
  }
}

class DiscountEngine {
  constructor(private strategies: DiscountStrategy[]) {}

  total(cart: Cart): number {
    let discount = 0;
    for (const s of this.strategies) {
      if (s instanceof PercentageOff && cart.customer.tier === 'staff') continue;
      if (s instanceof BuyXGetY && cart.lines.length > 20) continue;
      discount += s.apply(cart);
    }
    return Math.min(discount, cart.subtotalCents);
  }
}
```

### Critique

Your colleague is right, but only about one part. The strategy interface itself is fine; the engine undoes it.

#### What is already SOLID
- **Single Responsibility per strategy:** `PercentageOff` and `BuyXGetY` each encode one pricing rule.
- **Liskov:** both implementations honour the same contract (return a non-negative discount, never mutate the cart), so the engine can treat them uniformly.
- **Interface Segregation:** `apply(cart)` is the smallest useful interface.

#### Open/Closed Principle — violated in `DiscountEngine.total`
```text
if (s instanceof PercentageOff && cart.customer.tier === 'staff') continue;
if (s instanceof BuyXGetY && cart.lines.length > 20) continue;
```
The engine knows concrete strategy classes. Adding `FreeShippingOver` with its own eligibility rule means editing the engine again, which defeats the reason to have strategies. It also breaks quietly under change: wrap `PercentageOff` in a decorator (say, `CappedDiscount`) and the `instanceof` check stops matching, so staff suddenly receive the percentage discount.

#### Dependency Inversion — violated in a small way
The high-level `DiscountEngine` depends on low-level concretions (`PercentageOff`, `BuyXGetY`) instead of only on the `DiscountStrategy` abstraction it was given.

#### Single Responsibility — the engine has two jobs
It combines discounts *and* decides eligibility of each one. Eligibility belongs to each rule, because "staff don't get percentage promotions" is part of what that promotion is.

---

### Refactoring

Move eligibility into the abstraction, so each discount says when it applies and the engine only sums and caps.

```typescript
export interface CartLine {
  readonly sku: string;
  readonly qty: number;
  readonly unitCents: number;
}

export interface Cart {
  readonly subtotalCents: number;
  readonly lines: readonly CartLine[];
  readonly customerTier: 'standard' | 'gold' | 'staff';
}

export interface DiscountRule {
  appliesTo(cart: Cart): boolean;
  amount(cart: Cart): number;
}

export class PercentageOff implements DiscountRule {
  constructor(private readonly percent: number) {}

  appliesTo(cart: Cart): boolean {
    return cart.customerTier !== 'staff';
  }

  amount(cart: Cart): number {
    return Math.round((cart.subtotalCents * this.percent) / 100);
  }
}

export class BuyXGetY implements DiscountRule {
  constructor(
    private readonly sku: string,
    private readonly x: number,
    private readonly y: number,
    private readonly maxLines = 20,
  ) {}

  appliesTo(cart: Cart): boolean {
    return cart.lines.length <= this.maxLines && cart.lines.some((l) => l.sku === this.sku);
  }

  amount(cart: Cart): number {
    const line = cart.lines.find((l) => l.sku === this.sku);
    if (!line) return 0;
    return Math.floor(line.qty / (this.x + this.y)) * this.y * line.unitCents;
  }
}

export class DiscountEngine {
  constructor(private readonly rules: readonly DiscountRule[]) {}

  total(cart: Cart): number {
    const sum = this.rules
      .filter((rule) => rule.appliesTo(cart))
      .reduce((acc, rule) => acc + rule.amount(cart), 0);
    return Math.min(sum, cart.subtotalCents);
  }
}
```

A decorator now composes correctly because it forwards `appliesTo`:

```typescript
export class CappedDiscount implements DiscountRule {
  constructor(private readonly inner: DiscountRule, private readonly capCents: number) {}

  appliesTo(cart: Cart): boolean {
    return this.inner.appliesTo(cart);
  }

  amount(cart: Cart): number {
    return Math.min(this.inner.amount(cart), this.capCents);
  }
}
```

`DiscountEngine` has no imports of concrete rules, never changes when marketing invents a promotion, and each rule's eligibility can be checked in isolation with a literal `Cart`.

```typescript
// Domain/ValueObjects/Money.ts

export interface Currency {
  readonly code: string;
  readonly symbol: string;
  readonly decimalPlaces: number;
}

export class Money {
  private constructor(
    private readonly _amount: number,
    private readonly _currency: Currency
  ) {}

  public static create(amount: number, currency: Currency): Money {
    if (amount < 0) {
      throw new Error("Money amount must be positive");
    }

    return new Money(amount, currency);
  }

  public get amount(): number {
    return this._amount;
  }

  public get currency(): Currency {
    return this._currency;
  }

  public add(other: Money): Money {
    if (this._currency.code !== other._currency.code) {
      throw new Error("Cannot add money with different currencies");
    }

    const newAmount = this._amount + other._amount;
    return new Money(newAmount, this._currency);
  }

  public equals(other: Money): boolean {
    return (
      this._amount === other._amount &&
      this._currency.code === other._currency.code
    );
  }

  public toString(): string {
    return `${this._currency.symbol}${this._amount.toFixed(this._currency.decimalPlaces)}`;
  }
}
```

