Refactor this Koa route for hotel bookings. Overbooking and rate rules are written directly against Objection.js models:

```typescript
router.post('/hotels/:hotelId/bookings', async (ctx) => {
  const { roomType, checkIn, checkOut, guestId } = ctx.request.body as Record<string, string>;
  const inDate = new Date(checkIn);
  const outDate = new Date(checkOut);
  const nights = Math.round((outDate.getTime() - inDate.getTime()) / 86400000);
  if (nights < 1 || nights > 30) ctx.throw(400, 'Stay must be 1 to 30 nights');
  const type = await RoomType.query().findOne({ hotelId: ctx.params.hotelId, code: roomType });
  if (!type) ctx.throw(404, 'Unknown room type');
  const booked = await Booking.query().where({ roomTypeId: type.id })
    .where('checkIn', '<', outDate).where('checkOut', '>', inDate).resultSize();
  if (booked >= Math.floor(type.rooms * 1.05)) ctx.throw(409, 'Sold out');
  let total = 0;
  for (let i = 0; i < nights; i++) {
    const day = new Date(inDate.getTime() + i * 86400000).getUTCDay();
    total += day === 5 || day === 6 ? type.weekendRateCents : type.weekdayRateCents;
  }
  if (nights >= 7) total = Math.round(total * 0.9);
  ctx.status = 201;
  ctx.body = await Booking.query().insert({ roomTypeId: type.id, guestId, checkIn: inDate, checkOut: outDate, totalCents: total });
});
```

### Architectural Flaws in Original Code
1. **Revenue rules in a route:** the 5% overbooking allowance, weekend nights (Friday and Saturday) and the weekly discount are tied to Koa and Objection.
2. **`ctx.throw` as business errors:** failures are HTTP exceptions from the start.
3. **Room availability counted with an ad-hoc query** instead of a named rule.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/stay.ts`)
```typescript
import { Result } from '../shared/Result';

export type BookingError =
  | { kind: 'InvalidStay' }
  | { kind: 'UnknownRoomType' }
  | { kind: 'SoldOut' };

export interface RoomType {
  readonly id: string;
  readonly rooms: number;
  readonly weekdayRateCents: number;
  readonly weekendRateCents: number;
}

export const OVERBOOKING_FACTOR = 1.05;
export const WEEKLY_DISCOUNT = 0.9;

export class Stay {
  private constructor(readonly checkIn: Date, readonly checkOut: Date, readonly nights: number) {}

  static of(checkIn: Date, checkOut: Date): Result<Stay, BookingError> {
    const nights = Math.round((checkOut.getTime() - checkIn.getTime()) / 86_400_000);
    if (!(nights >= 1 && nights <= 30)) return Result.fail({ kind: 'InvalidStay' });
    return Result.ok(new Stay(checkIn, checkOut, nights));
  }

  priceFor(type: RoomType): number {
    let total = 0;
    for (let i = 0; i < this.nights; i++) {
      const day = new Date(this.checkIn.getTime() + i * 86_400_000).getUTCDay();
      total += day === 5 || day === 6 ? type.weekendRateCents : type.weekdayRateCents;
    }
    return this.nights >= 7 ? Math.round(total * WEEKLY_DISCOUNT) : total;
  }
}

export function hasAvailability(type: RoomType, overlappingBookings: number): boolean {
  return overlappingBookings < Math.floor(type.rooms * OVERBOOKING_FACTOR);
}
```

#### 2. Application Layer (`src/application/BookRoom.ts`)
```typescript
import { Result } from '../shared/Result';
import { BookingError, RoomType, Stay, hasAvailability } from '../domain/stay';

export interface NewBooking {
  readonly roomTypeId: string;
  readonly guestId: string;
  readonly checkIn: Date;
  readonly checkOut: Date;
  readonly totalCents: number;
}

export interface Inventory {
  roomType(hotelId: string, code: string): Promise<RoomType | null>;
  overlapping(roomTypeId: string, stay: Stay): Promise<number>;
  book(booking: NewBooking): Promise<NewBooking & { id: string }>;
}

export class BookRoom {
  constructor(private readonly inventory: Inventory) {}

  async execute(input: {
    hotelId: string; roomType: string; guestId: string; checkIn: Date; checkOut: Date;
  }): Promise<Result<NewBooking & { id: string }, BookingError>> {
    const stay = Stay.of(input.checkIn, input.checkOut);
    if (!stay.success) return stay;
    const type = await this.inventory.roomType(input.hotelId, input.roomType);
    if (!type) return Result.fail({ kind: 'UnknownRoomType' });
    if (!hasAvailability(type, await this.inventory.overlapping(type.id, stay.data))) {
      return Result.fail({ kind: 'SoldOut' });
    }
    const booking = await this.inventory.book({
      roomTypeId: type.id, guestId: input.guestId,
      checkIn: stay.data.checkIn, checkOut: stay.data.checkOut, totalCents: stay.data.priceFor(type),
    });
    return Result.ok(booking);
  }
}
```

#### 3. Infrastructure Layer
`ObjectionInventory` implements `Inventory` with the existing `RoomType.query().findOne(...)`, the overlap `resultSize()` query and `Booking.query().insert(...)`; Objection models never leave that class.

#### 4. Presentation Layer (Koa router)
```typescript
function toHttp(error: BookingError): [number, string] {
  switch (error.kind) {
    case 'InvalidStay': return [400, 'Stay must be 1 to 30 nights'];
    case 'UnknownRoomType': return [404, 'Unknown room type'];
    case 'SoldOut': return [409, 'Sold out'];
  }
}

router.post('/hotels/:hotelId/bookings', async (ctx) => {
  const body = ctx.request.body as { roomType: string; checkIn: string; checkOut: string; guestId: string };
  const result = await bookRoom.execute({
    hotelId: ctx.params.hotelId, roomType: body.roomType, guestId: body.guestId,
    checkIn: new Date(body.checkIn), checkOut: new Date(body.checkOut),
  });
  if (!result.success) {
    const [status, message] = toHttp(result.error);
    ctx.throw(status, message);
  }
  ctx.status = 201;
  ctx.body = result.data;
});
```

`Stay.of` also rejects unparseable dates (NaN nights) as `InvalidStay`, which the original let through.

### Design

The application talks about *contract documents*, not buckets and keys. The port therefore exposes three operations named after the requirement, and the adapters decide how a `ContractId` becomes an S3 key.

#### 1. Port (`src/application/ports/ContractDocumentStore.ts`)
```typescript
import { Result } from '../shared/Result';

export interface StoredDocument {
  readonly contractId: string;
  readonly contentType: 'application/pdf';
  readonly bytes: Uint8Array;
}

export type DocumentStoreError =
  | { kind: 'NotFound'; contractId: string }
  | { kind: 'TooLarge'; maxBytes: number }
  | { kind: 'StorageUnavailable'; detail: string };

export interface ContractDocumentStore {
  put(contractId: string, pdf: Uint8Array): Promise<Result<void, DocumentStoreError>>;
  get(contractId: string): Promise<Result<StoredDocument, DocumentStoreError>>;
  temporaryLink(contractId: string, validForSeconds: number): Promise<Result<string, DocumentStoreError>>;
}

export const MAX_CONTRACT_BYTES = 10 * 1024 * 1024;
```

Notes on the shape:
- `Uint8Array` instead of Node's `Buffer` or an SDK stream keeps the port runtime-agnostic.
- `temporaryLink` returns a plain URL string. Whether it's a presigned S3 URL or a route on the dev server is the adapter's concern.
- The size limit is a business rule, so it lives next to the port and every adapter enforces the same constant.

#### 2. S3 adapter (`src/infrastructure/storage/S3ContractDocumentStore.ts`)
```typescript
import { S3Client, PutObjectCommand, GetObjectCommand } from '@aws-sdk/client-s3';
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

function errorName(e: unknown): string {
  return typeof e === 'object' && e !== null && typeof Reflect.get(e, 'name') === 'string'
    ? String(Reflect.get(e, 'name'))
    : 'Unknown';
}

export class S3ContractDocumentStore implements ContractDocumentStore {
  constructor(private readonly s3: S3Client, private readonly bucket: string) {}

  private key(contractId: string): string {
    return `contracts/${contractId}/signed.pdf`;
  }

  private failure(e: unknown, contractId: string): DocumentStoreError {
    return errorName(e) === 'NoSuchKey'
      ? { kind: 'NotFound', contractId }
      : { kind: 'StorageUnavailable', detail: errorName(e) };
  }

  async put(contractId: string, pdf: Uint8Array): Promise<Result<void, DocumentStoreError>> {
    if (pdf.byteLength > MAX_CONTRACT_BYTES) return Result.fail({ kind: 'TooLarge', maxBytes: MAX_CONTRACT_BYTES });
    try {
      await this.s3.send(new PutObjectCommand({
        Bucket: this.bucket, Key: this.key(contractId), Body: pdf, ContentType: 'application/pdf',
      }));
      return Result.ok(undefined);
    } catch (e: unknown) {
      return Result.fail(this.failure(e, contractId));
    }
  }

  async get(contractId: string): Promise<Result<StoredDocument, DocumentStoreError>> {
    try {
      const out = await this.s3.send(new GetObjectCommand({ Bucket: this.bucket, Key: this.key(contractId) }));
      const bytes: Uint8Array | undefined = await out.Body?.transformToByteArray();
      if (!bytes) return Result.fail({ kind: 'NotFound', contractId });
      return Result.ok({ contractId, contentType: 'application/pdf', bytes });
    } catch (e: unknown) {
      return Result.fail(this.failure(e, contractId));
    }
  }

  async temporaryLink(contractId: string, validForSeconds: number): Promise<Result<string, DocumentStoreError>> {
    try {
      const command = new GetObjectCommand({ Bucket: this.bucket, Key: this.key(contractId) });
      const url: string = await getSignedUrl(this.s3, command, { expiresIn: validForSeconds });
      return Result.ok(url);
    } catch (e: unknown) {
      return Result.fail(this.failure(e, contractId));
    }
  }
}
```

A presigned URL is generated locally and does not check that the object exists, so the use case should call `get` or keep a "document uploaded" flag before handing out links.

#### 3. In-memory adapter (`src/infrastructure/storage/InMemoryContractDocumentStore.ts`)
Used by CI and by local development, where the dev server serves `/dev-files/:id`.

```typescript
export class InMemoryContractDocumentStore implements ContractDocumentStore {
  private readonly files = new Map<string, Uint8Array>();

  constructor(private readonly baseUrl: string) {}

  async put(contractId: string, pdf: Uint8Array): Promise<Result<void, DocumentStoreError>> {
    if (pdf.byteLength > MAX_CONTRACT_BYTES) return Result.fail({ kind: 'TooLarge', maxBytes: MAX_CONTRACT_BYTES });
    this.files.set(contractId, pdf.slice());
    return Result.ok(undefined);
  }

  async get(contractId: string): Promise<Result<StoredDocument, DocumentStoreError>> {
    const bytes = this.files.get(contractId);
    if (!bytes) return Result.fail({ kind: 'NotFound', contractId });
    return Result.ok({ contractId, contentType: 'application/pdf', bytes });
  }

  async temporaryLink(contractId: string, validForSeconds: number): Promise<Result<string, DocumentStoreError>> {
    if (!this.files.has(contractId)) return Result.fail({ kind: 'NotFound', contractId });
    return Result.ok(`${this.baseUrl}/dev-files/${encodeURIComponent(contractId)}?ttl=${validForSeconds}`);
  }
}
```

`pdf.slice()` stores a copy, so a caller mutating its array after `put` cannot change the stored document, matching what S3 would do.

#### 4. Wiring
```typescript
export function contractStore(env: { STORAGE: string; BUCKET: string; PUBLIC_URL: string }, s3: S3Client): ContractDocumentStore {
  return env.STORAGE === 's3'
    ? new S3ContractDocumentStore(s3, env.BUCKET)
    : new InMemoryContractDocumentStore(env.PUBLIC_URL);
}
```

The use case asks for `temporaryLink(id, 600)` and never learns which one it got.

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { prisma } from '../prisma';
import { sendgrid } from '../sendgrid';

export async function publishCourseGrades(courseId: string) {
  const course = await prisma.course.findUniqueOrThrow({
    where: { id: courseId },
    include: { assignments: true, enrollments: { include: { student: true, submissions: true } } },
  });
  for (const enrollment of course.enrollments) {
    let weighted = 0;
    for (const a of course.assignments) {
      const sub = enrollment.submissions.find((s) => s.assignmentId === a.id);
      let score = sub ? sub.score / a.maxScore : 0;
      if (sub && sub.submittedAt > a.dueAt) score *= 0.9;
      weighted += score * a.weight;
    }
    const percent = Math.round(weighted * 1000) / 10;
    const letter = percent >= 90 ? 'A' : percent >= 80 ? 'B' : percent >= 70 ? 'C' : percent >= 60 ? 'D' : 'F';
    await prisma.enrollment.update({ where: { id: enrollment.id }, data: { finalPercent: percent, letter } });
    await sendgrid.send({ to: enrollment.student.email, subject: `${course.name} final grade`, text: `You got ${letter} (${percent}%)` });
  }
}

```

### Architectural Flaws in Original Code
1. **Grading policy embedded in a data script:** the late penalty (10%), weighting and letter thresholds sit between Prisma and SendGrid calls.
2. **Deeply nested ORM include** shapes the whole algorithm around the database schema.
3. **Partial failure:** if a notification fails mid-loop, some grades are saved and others are not, with no record of which.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/grading.ts`)
```typescript
export interface Assignment {
  readonly id: string;
  readonly maxScore: number;
  readonly weight: number; // weights sum to 1
  readonly dueAt: Date;
}

export interface Submission {
  readonly assignmentId: string;
  readonly score: number;
  readonly submittedAt: Date;
}

export type Letter = 'A' | 'B' | 'C' | 'D' | 'F';

export interface FinalGrade { readonly percent: number; readonly letter: Letter; }

export const LATE_FACTOR = 0.9;

export function assignmentScore(a: Assignment, sub: Submission | undefined): number {
  if (!sub) return 0;
  const raw = sub.score / a.maxScore;
  return sub.submittedAt > a.dueAt ? raw * LATE_FACTOR : raw;
}

export function letterFor(percent: number): Letter {
  if (percent >= 90) return 'A';
  if (percent >= 80) return 'B';
  if (percent >= 70) return 'C';
  if (percent >= 60) return 'D';
  return 'F';
}

export function finalGrade(assignments: readonly Assignment[], submissions: readonly Submission[]): FinalGrade {
  const weighted = assignments.reduce(
    (sum, a) => sum + assignmentScore(a, submissions.find((s) => s.assignmentId === a.id)) * a.weight, 0);
  const percent = Math.round(weighted * 1000) / 10;
  return { percent, letter: letterFor(percent) };
}
```

