import { Assignment, FinalGrade, Submission, finalGrade } from '../domain/grading';

export interface CourseRoster {
  readonly name: string;
  readonly assignments: readonly Assignment[];
  readonly students: readonly { enrollmentId: string; contact: string; submissions: readonly Submission[] }[];
}

export interface GradebookRepository {
  roster(courseId: string): Promise<CourseRoster | null>;
  saveFinalGrades(grades: ReadonlyMap<string, FinalGrade>): Promise<void>; // one transaction
}

export interface GradeNotifier {
  finalGrade(contact: string, courseName: string, grade: FinalGrade): Promise<void>;
}

export class PublishCourseGrades {
  constructor(private readonly gradebook: GradebookRepository, private readonly notifier: GradeNotifier) {}

  async execute(courseId: string): Promise<number | null> {
    const roster = await this.gradebook.roster(courseId);
    if (!roster) return null;
    const grades = new Map(roster.students.map((s) => [s.enrollmentId, finalGrade(roster.assignments, s.submissions)]));
    await this.gradebook.saveFinalGrades(grades);
    for (const s of roster.students) {
      const grade = grades.get(s.enrollmentId);
      if (grade) await this.notifier.finalGrade(s.contact, roster.name, grade);
    }
    return grades.size;
  }
}
```
All grades are persisted atomically before any notification is sent. An unknown course now returns `null` instead of throwing as `findUniqueOrThrow` did; the caller decides how to report it.

