```typescript
// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class UserNotFoundError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Entities/User.ts
export class User {
  constructor(
    public id: string,
    public email: string,
    public passwordHash: string
  ) {}
}

// Application/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Application/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, err } from '../Result';
import { DomainError, InvalidPasswordError, UserNotFoundError, PasswordMismatchError } from '../../Domain/Errors/DomainError';
import { IUserRepository } from '../Ports/IUserRepository';
import { IPasswordHasher } from '../Ports/IPasswordHasher';

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(
    userId: string,
    currentPassword: string,
    newPassword: string
  ): Promise<Result<void, DomainError>> {
    // Validate input
    if (!userId || !currentPassword || !newPassword) {
      return err(new InvalidPasswordError('All fields are required'));
    }

    // Business rule: new password cannot be empty
    if (newPassword.trim() === '') {
      return err(new InvalidPasswordError('New password cannot be empty'));
    }

    // Business rule: new password must be different from current password
    const user = await this.userRepository.findById(userId);
    if (!user) {
      return err(new UserNotFoundError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      currentPassword,
      user.passwordHash
    );
    if (!isPasswordValid) {
      return err(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      newPassword,
      user.passwordHash
    );
    if (isSamePassword) {
      return err(new InvalidPasswordError('New password cannot be the same as current password'));
    }

    // Hash the new password
    const newPasswordHash = await this.passwordHasher.hash(newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends Error> = { success: true; value: T } | { success: false; error: E };

export const ok = <T>(value: T): Result<T, never> => ({ success: true, value });

export const err = <E extends Error>(error: E): Result<never, E> => ({ success: false, error });
```

This implementation follows Clean Architecture principles:

1. **Dependency Rule Enforcement**: 
   - Domain and application layers don't depend on external libraries
   - Ports (`IUserRepository`, `IPasswordHasher`) are defined in the application layer
   - Infrastructure implementations would depend on these ports

2. **Business Rules**:
   - New password cannot equal old password (enforced by comparing hashes)
   - All fields are required
   - New password cannot be empty
   - Current password must be valid

3. **Result Pattern**:
   - Uses typed `Result<void, DomainError>` return type
   - Proper error handling with domain-specific errors
   - Clear separation of success and error cases

4. **SOLID Principles**:
   - Single Responsibility: Each class has one clear purpose
   - Open/Closed: Easy to extend with new error types
   - Liskov Substitution: DomainError hierarchy maintains contract
   - Interface Segregation: Ports are minimal and focused
   - Dependency Inversion: High-level modules depend on abstractions

The use case handles all required validations and returns appropriate domain errors when business rules are violated.

The protocol math belongs to the pet's vaccination history, so the domain decides eligibility and the next due date. The use case only loads data, asks the domain, persists and schedules the reminder.

#### 1. Domain (`src/domain/vaccination.ts`)
```typescript
import { Result } from '../shared/Result';

export interface VaccineProtocol {
  readonly vaccine: string;
  readonly minAgeDays: number;
  readonly primaryDoses: number;
  readonly primaryIntervalDays: number;
  readonly boosterIntervalDays: number;
}

export interface DoseRecord {
  readonly vaccine: string;
  readonly givenAt: Date;
}

export type VaccinationError =
  | { kind: 'PetNotFound' }
  | { kind: 'UnknownVaccine'; vaccine: string }
  | { kind: 'TooYoung'; minAgeDays: number }
  | { kind: 'TooSoon'; earliest: Date };

export interface RecordedDose {
  readonly doseNumber: number;
  readonly nextDueAt: Date;
}

const DAY_MS = 86_400_000;
export const GRACE_DAYS = 4;

const addDays = (date: Date, days: number): Date => new Date(date.getTime() + days * DAY_MS);

// Gap required after the n-th dose: primary interval inside the series, booster interval after it.
function gapAfterDose(protocol: VaccineProtocol, doseCount: number): number {
  return doseCount < protocol.primaryDoses ? protocol.primaryIntervalDays : protocol.boosterIntervalDays;
}

export class Pet {
  constructor(
    readonly id: string,
    readonly ownerId: string,
    readonly birthDate: Date,
    private readonly doses: DoseRecord[],
  ) {}

  get history(): readonly DoseRecord[] {
    return this.doses;
  }

  vaccinate(protocol: VaccineProtocol, at: Date): Result<RecordedDose, VaccinationError> {
    const ageDays = Math.floor((at.getTime() - this.birthDate.getTime()) / DAY_MS);
    if (ageDays < protocol.minAgeDays) {
      return Result.fail({ kind: 'TooYoung', minAgeDays: protocol.minAgeDays });
    }

    const previous = this.doses
      .filter((d) => d.vaccine === protocol.vaccine)
      .sort((a, b) => a.givenAt.getTime() - b.givenAt.getTime());
    const last = previous[previous.length - 1];
    if (last) {
      const earliest = addDays(last.givenAt, gapAfterDose(protocol, previous.length) - GRACE_DAYS);
      if (at < earliest) return Result.fail({ kind: 'TooSoon', earliest });
    }

    this.doses.push({ vaccine: protocol.vaccine, givenAt: at });
    const doseNumber = previous.length + 1;
    return Result.ok({ doseNumber, nextDueAt: addDays(at, gapAfterDose(protocol, doseNumber)) });
  }
}
```

#### 2. Application (`src/application/RecordVaccination.ts`)
```typescript
import { Result } from '../shared/Result';
import { Pet, RecordedDose, VaccinationError, VaccineProtocol } from '../domain/vaccination';

export interface PetRepository {
  findById(id: string): Promise<Pet | null>;
  save(pet: Pet): Promise<void>;
}

export interface ProtocolCatalog {
  find(vaccine: string): Promise<VaccineProtocol | null>;
}

export interface ReminderScheduler {
  schedule(ownerId: string, petId: string, vaccine: string, dueAt: Date): Promise<void>;
}

export interface RecordVaccinationInput {
  readonly petId: string;
  readonly vaccine: string;
}

export class RecordVaccination {
  constructor(
    private readonly pets: PetRepository,
    private readonly protocols: ProtocolCatalog,
    private readonly reminders: ReminderScheduler,
    private readonly now: () => Date,
  ) {}

  async execute(input: RecordVaccinationInput): Promise<Result<RecordedDose, VaccinationError>> {
    const pet = await this.pets.findById(input.petId);
    if (!pet) return Result.fail({ kind: 'PetNotFound' });

    const protocol = await this.protocols.find(input.vaccine);
    if (!protocol) return Result.fail({ kind: 'UnknownVaccine', vaccine: input.vaccine });

    const recorded = pet.vaccinate(protocol, this.now());
    if (!recorded.success) return recorded;

    await this.pets.save(pet);
    await this.reminders.schedule(pet.ownerId, pet.id, protocol.vaccine, recorded.data.nextDueAt);
    return recorded;
  }
}
```

With DHPP, a puppy vaccinated on day 42 and again on day 60 is accepted (21 − 4 = 17 days), the third dose returns a next due date 365 days later, and a second rabies shot one month after the first fails with `TooSoon`. The repositories and the reminder scheduler are implemented in infrastructure (database, SMS/notification service); the composition root passes `() => new Date()` as the clock.

Here is our refund approval use case. Write unit tests for it: one per outcome, with the per-role limits tested right at the boundary. Fixed clock, no mocks of the Result type.

```typescript
import { Result } from '../shared/Result';

export type Role = 'agent' | 'supervisor' | 'manager';

export interface PaidOrder {
  id: string;
  paidCents: number;
  refundedCents: number;
  paidAt: Date;
}

export interface OrderReader {
  byId(id: string): Promise<PaidOrder | null>;
}

export interface RefundIssuer {
  issue(orderId: string, cents: number): Promise<void>;
}

export type RefundError =
  | { kind: 'OrderNotFound' }
  | { kind: 'WindowClosed' }
  | { kind: 'ExceedsPaid'; refundableCents: number }
  | { kind: 'AboveRoleLimit'; limitCents: number };

const LIMITS: Record<Role, number> = { agent: 10_000, supervisor: 100_000, manager: Infinity };
const WINDOW_DAYS = 30;

export class ApproveRefund {
  constructor(
    private readonly orders: OrderReader,
    private readonly issuer: RefundIssuer,
    private readonly now: () => Date,
  ) {}

  async execute(orderId: string, cents: number, role: Role): Promise<Result<void, RefundError>> {
    const order = await this.orders.byId(orderId);
    if (!order) return Result.fail({ kind: 'OrderNotFound' });
    const ageDays = (this.now().getTime() - order.paidAt.getTime()) / 86_400_000;
    if (ageDays > WINDOW_DAYS) return Result.fail({ kind: 'WindowClosed' });
    const refundableCents = order.paidCents - order.refundedCents;
    if (cents > refundableCents) return Result.fail({ kind: 'ExceedsPaid', refundableCents });
    if (cents > LIMITS[role]) return Result.fail({ kind: 'AboveRoleLimit', limitCents: LIMITS[role] });
    await this.issuer.issue(orderId, cents);
    return Result.ok(undefined);
  }
}
```

Orders live in a small in-memory reader; the issuer is a `vi.fn` because the only thing to verify is whether (and with what) it was called. The default order is large (5,000.00 paid) so the role limits, not the order total, decide the boundary cases.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ApproveRefund, OrderReader, PaidOrder, RefundIssuer, Role } from './ApproveRefund';

class InMemoryOrders implements OrderReader {
  readonly orders = new Map<string, PaidOrder>();
  async byId(id: string): Promise<PaidOrder | null> {
    return this.orders.get(id) ?? null;
  }
}

const NOW = new Date('2024-11-20T10:00:00Z');
const daysAgo = (d: number): Date => new Date(NOW.getTime() - d * 86_400_000);
const order = (overrides: Partial<PaidOrder> = {}): PaidOrder => ({
  id: 'o-1', paidCents: 500_000, refundedCents: 0, paidAt: daysAgo(3), ...overrides,
});

describe('ApproveRefund', () => {
  let orders: InMemoryOrders;
  let issue: ReturnType<typeof vi.fn<RefundIssuer['issue']>>;
  let useCase: ApproveRefund;

  beforeEach(() => {
    orders = new InMemoryOrders();
    issue = vi.fn<RefundIssuer['issue']>().mockResolvedValue(undefined);
    useCase = new ApproveRefund(orders, { issue }, () => NOW);
  });

  it.each<{ role: Role; cents: number; ok: boolean }>([
    { role: 'agent', cents: 10_000, ok: true },
    { role: 'agent', cents: 10_001, ok: false },
    { role: 'supervisor', cents: 100_000, ok: true },
    { role: 'supervisor', cents: 100_001, ok: false },
    { role: 'manager', cents: 500_000, ok: true },
  ])('$role refunding $cents cents -> allowed: $ok', async ({ role, cents, ok }) => {
    // Arrange
    orders.orders.set('o-1', order());

    // Act
    const result = await useCase.execute('o-1', cents, role);

    // Assert
    expect(result.success).toBe(ok);
    if (result.success) {
      expect(issue).toHaveBeenCalledWith('o-1', cents);
    } else {
      expect(result.error.kind).toBe('AboveRoleLimit');
      expect(issue).not.toHaveBeenCalled();
    }
  });

  it('fails with OrderNotFound for an unknown order', async () => {
    // Arrange: no orders stored

    // Act
    const result = await useCase.execute('o-404', 500, 'agent');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('OrderNotFound');
  });

  it('closes the window after 30 days', async () => {
    // Arrange
    orders.orders.set('o-1', order({ paidAt: daysAgo(31) }));

    // Act
    const result = await useCase.execute('o-1', 500, 'manager');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('WindowClosed');
  });

  it('does not refund more than what is left after earlier refunds', async () => {
    // Arrange
    orders.orders.set('o-1', order({ paidCents: 8_000, refundedCents: 5_000 }));

    // Act
    const result = await useCase.execute('o-1', 3_500, 'agent');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'ExceedsPaid', refundableCents: 3_000 });
    expect(issue).not.toHaveBeenCalled();
  });
});
```

Refactor the following javascript code to adhere strictly to Clean Architecture and Ports & Adapters:

```javascript
const { Rental, Vehicle } = require('../models');
const stripe = require('stripe')(process.env.STRIPE_KEY);

module.exports.closeRental = async (req, res) => {
  const rental = await Rental.findByPk(req.params.id, { include: Vehicle });
  if (!rental || rental.closedAt) return res.status(404).json({ error: 'Open rental not found' });
  const { odometer, fuelLevel } = req.body;
  if (odometer < rental.startOdometer) return res.status(400).json({ error: 'Odometer went backwards' });
  const days = Math.max(1, Math.ceil((Date.now() - rental.startedAt) / 86400000));
  const km = odometer - rental.startOdometer;
  const includedKm = days * 200;
  let total = days * rental.Vehicle.dailyRateCents;
  if (km > includedKm) total += (km - includedKm) * 25;
  if (fuelLevel < rental.startFuelLevel) total += Math.ceil((rental.startFuelLevel - fuelLevel) * 60) * 180;
  await stripe.paymentIntents.capture(rental.paymentIntentId, { amount_to_capture: total });
  await rental.update({ closedAt: new Date(), endOdometer: odometer, totalCents: total });
  res.json({ totalCents: total, km });
};

```

### Architectural Flaws in Original Code
1. **Pricing in an Express handler:** the daily rate, 200 km/day allowance, 25¢/km excess and fuel refill charge are untestable without Sequelize and Stripe.
2. **Stripe client created at module load** from `process.env`, so importing the file needs a key.
3. **Magic numbers:** 200, 25, 60 and 180 have no names (60 is the tank size in litres, 180 the cents per litre).

---

### Clean Architecture Refactoring (TypeScript)

#### 1. Domain Layer (`src/domain/Rental.ts`)
```typescript
import { Result } from '../shared/Result';

export type CloseError = { kind: 'NotFound' } | { kind: 'OdometerBackwards' };

export const POLICY = {
  includedKmPerDay: 200,
  excessKmCents: 25,
  tankLitres: 60,
  fuelCentsPerLitre: 180,
} as const;

export interface RentalSnapshot {
  readonly id: string;
  readonly startedAt: Date;
  readonly startOdometer: number;
  readonly startFuelLevel: number; // 0..1
  readonly dailyRateCents: number;
  readonly paymentRef: string;
}

export interface RentalBill {
  readonly days: number;
  readonly km: number;
  readonly totalCents: number;
}

export function bill(rental: RentalSnapshot, odometer: number, fuelLevel: number, now: Date): Result<RentalBill, CloseError> {
  if (odometer < rental.startOdometer) return Result.fail({ kind: 'OdometerBackwards' });
  const days = Math.max(1, Math.ceil((now.getTime() - rental.startedAt.getTime()) / 86_400_000));
  const km = odometer - rental.startOdometer;
  let total = days * rental.dailyRateCents;
  const excessKm = km - days * POLICY.includedKmPerDay;
  if (excessKm > 0) total += excessKm * POLICY.excessKmCents;
  if (fuelLevel < rental.startFuelLevel) {
    total += Math.ceil((rental.startFuelLevel - fuelLevel) * POLICY.tankLitres) * POLICY.fuelCentsPerLitre;
  }
  return Result.ok({ days, km, totalCents: total });
}
```

