import { Result } from '../shared/Result';
import { CloseError, RentalBill, RentalSnapshot, bill } from '../domain/Rental';

export interface RentalRepository {
  findOpen(id: string): Promise<RentalSnapshot | null>;
  close(id: string, closedAt: Date, endOdometer: number, totalCents: number): Promise<void>;
}

export interface PaymentCapture {
  capture(paymentRef: string, amountCents: number): Promise<void>;
}

export class CloseRental {
  constructor(
    private readonly rentals: RentalRepository,
    private readonly payments: PaymentCapture,
    private readonly now: () => Date,
  ) {}

  async execute(id: string, odometer: number, fuelLevel: number): Promise<Result<RentalBill, CloseError>> {
    const rental = await this.rentals.findOpen(id);
    if (!rental) return Result.fail({ kind: 'NotFound' });
    const now = this.now();
    const result = bill(rental, odometer, fuelLevel, now);
    if (!result.success) return result;
    await this.payments.capture(rental.paymentRef, result.data.totalCents);
    await this.rentals.close(id, now, odometer, result.data.totalCents);
    return result;
  }
}
