### Design
- **Domain:** a `StockLot` aggregate that decides whether it can be written off and how; errors are subclasses of a shared `DomainError` with a stable `code`.
- **Application:** `WriteOffExpiredLot`, which loads the lot, the staff members and the vendor policy through interfaces it owns, and records the disposal.

### Domain (`src/domain/StockLot.ts`)
```typescript
import { Result } from '../shared/Result';

export abstract class DomainError extends Error {
  abstract readonly code: string;
}

export class LotNotFound extends DomainError {
  readonly code = 'LOT_NOT_FOUND';
  constructor(lotId: string) { super(`Lot ${lotId} does not exist`); }
}

export class LotNotExpired extends DomainError {
  readonly code = 'LOT_NOT_EXPIRED';
  constructor(expiresOn: Date) { super(`Lot expires on ${expiresOn.toISOString().slice(0, 10)}`); }
}

export class LotEmpty extends DomainError {
  readonly code = 'LOT_EMPTY';
  constructor() { super('Lot has no remaining units'); }
}

export class WitnessRequired extends DomainError {
  readonly code = 'WITNESS_REQUIRED';
  constructor(reason: string) { super(reason); }
}

export type StaffRole = 'PHARMACIST' | 'TECHNICIAN';
export interface StaffMember { readonly id: string; readonly role: StaffRole; }

export type DisposalMethod = 'DESTROYED' | 'RETURNED_TO_VENDOR';

export interface Disposal {
  readonly lotId: string;
  readonly quantity: number;
  readonly method: DisposalMethod;
  readonly operatorId: string;
  readonly witnessId: string | null;
  readonly on: Date;
}

const DAY_MS = 86_400_000;
export const RETURN_WINDOW_DAYS = 90;

export class StockLot {
  constructor(
    readonly id: string,
    readonly vendorId: string,
    readonly controlled: boolean,
    readonly expiresOn: Date,
    private remaining: number,
  ) {}

  get quantity(): number { return this.remaining; }

  writeOff(
    today: Date,
    operator: StaffMember,
    witness: StaffMember | null,
    vendorAcceptsReturns: boolean,
  ): Result<Disposal, DomainError> {
    if (this.expiresOn >= today) return Result.fail(new LotNotExpired(this.expiresOn));
    if (this.remaining <= 0) return Result.fail(new LotEmpty());
    if (this.controlled) {
      if (!witness) return Result.fail(new WitnessRequired('Controlled substance needs a witness'));
      if (witness.role !== 'PHARMACIST') return Result.fail(new WitnessRequired('Witness must be a pharmacist'));
      if (witness.id === operator.id) return Result.fail(new WitnessRequired('Witness cannot be the operator'));
    }

    const daysExpired = Math.floor((today.getTime() - this.expiresOn.getTime()) / DAY_MS);
    const method: DisposalMethod =
      vendorAcceptsReturns && daysExpired <= RETURN_WINDOW_DAYS ? 'RETURNED_TO_VENDOR' : 'DESTROYED';

    const disposal: Disposal = {
      lotId: this.id,
      quantity: this.remaining,
      method,
      operatorId: operator.id,
      witnessId: witness ? witness.id : null,
      on: today,
    };
    this.remaining = 0;
    return Result.ok(disposal);
  }
}
```

### Application (`src/application/WriteOffExpiredLot.ts`)
```typescript
import { Result } from '../shared/Result';
import { DomainError, Disposal, LotNotFound, StaffMember, StockLot, WitnessRequired } from '../domain/StockLot';

export class UnknownStaffMember extends DomainError {
  readonly code = 'UNKNOWN_STAFF';
  constructor(staffId: string) { super(`Staff member ${staffId} not found`); }
}

export interface StockLotRepository {
  findById(id: string): Promise<StockLot | null>;
  save(lot: StockLot): Promise<void>;
}
export interface StaffDirectory { findById(id: string): Promise<StaffMember | null>; }
export interface VendorPolicies { acceptsReturns(vendorId: string): Promise<boolean>; }
export interface DisposalLog { record(disposal: Disposal): Promise<void>; }

export interface WriteOffInput {
  readonly lotId: string;
  readonly operatorId: string;
  readonly witnessId?: string;
}

export class WriteOffExpiredLot {
  constructor(
    private readonly lots: StockLotRepository,
    private readonly staff: StaffDirectory,
    private readonly vendors: VendorPolicies,
    private readonly log: DisposalLog,
    private readonly today: () => Date,
  ) {}

  async execute(input: WriteOffInput): Promise<Result<Disposal, DomainError>> {
    const lot = await this.lots.findById(input.lotId);
    if (!lot) return Result.fail(new LotNotFound(input.lotId));

    const operator = await this.staff.findById(input.operatorId);
    if (!operator) return Result.fail(new UnknownStaffMember(input.operatorId));

    let witness: StaffMember | null = null;
    if (input.witnessId) {
      witness = await this.staff.findById(input.witnessId);
      if (!witness) return Result.fail(new WitnessRequired(`Witness ${input.witnessId} not found`));
    }

    const disposal = lot.writeOff(this.today(), operator, witness, await this.vendors.acceptsReturns(lot.vendorId));
    if (!disposal.success) return disposal;

    await this.lots.save(lot);
    await this.log.record(disposal.data);
    return disposal;
  }
}
```

A lot that expires today is still sellable until the end of the day, hence `expiresOn >= today` is rejected. The HTTP layer can map errors by `error.code` (e.g. `LOT_NOT_EXPIRED` → 409, `WITNESS_REQUIRED` → 422) without inspecting messages.

