#### 1. Domain (`src/domain/maintenance.ts`)
```typescript
import { Result } from '../shared/Result';

export type Category = 'WATER_LEAK' | 'NO_HEAT' | 'GAS_SMELL' | 'APPLIANCE' | 'ELECTRICAL' | 'PAINT' | 'PEST' | 'OTHER';
export type Priority = 'EMERGENCY' | 'URGENT' | 'ROUTINE';

const PRIORITY: Record<Category, Priority> = {
  WATER_LEAK: 'EMERGENCY', NO_HEAT: 'EMERGENCY', GAS_SMELL: 'EMERGENCY',
  APPLIANCE: 'URGENT', ELECTRICAL: 'URGENT',
  PAINT: 'ROUTINE', PEST: 'ROUTINE', OTHER: 'ROUTINE',
};
const RESPONSE_HOURS: Record<Priority, number> = { EMERGENCY: 4, URGENT: 48, ROUTINE: 7 * 24 };
const HOUR_MS = 3_600_000;
export const MAX_OPEN_ROUTINE = 5;
export const DUPLICATE_WINDOW_HOURS = 24;

export interface OpenRequest {
  readonly id: string;
  readonly unitId: string;
  readonly tenantId: string;
  readonly category: Category;
  readonly createdAt: Date;
}

export interface NewRequest {
  readonly id: string;
  readonly unitId: string;
  readonly tenantId: string;
  readonly category: Category;
  readonly description: string;
  readonly priority: Priority;
  readonly createdAt: Date;
  readonly respondBy: Date;
}

export type MaintenanceError =
  | { kind: 'NoActiveLease' }
  | { kind: 'DescriptionLength' }
  | { kind: 'Duplicate'; existingId: string }
  | { kind: 'TooManyRoutine'; limit: number };

export function openRequest(
  draft: { id: string; unitId: string; tenantId: string; category: Category; description: string },
  open: readonly OpenRequest[],
  now: Date,
): Result<NewRequest, MaintenanceError> {
  const length = draft.description.trim().length;
  if (length < 20 || length > 2000) return Result.fail({ kind: 'DescriptionLength' });

  const windowStart = now.getTime() - DUPLICATE_WINDOW_HOURS * HOUR_MS;
  const duplicate = open.find(
    (r) => r.unitId === draft.unitId && r.category === draft.category && r.createdAt.getTime() >= windowStart,
  );
  if (duplicate) return Result.fail({ kind: 'Duplicate', existingId: duplicate.id });

  const priority = PRIORITY[draft.category];
  const openRoutine = open.filter((r) => r.tenantId === draft.tenantId && PRIORITY[r.category] === 'ROUTINE').length;
  if (priority === 'ROUTINE' && openRoutine >= MAX_OPEN_ROUTINE) {
    return Result.fail({ kind: 'TooManyRoutine', limit: MAX_OPEN_ROUTINE });
  }

  const respondBy = new Date(now.getTime() + RESPONSE_HOURS[priority] * HOUR_MS);
  return Result.ok({ ...draft, priority, createdAt: now, respondBy });
}
```

#### 2. Application (`src/application/SubmitMaintenanceRequest.ts`)
```typescript
import { Result } from '../shared/Result';
import { Category, MaintenanceError, NewRequest, OpenRequest, openRequest } from '../domain/maintenance';

export interface LeaseQuery { hasActiveLease(tenantId: string, unitId: string, on: Date): Promise<boolean>; }
export interface MaintenanceRepository {
  openForUnitOrTenant(unitId: string, tenantId: string): Promise<readonly OpenRequest[]>;
  add(request: NewRequest): Promise<void>;
}
export interface OnCallPager { page(request: NewRequest): Promise<void>; }

export interface SubmitRequestInput {
  readonly tenantId: string;
  readonly unitId: string;
  readonly category: Category;
  readonly description: string;
}

export class SubmitMaintenanceRequest {
  constructor(
    private readonly leases: LeaseQuery,
    private readonly requests: MaintenanceRepository,
    private readonly pager: OnCallPager,
    private readonly now: () => Date,
    private readonly newId: () => string,
  ) {}

  async execute(input: SubmitRequestInput): Promise<Result<NewRequest, MaintenanceError>> {
    const now = this.now();
    if (!(await this.leases.hasActiveLease(input.tenantId, input.unitId, now))) {
      return Result.fail({ kind: 'NoActiveLease' });
    }
    const open = await this.requests.openForUnitOrTenant(input.unitId, input.tenantId);
    const created = openRequest({ id: this.newId(), ...input }, open, now);
    if (!created.success) return created;

    await this.requests.add(created.data);
    if (created.data.priority === 'EMERGENCY') await this.pager.page(created.data);
    return created;
  }
}
```

#### 3. Route (`src/http/maintenanceRoute.ts`)
```typescript
import { Request, Response } from 'express';
import { Category, MaintenanceError } from '../domain/maintenance';
import { SubmitMaintenanceRequest } from '../application/SubmitMaintenanceRequest';

const CATEGORIES: readonly Category[] = ['WATER_LEAK', 'NO_HEAT', 'GAS_SMELL', 'APPLIANCE', 'ELECTRICAL', 'PAINT', 'PEST', 'OTHER'];
const isCategory = (v: unknown): v is Category => CATEGORIES.some((c) => c === v);

function toHttp(error: MaintenanceError): [number, object] {
  switch (error.kind) {
    case 'NoActiveLease': return [403, { error: 'No active lease for this unit' }];
    case 'DescriptionLength': return [422, { error: 'Description must be 20-2000 characters' }];
    case 'Duplicate': return [409, { error: 'Duplicate request', existingId: error.existingId }];
    case 'TooManyRoutine': return [429, { error: `At most ${error.limit} open routine requests` }];
  }
}

export const submitMaintenance = (useCase: SubmitMaintenanceRequest) => async (req: Request, res: Response) => {
  const { category, description } = req.body as { category?: unknown; description?: unknown };
  if (!isCategory(category) || typeof description !== 'string') return res.status(400).json({ error: 'Invalid body' });

  const result = await useCase.execute({ tenantId: String(req.params.tenantId), unitId: String(req.params.unitId), category, description });
  if (result.success) return res.status(201).json(result.data);
  const [status, body] = toHttp(result.error);
  return res.status(status).json(body);
};
```
In a real app the tenant id comes from the authenticated session, not the URL; the use case does not care where it comes from.

A stage machine is best expressed as a transition table in the domain, with the extra guards (reason, scorecards) checked in the same method. The use case loads the application, applies the transition and decides whether to notify.

### Domain (`src/domain/JobApplication.ts`)
```typescript
import { Result } from '../shared/Result';

export type Stage = 'APPLIED' | 'SCREENING' | 'INTERVIEW' | 'OFFER' | 'HIRED' | 'REJECTED' | 'WITHDRAWN';
export type Actor = 'RECRUITER' | 'CANDIDATE';

const NEXT: Partial<Record<Stage, Stage>> = {
  APPLIED: 'SCREENING',
  SCREENING: 'INTERVIEW',
  INTERVIEW: 'OFFER',
  OFFER: 'HIRED',
};
const OPEN: readonly Stage[] = ['APPLIED', 'SCREENING', 'INTERVIEW', 'OFFER'];
export const MIN_SCORECARDS = 2;
export const MIN_AVERAGE = 3.0;

export type StageError =
  | { kind: 'ApplicationNotFound' }
  | { kind: 'FinalStage'; stage: Stage }
  | { kind: 'InvalidTransition'; from: Stage; to: Stage }
  | { kind: 'NotAllowedFor'; actor: Actor }
  | { kind: 'ReasonRequired' }
  | { kind: 'InsufficientInterviews'; count: number; average: number };

export interface StageChange {
  readonly to: Stage;
  readonly actor: Actor;
  readonly reason?: string;
}

export class JobApplication {
  constructor(
    readonly id: string,
    readonly candidateId: string,
    private current: Stage,
    private readonly scores: readonly number[],
  ) {}

  get stage(): Stage { return this.current; }

  move(change: StageChange): Result<Stage, StageError> {
    const from = this.current;
    if (!OPEN.includes(from)) return Result.fail({ kind: 'FinalStage', stage: from });

    if (change.to === 'WITHDRAWN') {
      if (change.actor !== 'CANDIDATE') return Result.fail({ kind: 'NotAllowedFor', actor: change.actor });
    } else if (change.actor !== 'RECRUITER') {
      return Result.fail({ kind: 'NotAllowedFor', actor: change.actor });
    } else if (change.to === 'REJECTED') {
      if (!change.reason || change.reason.trim() === '') return Result.fail({ kind: 'ReasonRequired' });
    } else if (NEXT[from] !== change.to) {
      return Result.fail({ kind: 'InvalidTransition', from, to: change.to });
    } else if (change.to === 'OFFER') {
      const average = this.scores.length ? this.scores.reduce((a, b) => a + b, 0) / this.scores.length : 0;
      if (this.scores.length < MIN_SCORECARDS || average < MIN_AVERAGE) {
        return Result.fail({ kind: 'InsufficientInterviews', count: this.scores.length, average });
      }
    }

    this.current = change.to;
    return Result.ok(change.to);
  }
}
```

### Use case (`src/application/MoveApplicationStage.ts`)
```typescript
import { Result } from '../shared/Result';
import { JobApplication, Stage, StageChange, StageError } from '../domain/JobApplication';

export interface ApplicationRepository {
  findById(id: string): Promise<JobApplication | null>;
  save(application: JobApplication): Promise<void>;
}

export interface CandidateNotifier {
  stageChanged(candidateId: string, applicationId: string, stage: Stage, reason?: string): Promise<void>;
}

const SILENT: readonly Stage[] = ['SCREENING'];

export class MoveApplicationStage {
  constructor(private readonly applications: ApplicationRepository, private readonly notifier: CandidateNotifier) {}

  async execute(applicationId: string, change: StageChange): Promise<Result<Stage, StageError>> {
    const application = await this.applications.findById(applicationId);
    if (!application) return Result.fail({ kind: 'ApplicationNotFound' });

    const moved = application.move(change);
    if (!moved.success) return moved;

    await this.applications.save(application);
    if (!SILENT.includes(moved.data)) {
      await this.notifier.stageChanged(application.candidateId, application.id, moved.data, change.reason);
    }
    return moved;
  }
}
```
Scorecards with scores 4 and 2 average exactly 3.0 and allow the offer; a single scorecard of 5 does not. Trying to go from Screening straight to Offer fails with `InvalidTransition`, and anything after Hired fails with `FinalStage`.

```typescript
// Domain Layer - Interfaces and Types

/**
 * Domain Event interface
 * Represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly id: string;
  readonly occurredAt: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  publish(event: IDomainEvent): Promise<void>;
}

// Application Layer - Use Cases

import { Result } from './Result';

/**
 * Domain Error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'EventPublishingError';
  }
}

/**
 * Use case that demonstrates publishing a domain event
 */
export class PublishDomainEventUseCase {
  constructor(private readonly eventPublisher: IEventPublisher) {}

  async execute(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      await this.eventPublisher.publish(event);
      return Result.success<void>(undefined);
    } catch (error) {
      return Result.failure<EventPublishingError>(
        new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`)
      );
    }
  }
}

// Infrastructure Layer - Test Double Implementation

/**
 * In-memory test double implementation of IEventPublisher
 * Used for testing without external dependencies
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private readonly events: IDomainEvent[] = [];
  private readonly subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event
   * @param event The domain event to publish
   */
  async publish(event: IDomainEvent): Promise<void> {
    this.events.push(event);

    // Notify all subscribers
    this.subscribers.forEach(subscriber => subscriber(event));
  }

  /**
   * Subscribe to events for testing purposes
   * @param subscriber Function to be called when an event is published
   */
  subscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers.push(subscriber);
  }

  /**
   * Get all published events (for testing assertions)
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clear all published events (for test setup)
   */
  clear(): void {
    this.events.length = 0;
  }
}
```

This implementation follows Clean Architecture principles:

1. **Domain Layer**:
   - Defines `IDomainEvent` interface and `IEventPublisher` port
   - No dependencies on external frameworks or infrastructure

2. **Application Layer**:
   - Contains `EventPublishingError` domain error
   - `PublishDomainEventUseCase` demonstrates proper dependency injection
   - Uses `Result<T, E>` pattern for error handling

3. **Infrastructure Layer**:
   - `InMemoryEventPublisher` implements the event publisher interface
   - Provides test double functionality with subscription capability
   - Maintains in-memory event storage for testing

The implementation enforces the Dependency Rule by ensuring:
- Domain layer doesn't depend on infrastructure
- Application layer doesn't depend on external libraries
- All dependencies flow inward (from infrastructure to domain)
- The `IEventPublisher` interface is in the domain layer but implemented in infrastructure

The test double supports:
- Event publishing
- Event subscription for testing
- Event retrieval for assertions
- Test setup/cleanup capabilities

