Unit tests please, AAA style, for recording an expense against a budget category. I care most about when the 80% warning and the overspent alert fire, and that each one fires only once.

```typescript
import { Result } from '../shared/Result';

export type AlertLevel = 'warning' | 'overspent';

export interface BudgetCategory {
  id: string;
  month: string; // 'YYYY-MM'
  limitCents: number;
  spentCents: number;
  alertsSent: AlertLevel[];
}

export interface BudgetRepository {
  get(id: string): Promise<BudgetCategory | null>;
  save(category: BudgetCategory): Promise<void>;
}

export interface BudgetAlerts {
  send(categoryId: string, level: AlertLevel, spentCents: number): Promise<void>;
}

export type ExpenseError = { kind: 'InvalidAmount' } | { kind: 'CategoryNotFound' } | { kind: 'PeriodClosed' };

export class RecordExpense {
  constructor(
    private readonly budgets: BudgetRepository,
    private readonly alerts: BudgetAlerts,
    private readonly now: () => Date,
  ) {}

  async execute(categoryId: string, amountCents: number): Promise<Result<AlertLevel | null, ExpenseError>> {
    if (!Number.isInteger(amountCents) || amountCents <= 0) return Result.fail({ kind: 'InvalidAmount' });
    const category = await this.budgets.get(categoryId);
    if (!category) return Result.fail({ kind: 'CategoryNotFound' });
    if (this.now().toISOString().slice(0, 7) !== category.month) return Result.fail({ kind: 'PeriodClosed' });
    const spentCents = category.spentCents + amountCents;
    const level: AlertLevel | null =
      spentCents > category.limitCents ? 'overspent' : spentCents >= category.limitCents * 0.8 ? 'warning' : null;
    const fire = level !== null && !category.alertsSent.includes(level);
    if (fire) await this.alerts.send(category.id, level, spentCents);
    const alertsSent = fire ? [...category.alertsSent, level] : category.alertsSent;
    await this.budgets.save({ ...category, spentCents, alertsSent });
    return Result.ok(fire ? level : null);
  }
}
```

The category starts empty with a limit of 100.00, so the thresholds are 80.00 (warning) and anything above 100.00 (overspent). The repository is a map-backed fake; the alert channel is a spy. Clock: 12 March 2024, matching the category month.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { RecordExpense, AlertLevel, BudgetAlerts, BudgetCategory, BudgetRepository } from './RecordExpense';

class InMemoryBudgets implements BudgetRepository {
  readonly categories = new Map<string, BudgetCategory>();
  async get(id: string): Promise<BudgetCategory | null> {
    return this.categories.get(id) ?? null;
  }
  async save(category: BudgetCategory): Promise<void> {
    this.categories.set(category.id, category);
  }
}

const NOW = new Date('2024-03-12T09:00:00Z');
const groceries = (overrides: Partial<BudgetCategory> = {}): BudgetCategory => ({
  id: 'groceries', month: '2024-03', limitCents: 10_000, spentCents: 0, alertsSent: [], ...overrides,
});

describe('RecordExpense', () => {
  let budgets: InMemoryBudgets;
  let send: ReturnType<typeof vi.fn<BudgetAlerts['send']>>;
  let useCase: RecordExpense;

  beforeEach(() => {
    budgets = new InMemoryBudgets();
    send = vi.fn<BudgetAlerts['send']>().mockResolvedValue(undefined);
    useCase = new RecordExpense(budgets, { send }, () => NOW);
  });

  it.each<{ amount: number; fired: AlertLevel | null }>([
    { amount: 7_999, fired: null },
    { amount: 8_000, fired: 'warning' },
    { amount: 10_000, fired: 'warning' },
    { amount: 10_001, fired: 'overspent' },
  ])('spending $amount of 10000 fires $fired', async ({ amount, fired }) => {
    // Arrange
    budgets.categories.set('groceries', groceries());

    // Act
    const result = await useCase.execute('groceries', amount);

    // Assert
    expect(result).toEqual({ success: true, data: fired });
    expect(budgets.categories.get('groceries')?.spentCents).toBe(amount);
    expect(send).toHaveBeenCalledTimes(fired ? 1 : 0);
  });

  it('does not repeat a warning that was already sent', async () => {
    // Arrange
    budgets.categories.set('groceries', groceries({ spentCents: 8_500, alertsSent: ['warning'] }));

    // Act
    const result = await useCase.execute('groceries', 500);

    // Assert
    expect(result).toEqual({ success: true, data: null });
    expect(send).not.toHaveBeenCalled();
  });

  it('still sends overspent after an earlier warning', async () => {
    // Arrange
    budgets.categories.set('groceries', groceries({ spentCents: 9_000, alertsSent: ['warning'] }));

    // Act
    await useCase.execute('groceries', 1_500);

    // Assert
    expect(send).toHaveBeenCalledWith('groceries', 'overspent', 10_500);
    expect(budgets.categories.get('groceries')?.alertsSent).toEqual(['warning', 'overspent']);
  });

  it.each([0, -100, 12.5])('rejects amount %s', async (amount) => {
    // Arrange
    budgets.categories.set('groceries', groceries());

    // Act
    const result = await useCase.execute('groceries', amount);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('InvalidAmount');
  });

  it('fails with CategoryNotFound', async () => {
    // Arrange: no categories

    // Act
    const result = await useCase.execute('travel', 500);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('CategoryNotFound');
  });

  it('rejects expenses for a past month', async () => {
    // Arrange
    budgets.categories.set('groceries', groceries({ month: '2024-02' }));

    // Act
    const result = await useCase.execute('groceries', 500);

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('PeriodClosed');
  });
});
```

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { Result } from '../shared/Result';
import { Membership, MembershipError } from '../domain/Membership';

export interface MembershipRepository {
  findByUser(userId: string): Promise<Membership | null>;
  save(membership: Membership): Promise<void>;
}

export interface Clock {
  now(): Date;
}

export class PauseMembership {
  constructor(private readonly memberships: MembershipRepository, private readonly clock: Clock) {}

  async execute(userId: string, weeks: number): Promise<Result<Membership, MembershipError>> {
    const membership = await this.memberships.findByUser(userId);
    if (!membership) return Result.fail({ kind: 'NotFound' });
    const paused = membership.pause(weeks, this.clock.now());
    if (!paused.success) return paused;
    await this.memberships.save(membership);
    console.log(`Membership ${membership.id} paused for ${weeks} weeks`);
    return Result.ok(membership);
  }
}

```

### Assessment
This file already follows the Dependency Rule: it is an application-layer class that depends only on the domain (`Membership`, `MembershipError`) and on interfaces it owns (`MembershipRepository`, `Clock`). Errors are returned as `Result` values, and time is injected. A large restructuring would add nothing.

There is one small violation:

1. **`console.log` is an infrastructure concern.** The application layer writes directly to the process console, so tests produce noise and the log destination cannot be changed.

### Minimal Refactoring
Introduce an interface for the log line and inject it like the other dependencies.

```typescript
import { Result } from '../shared/Result';
import { Membership, MembershipError } from '../domain/Membership';

export interface MembershipRepository {
  findByUser(userId: string): Promise<Membership | null>;
  save(membership: Membership): Promise<void>;
}

export interface Clock {
  now(): Date;
}

export interface ActivityLog {
  membershipPaused(membershipId: string, weeks: number): void;
}

export class PauseMembership {
  constructor(
    private readonly memberships: MembershipRepository,
    private readonly clock: Clock,
    private readonly log: ActivityLog,
  ) {}

  async execute(userId: string, weeks: number): Promise<Result<Membership, MembershipError>> {
    const membership = await this.memberships.findByUser(userId);
    if (!membership) return Result.fail({ kind: 'NotFound' });
    const paused = membership.pause(weeks, this.clock.now());
    if (!paused.success) return paused;
    await this.memberships.save(membership);
    this.log.membershipPaused(membership.id, weeks);
    return Result.ok(membership);
  }
}
```

The console implementation belongs in infrastructure:

```typescript
import { ActivityLog } from '../application/PauseMembership';

export const consoleActivityLog: ActivityLog = {
  membershipPaused: (id, weeks) => console.log(`Membership ${id} paused for ${weeks} weeks`),
};
```

Everything else (the domain rule in `Membership.pause`, the repository interface and the injected clock) should stay as it is.

Design the CheckBaggage use case for the airline check-in kiosk. It must reuse this existing repository interface:

```typescript
export interface BookingRepository {
  findByRecordLocator(locator: string): Promise<{ passengerId: string; cabin: 'ECONOMY' | 'BUSINESS'; tier: 'NONE' | 'SILVER' | 'GOLD'; checkedIn: boolean } | null>;
}
```

Allowance: economy 1 bag up to 23 kg, business 2 bags up to 32 kg; GOLD members get one extra bag. Each bag beyond the allowance costs 60.00. A bag over the cabin's weight limit costs 75.00 if it is at most 32 kg; over 32 kg it cannot be checked at all. A bag whose length + width + height exceeds 158 cm costs 100.00 extra. The booking must not be checked in yet. Return each bag's fees and the total.

The fee calculation is a pure function of the cabin, the tier and the bags, so it goes in the domain. The use case resolves the booking through the existing `BookingRepository` and maps its record to domain types.

#### 1. Domain (`src/domain/baggage.ts`)
```typescript
import { Result } from '../shared/Result';

export type Cabin = 'ECONOMY' | 'BUSINESS';
export type Tier = 'NONE' | 'SILVER' | 'GOLD';

export interface Bag {
  readonly weightKg: number;
  readonly lengthCm: number;
  readonly widthCm: number;
  readonly heightCm: number;
}

export interface BagCharge {
  readonly index: number;
  readonly extraBagCents: number;
  readonly overweightCents: number;
  readonly oversizeCents: number;
}

export interface BaggageQuote {
  readonly bags: readonly BagCharge[];
  readonly totalCents: number;
}

export type BaggageError =
  | { kind: 'BookingNotFound' }
  | { kind: 'AlreadyCheckedIn' }
  | { kind: 'TooHeavy'; index: number; weightKg: number };

const ALLOWANCE: Record<Cabin, { pieces: number; maxKg: number }> = {
  ECONOMY: { pieces: 1, maxKg: 23 },
  BUSINESS: { pieces: 2, maxKg: 32 },
};
export const ABSOLUTE_MAX_KG = 32;
export const MAX_LINEAR_CM = 158;
const EXTRA_BAG_CENTS = 6_000;
const OVERWEIGHT_CENTS = 7_500;
const OVERSIZE_CENTS = 10_000;

export function quoteBaggage(cabin: Cabin, tier: Tier, bags: readonly Bag[]): Result<BaggageQuote, BaggageError> {
  const { pieces, maxKg } = ALLOWANCE[cabin];
  const freePieces = pieces + (tier === 'GOLD' ? 1 : 0);
  const charges: BagCharge[] = [];

  for (const [index, bag] of bags.entries()) {
    if (bag.weightKg > ABSOLUTE_MAX_KG) return Result.fail({ kind: 'TooHeavy', index, weightKg: bag.weightKg });
    const linear = bag.lengthCm + bag.widthCm + bag.heightCm;
    charges.push({
      index,
      extraBagCents: index >= freePieces ? EXTRA_BAG_CENTS : 0,
      overweightCents: bag.weightKg > maxKg ? OVERWEIGHT_CENTS : 0,
      oversizeCents: linear > MAX_LINEAR_CM ? OVERSIZE_CENTS : 0,
    });
  }

  const totalCents = charges.reduce((sum, c) => sum + c.extraBagCents + c.overweightCents + c.oversizeCents, 0);
  return Result.ok({ bags: charges, totalCents });
}
```

#### 2. Application (`src/application/CheckBaggage.ts`)
```typescript
import { Result } from '../shared/Result';
import { Bag, BaggageError, BaggageQuote, quoteBaggage } from '../domain/baggage';

export interface CheckBaggageInput {
  readonly recordLocator: string;
  readonly bags: readonly Bag[];
}

export class CheckBaggage {
  constructor(private readonly bookings: BookingRepository) {}

  async execute(input: CheckBaggageInput): Promise<Result<BaggageQuote, BaggageError>> {
    const booking = await this.bookings.findByRecordLocator(input.recordLocator);
    if (!booking) return Result.fail({ kind: 'BookingNotFound' });
    if (booking.checkedIn) return Result.fail({ kind: 'AlreadyCheckedIn' });
    return quoteBaggage(booking.cabin, booking.tier, input.bags);
  }
}
```

An economy GOLD passenger with bags of 20 kg, 25 kg and 18 kg (all within 158 cm) pays 75.00 for the second bag (overweight, but free as a piece) and 60.00 for the third: 135.00 in total. A 33 kg bag fails with `TooHeavy`, which the kiosk turns into "please use cargo". The use case is read-only; charging the fee belongs to a separate step after the passenger accepts the quote.

The split is pure integer arithmetic, so it is a domain function that is easy to verify by hand. The use case adds the "split only once" guard and the charging.

### Domain (`src/domain/fareSplit.ts`)
```typescript
import { Result } from '../shared/Result';

export const BOOKING_FEE_CENTS = 150;
export const MIN_RIDERS = 2;
export const MAX_RIDERS = 4;

export interface RiderLeg { readonly riderId: string; readonly meters: number; }
export interface Share { readonly riderId: string; readonly cents: number; }

export type SplitError =
  | { kind: 'RideNotFound' }
  | { kind: 'AlreadySplit' }
  | { kind: 'RiderCount'; count: number }
  | { kind: 'InvalidDistance'; riderId: string }
  | { kind: 'BookerNotRiding' }
  | { kind: 'FareBelowFee' };

export function splitFare(fareCents: number, bookerId: string, legs: readonly RiderLeg[]): Result<Share[], SplitError> {
  if (legs.length < MIN_RIDERS || legs.length > MAX_RIDERS) return Result.fail({ kind: 'RiderCount', count: legs.length });
  const bad = legs.find((l) => !Number.isInteger(l.meters) || l.meters <= 0);
  if (bad) return Result.fail({ kind: 'InvalidDistance', riderId: bad.riderId });
  if (!legs.some((l) => l.riderId === bookerId)) return Result.fail({ kind: 'BookerNotRiding' });
  if (fareCents < BOOKING_FEE_CENTS) return Result.fail({ kind: 'FareBelowFee' });

  const distancePart = fareCents - BOOKING_FEE_CENTS;
  const totalMeters = legs.reduce((sum, l) => sum + l.meters, 0);
  const feeEach = Math.floor(BOOKING_FEE_CENTS / legs.length);

  const shares = legs.map((l) => ({
    riderId: l.riderId,
    cents: Math.floor((distancePart * l.meters) / totalMeters) + feeEach,
  }));
  const leftover = fareCents - shares.reduce((sum, s) => sum + s.cents, 0);
  return Result.ok(shares.map((s) => (s.riderId === bookerId ? { ...s, cents: s.cents + leftover } : s)));
}
```

### Application (`src/application/SplitRideFare.ts`)
```typescript
import { Result } from '../shared/Result';
import { RiderLeg, Share, SplitError, splitFare } from '../domain/fareSplit';

export interface CompletedRide {
  readonly id: string;
  readonly fareCents: number;
  readonly bookerId: string;
  readonly legs: readonly RiderLeg[];
  readonly split: boolean;
}

export interface RideRepository {
  findCompleted(rideId: string): Promise<CompletedRide | null>;
  markSplit(rideId: string, shares: readonly Share[]): Promise<void>;
}

export interface RiderBilling {
  charge(riderId: string, cents: number, reference: string): Promise<void>;
}

export class SplitRideFare {
  constructor(private readonly rides: RideRepository, private readonly billing: RiderBilling) {}

  async execute(rideId: string): Promise<Result<Share[], SplitError>> {
    const ride = await this.rides.findCompleted(rideId);
    if (!ride) return Result.fail({ kind: 'RideNotFound' });
    if (ride.split) return Result.fail({ kind: 'AlreadySplit' });

    const shares = splitFare(ride.fareCents, ride.bookerId, ride.legs);
    if (!shares.success) return shares;

    await this.rides.markSplit(ride.id, shares.data);
    for (const share of shares.data) {
      await this.billing.charge(share.riderId, share.cents, `${ride.id}:${share.riderId}`);
    }
    return shares;
  }
}
```

Check: a 2,000-cent fare with A (booker) 7,000 m, B 4,000 m and C 2,000 m splits 1,850 cents as 996 / 569 / 284 plus 50 each for the fee. That sums to 1,999, so A gets the leftover cent: A 1,047, B 619, C 334, total 2,000. The ride is marked as split before charging, and the charge reference is deterministic, so a retried charge can be deduplicated by the billing implementation instead of charging a rider twice.

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    try {
      // Validate input
      if (!request.userId) {
        return error(new InvalidPasswordError('User ID is required'));
      }

      if (!request.currentPassword) {
        return error(new InvalidPasswordError('Current password is required'));
      }

      if (!request.newPassword) {
        return error(new InvalidPasswordError('New password is required'));
      }

      // Fetch user
      const user = await this.userRepository.findById(request.userId);
      if (!user) {
        return error(new PasswordMismatchError('User not found'));
      }

      // Verify current password
      const isPasswordValid = await this.passwordHasher.compare(
        request.currentPassword,
        user.passwordHash
      );

      if (!isPasswordValid) {
        return error(new PasswordMismatchError('Current password is incorrect'));
      }

      // Business rule: new password cannot equal old password
      const isSamePassword = await this.passwordHasher.compare(
        request.newPassword,
        user.passwordHash
      );

      if (isSamePassword) {
        return error(new InvalidPasswordError('New password cannot be the same as the current password'));
      }

      // Hash new password
      const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

      // Update user password
      user.passwordHash = newPasswordHash;
      await this.userRepository.update(user);

      return ok(undefined);
    } catch (err) {
      if (err instanceof DomainError) {
        return error(err);
      }
      return error(new InvalidPasswordError('Failed to change password'));
    }
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = {
  isSuccess: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value,
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error,
  };
}
```

### Domain (`src/domain/ticketPricing.ts`)
```typescript
import { Result } from '../shared/Result';

export interface Visitor {
  readonly age: number;
  readonly studentCard: boolean;
  readonly resident: boolean;
}

export interface Quote {
  readonly lines: readonly number[];
  readonly subtotalCents: number;
  readonly discountCents: number;
  readonly totalCents: number;
}

export type QuoteError =
  | { kind: 'OrderSize'; count: number }
  | { kind: 'DateInPast' };

export const MAX_VISITORS = 20;
export const GROUP_MIN_PAYING = 10;
export const GROUP_DISCOUNT = 0.15;

export function isFirstSunday(date: Date): boolean {
  return date.getDay() === 0 && date.getDate() <= 7;
}

export function priceFor(v: Visitor, freeResidentDay: boolean): number {
  if (freeResidentDay && v.resident) return 0;
  if (v.age < 6) return 0;
  if (v.age <= 17) return 900;
  if (v.age >= 65) return 1_200;
  return v.studentCard ? 1_000 : 1_800;
}

export function quoteOrder(visitors: readonly Visitor[], visitDate: Date, today: Date): Result<Quote, QuoteError> {
  if (visitors.length < 1 || visitors.length > MAX_VISITORS) {
    return Result.fail({ kind: 'OrderSize', count: visitors.length });
  }
  if (visitDate < today) return Result.fail({ kind: 'DateInPast' });

  const lines = visitors.map((v) => priceFor(v, isFirstSunday(visitDate)));
  const subtotalCents = lines.reduce((sum, c) => sum + c, 0);
  const paying = lines.filter((c) => c > 0).length;
  const discountCents = paying >= GROUP_MIN_PAYING ? Math.round(subtotalCents * GROUP_DISCOUNT) : 0;
  return Result.ok({ lines, subtotalCents, discountCents, totalCents: subtotalCents - discountCents });
}
```

### Use case (`src/application/QuoteTicketOrder.ts`)
```typescript
import { Result } from '../shared/Result';
import { Quote, QuoteError, Visitor, quoteOrder } from '../domain/ticketPricing';

export interface ResidentRegistry {
  isResidentPostalCode(postalCode: string): Promise<boolean>;
}

export interface VisitorInput {
  readonly age: number;
  readonly studentCard: boolean;
  readonly postalCode: string;
}

export class QuoteTicketOrder {
  constructor(private readonly residents: ResidentRegistry, private readonly today: () => Date) {}

  async execute(visitorsIn: readonly VisitorInput[], visitDate: Date): Promise<Result<Quote, QuoteError>> {
    const visitors: Visitor[] = [];
    for (const v of visitorsIn) {
      visitors.push({ age: v.age, studentCard: v.studentCard, resident: await this.residents.isResidentPostalCode(v.postalCode) });
    }
    return quoteOrder(visitors, visitDate, this.today());
  }
}
