### 1. Port (`src/application/ports/BookSearchIndex.ts`)

The port takes a structured query. Filter syntax, index names and `hits`/`estimatedTotalHits` are Meilisearch details and stay in the adapter.

```typescript
import { Result } from '../shared/Result';

export interface IndexedBook {
  readonly id: string;
  readonly title: string;
  readonly author: string;
  readonly year: number;
  readonly summary: string;
}

export interface BookQuery {
  readonly text: string;
  readonly author?: string;
  readonly yearFrom?: number;
  readonly yearTo?: number;
  readonly page: number;     // 1-based
  readonly pageSize: number;
}

export interface BookPage {
  readonly books: readonly IndexedBook[];
  readonly totalApprox: number;
  readonly page: number;
}

export type SearchError =
  | { kind: 'InvalidQuery'; reason: string }
  | { kind: 'IndexUnavailable'; detail: string };

export interface BookSearchIndex {
  upsert(books: readonly IndexedBook[]): Promise<Result<void, SearchError>>;
  remove(bookId: string): Promise<Result<void, SearchError>>;
  search(query: BookQuery): Promise<Result<BookPage, SearchError>>;
}

export function validateQuery(q: BookQuery): Result<BookQuery, SearchError> {
  if (q.page < 1 || q.pageSize < 1 || q.pageSize > 100) {
    return Result.fail({ kind: 'InvalidQuery', reason: 'page must be >= 1 and pageSize between 1 and 100' });
  }
  if (q.yearFrom !== undefined && q.yearTo !== undefined && q.yearFrom > q.yearTo) {
    return Result.fail({ kind: 'InvalidQuery', reason: 'yearFrom is after yearTo' });
  }
  return Result.ok(q);
}
```

`validateQuery` is shared by every adapter, so the in-memory index rejects exactly the same queries as production.

### 2. Meilisearch adapter (`src/infrastructure/search/MeiliBookSearchIndex.ts`)
```typescript
import { Index } from 'meilisearch';

function quote(value: string): string {
  return `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
}

function toFilter(q: BookQuery): string[] {
  const filters: string[] = [];
  if (q.author) filters.push(`author = ${quote(q.author)}`);
  if (q.yearFrom !== undefined) filters.push(`year >= ${Math.trunc(q.yearFrom)}`);
  if (q.yearTo !== undefined) filters.push(`year <= ${Math.trunc(q.yearTo)}`);
  return filters;
}

function describe(e: unknown): string {
  return e instanceof Error ? e.message : String(e);
}

export class MeiliBookSearchIndex implements BookSearchIndex {
  constructor(private readonly index: Index<IndexedBook>) {}

  async upsert(books: readonly IndexedBook[]): Promise<Result<void, SearchError>> {
    try {
      await this.index.addDocuments([...books], { primaryKey: 'id' });
      return Result.ok(undefined);
    } catch (e: unknown) {
      return Result.fail({ kind: 'IndexUnavailable', detail: describe(e) });
    }
  }

  async remove(bookId: string): Promise<Result<void, SearchError>> {
    try {
      await this.index.deleteDocument(bookId);
      return Result.ok(undefined);
    } catch (e: unknown) {
      return Result.fail({ kind: 'IndexUnavailable', detail: describe(e) });
    }
  }

  async search(query: BookQuery): Promise<Result<BookPage, SearchError>> {
    const valid = validateQuery(query);
    if (!valid.success) return valid;
    try {
      const res = await this.index.search(query.text, {
        filter: toFilter(query),
        limit: query.pageSize,
        offset: (query.page - 1) * query.pageSize,
      });
      const books: IndexedBook[] = res.hits.map((h: IndexedBook) => ({
        id: h.id, title: h.title, author: h.author, year: h.year, summary: h.summary,
      }));
      return Result.ok({ books, totalApprox: res.estimatedTotalHits ?? books.length, page: query.page });
    } catch (e: unknown) {
      return Result.fail({ kind: 'IndexUnavailable', detail: describe(e) });
    }
  }
}
```

Two details the controllers used to get wrong:
- **Escaping:** an author like `O"Brien` broke the hand-built filter string. `quote()` escapes it in one place.
- **Hit shape:** Meilisearch adds `_formatted` and ranking fields to hits; the adapter copies only the fields the port promises.

`addDocuments` is asynchronous on the Meilisearch side (it returns an enqueued task). If a caller must search immediately after indexing, the adapter can wait for the task; the port does not need to change.

### 3. In-memory adapter (`src/infrastructure/search/InMemoryBookSearchIndex.ts`)
```typescript
export class InMemoryBookSearchIndex implements BookSearchIndex {
  private readonly books = new Map<string, IndexedBook>();

  async upsert(books: readonly IndexedBook[]): Promise<Result<void, SearchError>> {
    for (const b of books) this.books.set(b.id, b);
    return Result.ok(undefined);
  }

  async remove(bookId: string): Promise<Result<void, SearchError>> {
    this.books.delete(bookId);
    return Result.ok(undefined);
  }

  async search(query: BookQuery): Promise<Result<BookPage, SearchError>> {
    const valid = validateQuery(query);
    if (!valid.success) return valid;
    const words = query.text.toLowerCase().split(/\s+/).filter(Boolean);
    const matches = [...this.books.values()].filter((b) => {
      const text = `${b.title} ${b.author} ${b.summary}`.toLowerCase();
      return words.every((w) => text.includes(w))
        && (query.author === undefined || b.author === query.author)
        && (query.yearFrom === undefined || b.year >= query.yearFrom)
        && (query.yearTo === undefined || b.year <= query.yearTo);
    });
    const start = (query.page - 1) * query.pageSize;
    return Result.ok({ books: matches.slice(start, start + query.pageSize), totalApprox: matches.length, page: query.page });
  }
}
```

It has no typo tolerance or ranking, and that's fine: tests built on it check *which filters apply and how paging works*, not relevance. Relevance is tested once, against a real Meilisearch container, in the adapter's integration test.

Refactor this Next.js API handler that validates, queries MongoDB and formats the response in one function:

```typescript
async function handler(req, res) {
  const { sku, qty } = req.body;
  if (!sku || qty < 1) return res.status(400).end();
  const item = await mongo.collection('stock').findOne({ sku });
  if (!item || item.available < qty) return res.status(409).json({ error: 'Out of stock' });
  await mongo.collection('stock').updateOne({ sku }, { $inc: { available: -qty } });
  res.json({ reserved: qty, left: item.available - qty });
}
```

### Architectural Flaws in Original Code
1. **Stock rule in the handler:** the "enough units available" decision is core business logic.
2. **Driver coupling:** MongoDB calls are made directly from the HTTP layer.
3. **Race condition:** read-then-update lets two requests reserve the same units. The repository must make the decrement atomic.

---

### Clean Architecture Refactoring

#### 1. Domain (`src/domain/StockItem.ts`)
```typescript
export class StockItem {
  constructor(public readonly sku: string, public readonly available: number) {}

  canReserve(qty: number): boolean {
    return Number.isInteger(qty) && qty >= 1 && this.available >= qty;
  }
}
```

#### 2. Application (`src/application/ReserveStockUseCase.ts`)
```typescript
import { StockItem } from '../domain/StockItem';

export interface IStockRepository {
  find(sku: string): Promise<StockItem | null>;
  /** Atomically decrements; returns false when the stock changed underneath. */
  tryDecrement(sku: string, qty: number): Promise<boolean>;
}

export class ReserveStockUseCase {
  constructor(private readonly stock: IStockRepository) {}

  async execute(sku: string, qty: number): Promise<{ reserved: number; left: number }> {
    const item = await this.stock.find(sku);
    if (!item || !item.canReserve(qty)) throw new Error('Out of stock');
    if (!(await this.stock.tryDecrement(sku, qty))) throw new Error('Out of stock');
    return { reserved: qty, left: item.available - qty };
  }
}
```

#### 3. Infrastructure (atomic decrement) and controller
```typescript
/** The only part of the MongoDB collection API this adapter needs. */
interface StockCollection {
  findOne(filter: { sku: string }): Promise<{ sku: string; available: number } | null>;
  updateOne(
    filter: { sku: string; available: { $gte: number } },
    update: { $inc: { available: number } },
  ): Promise<{ modifiedCount: number }>;
}

class MongoStockRepository implements IStockRepository {
  constructor(private readonly collection: StockCollection) {}

  async find(sku: string): Promise<StockItem | null> {
    const doc = await this.collection.findOne({ sku });
    return doc ? new StockItem(doc.sku, doc.available) : null;
  }

  async tryDecrement(sku: string, qty: number): Promise<boolean> {
    const result = await this.collection.updateOne(
      { sku, available: { $gte: qty } },
      { $inc: { available: -qty } },
    );
    return result.modifiedCount === 1;
  }
}

interface ApiRequest { body: { sku: string; qty: number } }
interface ApiResponse {
  json(body: unknown): void;
  status(code: number): ApiResponse;
}

async function handler(req: ApiRequest, res: ApiResponse) {
  try {
    res.json(await reserveStock.execute(req.body.sku, req.body.qty));
  } catch (error) {
    res.status(409).json({ error: (error as Error).message });
  }
}
```

Flag keys are string literals scattered across services and every service imports the LaunchDarkly SDK. How would you put feature flags behind a port with a LaunchDarkly adapter? Example of today's code:

```typescript
const useNewPricing = await ld.variation('pricing-v2', { key: user.id, custom: { plan: user.plan } }, false);
const maxSeats = await ld.variation('team-max-seats', { key: user.id }, 5);
```

### Port design

Two things should move out of the services: the SDK and the stringly-typed keys. The port is typed per flag, so a typo in a key or a wrong default type is a compile error.

#### 1. Flag catalogue and port (`src/application/ports/FeatureFlags.ts`)
```typescript
export interface FlagContext {
  readonly userId: string;
  readonly plan: 'free' | 'team' | 'enterprise';
}

/** Every flag the application knows, with its type and safe default. */
export const FLAGS = {
  pricingV2: { key: 'pricing-v2', fallback: false },
  teamMaxSeats: { key: 'team-max-seats', fallback: 5 },
} as const;

export type FlagName = keyof typeof FLAGS;
export type FlagValue<N extends FlagName> = (typeof FLAGS)[N]['fallback'] extends boolean ? boolean : number;

export interface FeatureFlags {
  get<N extends FlagName>(name: N, context: FlagContext): Promise<FlagValue<N>>;
}
```

Why no `Result` here? A flag lookup must never block a request. If the provider fails, the correct business behaviour is "use the safe default", so the port guarantees a value and the adapter is responsible for falling back. Errors are reported, not returned.

#### 2. LaunchDarkly adapter (`src/infrastructure/flags/LaunchDarklyFlags.ts`)
```typescript
import { LDClient } from '@launchdarkly/node-server-sdk';

export interface FlagErrorReporter {
  flagFailed(name: string, reason: string): void;
}

export class LaunchDarklyFlags implements FeatureFlags {
  constructor(private readonly client: LDClient, private readonly report: FlagErrorReporter) {}

  async get<N extends FlagName>(name: N, context: FlagContext): Promise<FlagValue<N>> {
    const flag = FLAGS[name];
    const fallback = flag.fallback as FlagValue<N>;
    const ldContext = { kind: 'user', key: context.userId, plan: context.plan };
    try {
      const raw: unknown = await this.client.variation(flag.key, ldContext, flag.fallback);
      if (typeof raw !== typeof flag.fallback) {
        this.report.flagFailed(name, `expected ${typeof flag.fallback}, got ${typeof raw}`);
        return fallback;
      }
      return raw as FlagValue<N>;
    } catch (e: unknown) {
      this.report.flagFailed(name, e instanceof Error ? e.message : String(e));
      return fallback;
    }
  }
}
```

The adapter owns the vendor's context format (`kind`, `key`, custom attributes) and the type check: if someone changes `team-max-seats` to a string variation in the LaunchDarkly dashboard, the application keeps getting the numeric default and an alert fires, instead of `"10" > 5` comparisons going wrong silently.

The cast `raw as FlagValue<N>` is the one place where the runtime check (`typeof raw === typeof fallback`) is stronger than what TypeScript can express for a generic, so it is kept inside the adapter.

#### 3. Fixed-value adapter for tests and local runs
```typescript
export class StaticFlags implements FeatureFlags {
  constructor(private readonly overrides: { [N in FlagName]?: FlagValue<N> } = {}) {}

  async get<N extends FlagName>(name: N, _context: FlagContext): Promise<FlagValue<N>> {
    const value = this.overrides[name];
    return value !== undefined ? (value as FlagValue<N>) : (FLAGS[name].fallback as FlagValue<N>);
  }
}
```

A test for the new pricing path reads `new StaticFlags({ pricingV2: true })`; there is no SDK to mock and no network.

#### 4. Calling code
```typescript
export async function seatLimitFor(flags: FeatureFlags, context: FlagContext): Promise<number> {
  const limit = await flags.get('teamMaxSeats', context);
  return context.plan === 'enterprise' ? Infinity : limit;
}
```

`flags.get('teamMaxSeat', ...)` (typo) no longer compiles, and `limit` is inferred as `number`. Adding a flag means one line in `FLAGS`; retiring one means deleting that line and fixing every compile error, which doubles as a list of the code paths to clean up.

The bonus formula below has a threshold, an accelerator above quota and a cap. Write isolated unit tests that pin each of those down with concrete numbers, AAA style, plus the error cases.

```typescript
import { Result } from '../shared/Result';

export interface SalesPeriod {
  id: string;
  repId: string;
  quotaCents: number;
  salesCents: number;
  closedAt: Date | null;
}

export interface PeriodRepository {
  find(id: string): Promise<SalesPeriod | null>;
}

export interface BonusLedger {
  alreadyPaid(periodId: string, repId: string): Promise<boolean>;
  record(periodId: string, repId: string, cents: number): Promise<void>;
}

export type BonusError =
  | { kind: 'PeriodNotFound' }
  | { kind: 'PeriodOpen' }
  | { kind: 'InvalidQuota' }
  | { kind: 'AlreadyPaid' };

const THRESHOLD = 0.8;
const BASE_RATE = 0.05;
const ACCELERATOR_RATE = 0.1;
const CAP_CENTS = 2_000_000;

export class CalculateSalesBonus {
  constructor(
    private readonly periods: PeriodRepository,
    private readonly ledger: BonusLedger,
    private readonly now: () => Date,
  ) {}

  async execute(periodId: string): Promise<Result<number, BonusError>> {
    const period = await this.periods.find(periodId);
    if (!period) return Result.fail({ kind: 'PeriodNotFound' });
    if (!period.closedAt || period.closedAt > this.now()) return Result.fail({ kind: 'PeriodOpen' });
    if (period.quotaCents <= 0) return Result.fail({ kind: 'InvalidQuota' });
    if (await this.ledger.alreadyPaid(period.id, period.repId)) return Result.fail({ kind: 'AlreadyPaid' });
    const { salesCents, quotaCents } = period;
    let bonus = 0;
    if (salesCents / quotaCents >= THRESHOLD) {
      bonus = salesCents * BASE_RATE + Math.max(0, salesCents - quotaCents) * ACCELERATOR_RATE;
    }
    const cents = Math.min(Math.round(bonus), CAP_CENTS);
    await this.ledger.record(period.id, period.repId, cents);
    return Result.ok(cents);
  }
}
```

The quota is 10,000.00 (1,000,000 cents) in the table, so the rows read as "sold X, earns Y": below 80% nothing, at 80% the base 5%, above quota an extra 10% on the excess, and a large deal hits the 20,000.00 cap. The ledger fake stores recorded bonuses in a map, which is also how `alreadyPaid` answers.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { CalculateSalesBonus, BonusLedger, PeriodRepository, SalesPeriod } from './CalculateSalesBonus';

class InMemoryPeriods implements PeriodRepository {
  readonly periods = new Map<string, SalesPeriod>();
  async find(id: string): Promise<SalesPeriod | null> {
    return this.periods.get(id) ?? null;
  }
}

class InMemoryLedger implements BonusLedger {
  readonly entries = new Map<string, number>();
  async alreadyPaid(periodId: string, repId: string): Promise<boolean> {
    return this.entries.has(`${periodId}/${repId}`);
  }
  async record(periodId: string, repId: string, cents: number): Promise<void> {
    this.entries.set(`${periodId}/${repId}`, cents);
  }
}

const NOW = new Date('2024-07-02T08:00:00Z');
const closedQ2 = (overrides: Partial<SalesPeriod> = {}): SalesPeriod => ({
  id: 'Q2', repId: 'rep-1', quotaCents: 1_000_000, salesCents: 1_000_000,
  closedAt: new Date('2024-07-01T00:00:00Z'), ...overrides,
});

describe('CalculateSalesBonus', () => {
  let periods: InMemoryPeriods;
  let ledger: InMemoryLedger;
  let useCase: CalculateSalesBonus;

  beforeEach(() => {
    periods = new InMemoryPeriods();
    ledger = new InMemoryLedger();
    useCase = new CalculateSalesBonus(periods, ledger, () => NOW);
  });

  it.each([
    { sales: 799_999, bonus: 0 },
    { sales: 800_000, bonus: 40_000 },
    { sales: 1_000_000, bonus: 50_000 },
    { sales: 1_200_000, bonus: 80_000 },
    { sales: 15_000_000, bonus: 2_000_000 },
  ])('sales of $sales earn $bonus', async ({ sales, bonus }) => {
    // Arrange
    periods.periods.set('Q2', closedQ2({ salesCents: sales }));

    // Act
    const result = await useCase.execute('Q2');

    // Assert
    expect(result).toEqual({ success: true, data: bonus });
    expect(ledger.entries.get('Q2/rep-1')).toBe(bonus);
  });

  it('fails with PeriodNotFound', async () => {
    // Arrange: no periods

    // Act
    const result = await useCase.execute('Q9');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('PeriodNotFound');
  });

  it.each([
    { label: 'not closed', closedAt: null },
    { label: 'closing later', closedAt: new Date('2024-07-03T00:00:00Z') },
  ])('fails with PeriodOpen when $label', async ({ closedAt }) => {
    // Arrange
    periods.periods.set('Q2', closedQ2({ closedAt }));

    // Act
    const result = await useCase.execute('Q2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('PeriodOpen');
    expect(ledger.entries.size).toBe(0);
  });

  it('fails with InvalidQuota for a zero quota', async () => {
    // Arrange
    periods.periods.set('Q2', closedQ2({ quotaCents: 0 }));

    // Act
    const result = await useCase.execute('Q2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('InvalidQuota');
  });

  it('fails with AlreadyPaid and keeps the first amount', async () => {
    // Arrange
    periods.periods.set('Q2', closedQ2({ salesCents: 1_200_000 }));
    await ledger.record('Q2', 'rep-1', 12_345);

    // Act
    const result = await useCase.execute('Q2');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AlreadyPaid');
    expect(ledger.entries.get('Q2/rep-1')).toBe(12_345);
  });
});
```

Please critique this document renderer hierarchy using SOLID, with particular attention to inheritance:

```typescript
class DocumentRenderer {
  protected pageWidth = 210;

  renderTitle(title: string): string { return `<h1>${title}</h1>`; }
  renderParagraph(text: string): string { return `<p>${text}</p>`; }
  renderTable(rows: string[][]): string {
    return `<table>${rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('')}</table>`;
  }
  setPageWidth(mm: number) { this.pageWidth = mm; }

  render(doc: Doc): string {
    return [this.renderTitle(doc.title), ...doc.blocks.map((b) =>
      b.type === 'table' ? this.renderTable(b.rows) : this.renderParagraph(b.text))].join('\n');
  }
}

class MarkdownRenderer extends DocumentRenderer {
  renderTitle(title: string) { return `# ${title}`; }
  renderParagraph(text: string) { return text; }
  renderTable(rows: string[][]) { return rows.map((r) => `| ${r.join(' | ')} |`).join('\n'); }
  setPageWidth() { throw new Error('Markdown has no pages'); }
}

class PlainTextRenderer extends MarkdownRenderer {
  renderTitle(title: string) { return title.toUpperCase(); }
  renderTable(rows: string[][]) { return rows.map((r) => r.join('\t')).join('\n'); }
}
```

### SOLID Critique

#### Liskov Substitution Principle — violated by `setPageWidth`
`DocumentRenderer` promises that `setPageWidth(mm)` works. `MarkdownRenderer` throws, and `PlainTextRenderer` inherits the throw. Any code like
```text
renderer.setPageWidth(settings.paper === 'letter' ? 216 : 210);
```
works for HTML and crashes for the other two, so a `DocumentRenderer` variable can't safely hold every subtype.

#### Interface Segregation — the root cause
Page geometry is a concern of paged formats only. Putting `pageWidth` in the base class forces formats without pages to "implement" it. The LSP violation is a symptom of the fat base class.

#### Inheritance used for code reuse, not for "is-a"
`PlainTextRenderer extends MarkdownRenderer` only to borrow `renderParagraph` (which returns `text` unchanged). Plain text is not a kind of Markdown: if someone later escapes `*` and `_` in Markdown paragraphs, plain text output gains stray backslashes. That is a change in one format breaking another, the coupling inheritance was supposed to avoid.

#### Open/Closed — violated in `render`
`b.type === 'table' ? ... : ...` treats every non-table block as a paragraph. Adding a `code` or `list` block means editing the base `render` method and every subclass, and until then a list silently renders as a paragraph.

#### Not violated: Single Responsibility
Each renderer has one job, turning a `Doc` into one textual format. That part is fine.

---

### Refactoring

Prefer composition: a `render` function walks the document and asks a small `Format` for each block. Paged output is a separate, optional capability.

```typescript
export type Block =
  | { readonly type: 'paragraph'; readonly text: string }
  | { readonly type: 'table'; readonly rows: readonly (readonly string[])[] };

export interface Doc {
  readonly title: string;
  readonly blocks: readonly Block[];
}

export interface Format {
  title(text: string): string;
  paragraph(text: string): string;
  table(rows: readonly (readonly string[])[]): string;
}

export interface PageLayout {
  readonly pageWidthMm: number;
}

export function renderDoc(doc: Doc, format: Format): string {
  const blocks = doc.blocks.map((block): string => {
    switch (block.type) {
      case 'paragraph':
        return format.paragraph(block.text);
      case 'table':
        return format.table(block.rows);
    }
  });
  return [format.title(doc.title), ...blocks].join('\n');
}
```

The `switch` over a discriminated union is checked by the compiler: adding `{ type: 'code' }` to `Block` makes every incomplete `switch` and every `Format` lacking a `code()` method fail to compile, instead of silently falling back to a paragraph.

```typescript
export const markdown: Format = {
  title: (text) => `# ${text}`,
  paragraph: (text) => text,
  table: (rows) => rows.map((r) => `| ${r.join(' | ')} |`).join('\n'),
};

export const plainText: Format = {
  title: (text) => text.toUpperCase(),
  paragraph: (text) => text,
  table: (rows) => rows.map((r) => r.join('\t')).join('\n'),
};

export class HtmlFormat implements Format {
  constructor(readonly layout: PageLayout) {}

  title(text: string): string { return `<h1>${text}</h1>`; }
  paragraph(text: string): string { return `<p>${text}</p>`; }
  table(rows: readonly (readonly string[])[]): string {
    const body = rows.map((r) => `<tr>${r.map((c) => `<td>${c}</td>`).join('')}</tr>`).join('');
    return `<table style="width:${this.layout.pageWidthMm}mm">${body}</table>`;
  }
}
```

Only `HtmlFormat` receives a `PageLayout`, through its constructor and immutably, so there is no setter to misuse and no format has to pretend it understands pages. `plainText` no longer inherits from `markdown`; repeating `(text) => text` is cheaper than coupling two formats that evolve for different reasons.

```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    try {
      // Validate input
      if (!request.userId) {
        return error(new InvalidPasswordError('User ID is required'));
      }

      if (!request.currentPassword) {
        return error(new InvalidPasswordError('Current password is required'));
      }

      if (!request.newPassword) {
        return error(new InvalidPasswordError('New password is required'));
      }

      // Fetch user
      const user = await this.userRepository.findById(request.userId);
      if (!user) {
        return error(new PasswordMismatchError('User not found'));
      }

      // Verify current password
      const isPasswordValid = await this.passwordHasher.compare(
        request.currentPassword,
        user.passwordHash
      );

      if (!isPasswordValid) {
        return error(new PasswordMismatchError('Current password is incorrect'));
      }

      // Business rule: new password cannot equal old password
      const isSamePassword = await this.passwordHasher.compare(
        request.newPassword,
        user.passwordHash
      );

      if (isSamePassword) {
        return error(new InvalidPasswordError('New password cannot be the same as the current password'));
      }

      // Hash new password
      const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

      // Update user with new password hash
      const updatedUser: User = {
        ...user,
        passwordHash: newPasswordHash
      };

      await this.userRepository.update(updatedUser);

      return ok(undefined);
    } catch (err) {
      if (err instanceof DomainError) {
        return error(err);
      }
      return error(new InvalidPasswordError('Failed to change password'));
    }
  }
}

// Application/Result.ts
export type Result<T, E extends DomainError> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    isError: false,
    value
  };
}

export function error<E extends DomainError>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    isError: true,
    error
  };
}
```

Refactor the following typescript code to adhere strictly to Clean Architecture and Ports & Adapters:

```typescript
import { Injectable, BadRequestException } from '@nestjs/common';
import { InjectModel } from '@nestjs/mongoose';
import { Model } from 'mongoose';
import { HttpService } from '@nestjs/axios';
import { firstValueFrom } from 'rxjs';
import { Quote } from './quote.schema';

@Injectable()
export class QuoteService {
  constructor(@InjectModel(Quote.name) private quotes: Model<Quote>, private http: HttpService) {}

  async quote(dto: { driverAge: number; licenseYears: number; vehicleValue: number; zip: string }) {
    if (dto.driverAge < 18) throw new BadRequestException('Driver must be an adult');
    const { data } = await this.http.get(`https://risk.internal/zip/${dto.zip}`).toPromise();
    let premium = dto.vehicleValue * 0.035;
    if (dto.driverAge < 25) premium *= 1.6;
    if (dto.licenseYears < 2) premium *= 1.3;
    premium *= data.riskFactor;
    premium = Math.max(300, Math.round(premium));
    const doc = await this.quotes.create({ ...dto, premium, validUntil: new Date(Date.now() + 30 * 86400000) });
    return { id: doc.id, premium, validUntil: doc.validUntil };
  }
}

```

### Architectural Flaws in Original Code
1. **Underwriting rules in a NestJS service:** the base rate, young-driver and new-licence loadings and the 300 minimum premium are tied to `@Injectable`, Mongoose and `HttpService`.
2. **Deprecated, untyped HTTP call:** `.toPromise()` is deprecated, `data` is untyped, and `firstValueFrom` is imported but unused.
3. **Framework exception for a business rule:** `BadRequestException` is thrown from the core logic.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/premium.ts`)
```typescript
import { Result } from '../shared/Result';

export interface DriverProfile {
  readonly driverAge: number;
  readonly licenseYears: number;
  readonly vehicleValue: number;
}

export type QuoteError = { kind: 'UnderageDriver' };

export const RATING = {
  baseRate: 0.035,
  youngDriverAge: 25,
  youngDriverLoading: 1.6,
  newLicenceYears: 2,
  newLicenceLoading: 1.3,
  minimumPremium: 300,
  validityDays: 30,
} as const;

export function checkEligibility(driver: DriverProfile): Result<DriverProfile, QuoteError> {
  return driver.driverAge < 18 ? Result.fail({ kind: 'UnderageDriver' }) : Result.ok(driver);
}

export function annualPremium(driver: DriverProfile, zipRiskFactor: number): number {
  let premium = driver.vehicleValue * RATING.baseRate;
  if (driver.driverAge < RATING.youngDriverAge) premium *= RATING.youngDriverLoading;
  if (driver.licenseYears < RATING.newLicenceYears) premium *= RATING.newLicenceLoading;
  premium *= zipRiskFactor;
  return Math.max(RATING.minimumPremium, Math.round(premium));
}
```

#### 2. Application Layer (`src/application/QuotePremium.ts`)
```typescript
import { Result } from '../shared/Result';
import { DriverProfile, QuoteError, RATING, annualPremium, checkEligibility } from '../domain/premium';

export interface IssuedQuote { readonly id: string; readonly premium: number; readonly validUntil: Date; }

export interface RiskByZip { factorFor(zip: string): Promise<number>; }
export interface QuoteRepository {
  save(input: DriverProfile & { zip: string; premium: number; validUntil: Date }): Promise<string>;
}

export class QuotePremium {
  constructor(private readonly risk: RiskByZip, private readonly quotes: QuoteRepository, private readonly now: () => Date) {}

  async execute(input: DriverProfile & { zip: string }): Promise<Result<IssuedQuote, QuoteError>> {
    const eligible = checkEligibility(input);
    if (!eligible.success) return eligible;
    const premium = annualPremium(input, await this.risk.factorFor(input.zip));
    const validUntil = new Date(this.now().getTime() + RATING.validityDays * 86_400_000);
    const id = await this.quotes.save({ ...input, premium, validUntil });
    return Result.ok({ id, premium, validUntil });
  }
}
```
The age check runs before the risk lookup, as before, so an underage request makes no remote call.

