  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  static from(
    id: string,
    userId: string,
    status: 'active' | 'cancelled' | 'expired',
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      status,
      startDate,
      endDate,
      plan
    );
  }

  isExpired(): boolean {
    return new Date() > this.endDate;
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
