### 1. Port (`src/application/ports/OrderEventPublisher.ts`)

The port publishes **integration events**: versioned, serialisable messages that other teams consume. Exchanges, routing keys, topic ARNs and message attributes are transport details that each adapter derives from the event.

```typescript
import { Result } from '../shared/Result';

export type OrderEvent =
  | {
      readonly type: 'OrderPlaced';
      readonly version: 1;
      readonly eventId: string;
      readonly occurredAt: string; // ISO-8601
      readonly orderId: string;
      readonly customerId: string;
      readonly totalCents: number;
    }
  | {
      readonly type: 'OrderShipped';
      readonly version: 1;
      readonly eventId: string;
      readonly occurredAt: string;
      readonly orderId: string;
      readonly carrier: string;
      readonly trackingCode: string;
    };

export type PublishError =
  | { kind: 'BrokerUnavailable'; detail: string }
  | { kind: 'Rejected'; eventId: string; detail: string };

export interface OrderEventPublisher {
  publish(event: OrderEvent): Promise<Result<void, PublishError>>;
}
```

`eventId` lets consumers deduplicate, since both brokers deliver at least once. `version` is part of the contract so the payload can evolve without breaking other teams.

### 2. RabbitMQ adapter (`src/infrastructure/messaging/RabbitOrderEventPublisher.ts`)
Uses a confirm channel, so `publish` resolves only after the broker has accepted the message.

```typescript
import { ConfirmChannel } from 'amqplib';

function routingKey(event: OrderEvent): string {
  return `orders.${event.type.replace(/^Order/, '').toLowerCase()}.v${event.version}`; // orders.placed.v1
}

export class RabbitOrderEventPublisher implements OrderEventPublisher {
  constructor(private readonly channel: ConfirmChannel, private readonly exchange = 'orders') {}

  publish(event: OrderEvent): Promise<Result<void, PublishError>> {
    const body = Buffer.from(JSON.stringify(event));
    return new Promise((resolve) => {
      try {
        this.channel.publish(
          this.exchange,
          routingKey(event),
          body,
          { persistent: true, messageId: event.eventId, type: event.type, contentType: 'application/json' },
          (err: unknown) => {
            resolve(err
              ? Result.fail({ kind: 'Rejected', eventId: event.eventId, detail: String(err) })
              : Result.ok(undefined));
          },
        );
      } catch (e: unknown) {
        resolve(Result.fail({ kind: 'BrokerUnavailable', detail: e instanceof Error ? e.message : String(e) }));
      }
    });
  }
}
```

A closed channel throws synchronously (`BrokerUnavailable`); a broker nack arrives through the confirm callback (`Rejected`).

### 3. SNS adapter (`src/infrastructure/messaging/SnsOrderEventPublisher.ts`)
```typescript
import { SNSClient, PublishCommand } from '@aws-sdk/client-sns';

function awsErrorName(e: unknown): string {
  return typeof e === 'object' && e !== null && typeof Reflect.get(e, 'name') === 'string'
    ? String(Reflect.get(e, 'name'))
    : 'UnknownError';
}

const UNAVAILABLE = new Set(['ThrottledException', 'InternalErrorException', 'TimeoutError']);

export class SnsOrderEventPublisher implements OrderEventPublisher {
  constructor(private readonly sns: SNSClient, private readonly topicArn: string) {}

  async publish(event: OrderEvent): Promise<Result<void, PublishError>> {
    try {
      await this.sns.send(new PublishCommand({
        TopicArn: this.topicArn,
        Message: JSON.stringify(event),
        MessageAttributes: {
          type: { DataType: 'String', StringValue: event.type },
          version: { DataType: 'Number', StringValue: String(event.version) },
        },
      }));
      return Result.ok(undefined);
    } catch (e: unknown) {
      const name = awsErrorName(e);
      return Result.fail(UNAVAILABLE.has(name)
        ? { kind: 'BrokerUnavailable', detail: name }
        : { kind: 'Rejected', eventId: event.eventId, detail: name });
    }
  }
}
```

The `type` message attribute plays the role of the RabbitMQ routing key: SNS subscription filter policies match on it, so a consumer interested only in shipments subscribes with `{ "type": ["OrderShipped"] }`.

### 4. Choosing the adapter
```typescript
export type MessagingConfig =
  | { readonly transport: 'rabbitmq'; readonly channel: ConfirmChannel }
  | { readonly transport: 'sns'; readonly client: SNSClient; readonly topicArn: string };

export function orderEventPublisher(config: MessagingConfig): OrderEventPublisher {
  return config.transport === 'rabbitmq'
    ? new RabbitOrderEventPublisher(config.channel)
    : new SnsOrderEventPublisher(config.client, config.topicArn);
}
```

Use cases receive an `OrderEventPublisher` and never branch on the deployment. If losing an event between "order saved" and "event published" is unacceptable, write events to an outbox table in the same transaction and let a relay call this port; the port stays exactly the same.

In this Angular service the seat selection rules are mixed with HttpClient calls. Apply Clean Architecture so the rules have no Angular dependency:

```typescript
@Injectable({ providedIn: 'root' })
export class SeatService {
  constructor(private http: HttpClient) {}

  async select(flightId: string, seat: string, passenger: { age: number; tier: string }) {
    const map = await firstValueFrom(this.http.get<any>(`/api/flights/${flightId}/seats`));
    const s = map.seats.find((x: any) => x.code === seat);
    if (!s || s.taken) throw new Error('Seat not available');
    if (s.exitRow && passenger.age < 15) throw new Error('Exit row requires age 15+');
    let fee = 0;
    if (s.extraLegroom) fee = passenger.tier === 'gold' ? 0 : 35;
    else if (s.row <= 5) fee = passenger.tier === 'gold' ? 0 : 20;
    await firstValueFrom(this.http.post(`/api/flights/${flightId}/seats/${seat}`, { fee }));
    return fee;
  }
}
```

### Architectural Flaws in Original Code
1. **Business rules in a framework service:** exit-row age limits and seat fees depend on `@Injectable` and `HttpClient`.
2. **`any` everywhere:** the seat map is typed as `any`, so the compiler cannot catch a renamed field.
3. **Errors as thrown strings:** callers cannot tell "seat taken" from "age restriction" without parsing messages.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/seating.ts`)
```typescript
import { Result } from '../shared/Result';

export type LoyaltyTier = 'standard' | 'silver' | 'gold';

export interface Seat {
  readonly code: string;
  readonly row: number;
  readonly taken: boolean;
  readonly exitRow: boolean;
  readonly extraLegroom: boolean;
}

export interface Passenger {
  readonly age: number;
  readonly tier: LoyaltyTier;
}

export type SeatError =
  | { kind: 'SeatUnavailable'; seat: string }
  | { kind: 'ExitRowAgeRestriction'; minimumAge: number };

export const EXIT_ROW_MIN_AGE = 15;

export function seatFee(seat: Seat, passenger: Passenger): Result<number, SeatError> {
  if (seat.taken) return Result.fail({ kind: 'SeatUnavailable', seat: seat.code });
  if (seat.exitRow && passenger.age < EXIT_ROW_MIN_AGE) {
    return Result.fail({ kind: 'ExitRowAgeRestriction', minimumAge: EXIT_ROW_MIN_AGE });
  }
  if (passenger.tier === 'gold') return Result.ok(0);
  if (seat.extraLegroom) return Result.ok(35);
  if (seat.row <= 5) return Result.ok(20);
  return Result.ok(0);
}
```

#### 2. Application Layer (`src/application/SelectSeat.ts`)
```typescript
import { Result } from '../shared/Result';
import { Passenger, Seat, SeatError, seatFee } from '../domain/seating';

export interface SeatMapSource {
  seats(flightId: string): Promise<Seat[]>;
  assign(flightId: string, seatCode: string, fee: number): Promise<void>;
}

export class SelectSeat {
  constructor(private readonly seatMap: SeatMapSource) {}

  async execute(flightId: string, seatCode: string, passenger: Passenger): Promise<Result<number, SeatError>> {
    const seat = (await this.seatMap.seats(flightId)).find((s) => s.code === seatCode);
    if (!seat) return Result.fail({ kind: 'SeatUnavailable', seat: seatCode });

    const fee = seatFee(seat, passenger);
    if (!fee.success) return fee;

    await this.seatMap.assign(flightId, seatCode, fee.data);
    return fee;
  }
}
```

#### 3. Infrastructure Layer (`src/app/infrastructure/HttpSeatMapSource.ts`)
Angular stays here: the class implements the application interface with `HttpClient`.
```typescript
