```typescript
// Domain/Entities/User.ts
export interface User {
  id: string;
  email: string;
  passwordHash: string;
}

// Domain/Errors/DomainError.ts
export abstract class DomainError extends Error {
  constructor(message: string) {
    super(message);
    this.name = this.constructor.name;
  }
}

export class InvalidPasswordError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export class PasswordMismatchError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

// Domain/Ports/IUserRepository.ts
export interface IUserRepository {
  findById(id: string): Promise<User | null>;
  update(user: User): Promise<void>;
}

// Domain/Ports/IPasswordHasher.ts
export interface IPasswordHasher {
  hash(password: string): Promise<string>;
  compare(password: string, hash: string): Promise<boolean>;
}

// Application/UseCases/ChangePasswordUseCase.ts
import { Result, ok, error } from '../Result';
import { User } from '../../Domain/Entities/User';
import { DomainError } from '../../Domain/Errors/DomainError';
import { InvalidPasswordError, PasswordMismatchError } from '../../Domain/Errors/DomainError';

export interface ChangePasswordRequest {
  userId: string;
  currentPassword: string;
  newPassword: string;
}

export class ChangePasswordUseCase {
  constructor(
    private userRepository: IUserRepository,
    private passwordHasher: IPasswordHasher
  ) {}

  async execute(request: ChangePasswordRequest): Promise<Result<void, DomainError>> {
    // Validate input
    if (!request.userId) {
      return error(new InvalidPasswordError('User ID is required'));
    }

    if (!request.currentPassword) {
      return error(new InvalidPasswordError('Current password is required'));
    }

    if (!request.newPassword) {
      return error(new InvalidPasswordError('New password is required'));
    }

    // Check if user exists
    const user = await this.userRepository.findById(request.userId);
    if (!user) {
      return error(new PasswordMismatchError('User not found'));
    }

    // Verify current password
    const isPasswordValid = await this.passwordHasher.compare(
      request.currentPassword,
      user.passwordHash
    );

    if (!isPasswordValid) {
      return error(new PasswordMismatchError('Current password is incorrect'));
    }

    // Business rule: new password cannot equal old password
    const isSamePassword = await this.passwordHasher.compare(
      request.newPassword,
      user.passwordHash
    );

    if (isSamePassword) {
      return error(new InvalidPasswordError('New password cannot be the same as the current password'));
    }

    // Hash new password
    const newPasswordHash = await this.passwordHasher.hash(request.newPassword);

    // Update user with new password hash
    user.passwordHash = newPasswordHash;
    await this.userRepository.update(user);

    return ok(undefined);
  }
}

// Application/Result.ts
export type Result<T, E extends Error> = Success<T> | Failure<E>;

interface Success<T> {
  isSuccess: true;
  value: T;
  error?: never;
}

interface Failure<E extends Error> {
  isSuccess: false;
  value?: never;
  error: E;
}

export function ok<T>(value: T): Result<T, never> {
  return {
    isSuccess: true,
    value
  };
}

export function error<E extends Error>(error: E): Result<never, E> {
  return {
    isSuccess: false,
    error
  };
}
```

This implementation follows Clean Architecture principles with:

1. **Dependency Rule Enforcement**: The use case depends only on ports (interfaces) and not on concrete implementations
2. **Business Rules**: Implements the rule that new password cannot equal old password
3. **Result Pattern**: Returns `Result<void, DomainError>` as required
4. **Typed Errors**: Uses specific domain error types instead of generic errors
5. **Strict Types**: No `any` types used; all interfaces and types are properly defined
6. **SOLID Principles**: Single Responsibility Principle (use case handles only password change logic), Dependency Inversion Principle (depends on abstractions)

The use case validates:
- Required fields
- User existence
- Current password validity
- New password uniqueness (not same as old)
- Password hashing and updating

All domain logic is contained within the application layer without depending on infrastructure concerns.

Write unit tests for the locker pickup use case. AAA comments in each test, and a fake locker controller that remembers which doors it opened instead of a mock.

```typescript
import { Result } from '../shared/Result';

export interface LockerParcel {
  lockerId: string;
  code: string;
  depositedAt: Date;
  failedAttempts: number;
  status: 'waiting' | 'collected' | 'returned';
}

export interface ParcelRepository {
  inLocker(lockerId: string): Promise<LockerParcel | null>;
  save(parcel: LockerParcel): Promise<void>;
}

export interface LockerController {
  open(lockerId: string): Promise<void>;
}

export type PickupError =
  | { kind: 'EmptyLocker' }
  | { kind: 'NotWaiting' }
  | { kind: 'PickupExpired' }
  | { kind: 'Locked' }
  | { kind: 'WrongCode'; attemptsLeft: number };

const MAX_ATTEMPTS = 3;
const HOLD_MS = 72 * 3_600_000;

export class PickUpParcel {
  constructor(
    private readonly parcels: ParcelRepository,
    private readonly lockers: LockerController,
    private readonly now: () => Date,
  ) {}

  async execute(lockerId: string, code: string): Promise<Result<void, PickupError>> {
    const parcel = await this.parcels.inLocker(lockerId);
    if (!parcel) return Result.fail({ kind: 'EmptyLocker' });
    if (parcel.status !== 'waiting') return Result.fail({ kind: 'NotWaiting' });
    if (this.now().getTime() - parcel.depositedAt.getTime() > HOLD_MS) {
      await this.parcels.save({ ...parcel, status: 'returned' });
      return Result.fail({ kind: 'PickupExpired' });
    }
    if (parcel.failedAttempts >= MAX_ATTEMPTS) return Result.fail({ kind: 'Locked' });
    if (code !== parcel.code) {
      const failedAttempts = parcel.failedAttempts + 1;
      await this.parcels.save({ ...parcel, failedAttempts });
      return Result.fail({ kind: 'WrongCode', attemptsLeft: MAX_ATTEMPTS - failedAttempts });
    }
    await this.lockers.open(lockerId);
    await this.parcels.save({ ...parcel, status: 'collected' });
    return Result.ok(undefined);
  }
}
```

Both fakes hold state: the repository stores parcels per locker, and the controller appends every opened locker id to a list. That way "the door did not open" is an assertion on data. A `parcel()` helper sets up a waiting parcel deposited 10 hours before the frozen clock.

```typescript
import { describe, it, expect, beforeEach } from 'vitest';
import { PickUpParcel, LockerController, LockerParcel, ParcelRepository } from './PickUpParcel';

class InMemoryParcels implements ParcelRepository {
  readonly byLocker = new Map<string, LockerParcel>();
  async inLocker(lockerId: string): Promise<LockerParcel | null> {
    return this.byLocker.get(lockerId) ?? null;
  }
  async save(parcel: LockerParcel): Promise<void> {
    this.byLocker.set(parcel.lockerId, parcel);
  }
}

class RecordingLockerController implements LockerController {
  readonly opened: string[] = [];
  async open(lockerId: string): Promise<void> {
    this.opened.push(lockerId);
  }
}

const NOW = new Date('2024-10-10T15:00:00Z');
const hoursAgo = (h: number): Date => new Date(NOW.getTime() - h * 3_600_000);
const parcel = (overrides: Partial<LockerParcel> = {}): LockerParcel => ({
  lockerId: 'L-07', code: '482913', depositedAt: hoursAgo(10), failedAttempts: 0, status: 'waiting', ...overrides,
});

describe('PickUpParcel', () => {
  let parcels: InMemoryParcels;
  let controller: RecordingLockerController;
  let useCase: PickUpParcel;

  beforeEach(() => {
    parcels = new InMemoryParcels();
    controller = new RecordingLockerController();
    useCase = new PickUpParcel(parcels, controller, () => NOW);
  });

  it('opens the door and marks the parcel collected with the right code', async () => {
    // Arrange
    await parcels.save(parcel());

    // Act
    const result = await useCase.execute('L-07', '482913');

    // Assert
    expect(result.success).toBe(true);
    expect(controller.opened).toEqual(['L-07']);
    expect(parcels.byLocker.get('L-07')?.status).toBe('collected');
  });

  it.each([
    { before: 0, attemptsLeft: 2 },
    { before: 2, attemptsLeft: 0 },
  ])('counts a wrong code after $before failures', async ({ before, attemptsLeft }) => {
    // Arrange
    await parcels.save(parcel({ failedAttempts: before }));

    // Act
    const result = await useCase.execute('L-07', '000000');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'WrongCode', attemptsLeft });
    expect(parcels.byLocker.get('L-07')?.failedAttempts).toBe(before + 1);
    expect(controller.opened).toEqual([]);
  });

  it('stays locked after three failures, even with the right code', async () => {
    // Arrange
    await parcels.save(parcel({ failedAttempts: 3 }));

    // Act
    const result = await useCase.execute('L-07', '482913');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('Locked');
    expect(controller.opened).toEqual([]);
  });

  it('marks the parcel for return after 72 hours', async () => {
    // Arrange
    await parcels.save(parcel({ depositedAt: hoursAgo(73) }));

    // Act
    const result = await useCase.execute('L-07', '482913');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('PickupExpired');
    expect(parcels.byLocker.get('L-07')?.status).toBe('returned');
  });

  it('fails with EmptyLocker when nothing is inside', async () => {
    // Arrange: no parcels

    // Act
    const result = await useCase.execute('L-99', '482913');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('EmptyLocker');
  });

  it('fails with NotWaiting for an already collected parcel', async () => {
    // Arrange
    await parcels.save(parcel({ status: 'collected' }));

    // Act
    const result = await useCase.execute('L-07', '482913');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('NotWaiting');
  });
});
