```typescript
// Domain Layer

/**
 * Domain Event interface - represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly eventId: string;
  readonly occurredOn: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  /**
   * Publishes a domain event
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>>;
}

// Application Layer

/**
 * Domain Error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventPublishingError";
  }
}

// Infrastructure Layer - Test Double Implementation

/**
 * In-memory test double implementation of IEventPublisher
 * Used for testing without external dependencies
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private events: IDomainEvent[] = [];
  private isPublishingEnabled = true;

  /**
   * Publishes a domain event to the in-memory store
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    if (!this.isPublishingEnabled) {
      return Result.failure(new EventPublishingError("Event publishing is disabled"));
    }

    try {
      this.events.push(event);
      return Result.success(undefined);
    } catch (error) {
      return Result.failure(
        new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`)
      );
    }
  }

  /**
   * Gets all published events
   * @returns Array of published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clears all published events
   */
  clearEvents(): void {
    this.events = [];
  }

  /**
   * Enables or disables publishing
   * @param enabled - Whether publishing should be enabled
   */
  setPublishingEnabled(enabled: boolean): void {
    this.isPublishingEnabled = enabled;
  }
}

// Result type implementation (used in the pattern)
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
