Write unit tests for the annual tier review. Use AAA, fake every collaborator, and show which spend amounts keep or lose each tier.

```typescript
import { Result } from '../shared/Result';

export type Tier = 'Bronze' | 'Silver' | 'Gold';

export interface Member {
  id: string;
  tier: Tier;
  tierSince: Date;
}

export interface MemberRepository {
  find(id: string): Promise<Member | null>;
  save(member: Member): Promise<void>;
}

export interface SpendHistory {
  totalCents(memberId: string, from: Date, to: Date): Promise<number>;
}

export interface TierNotifier {
  downgraded(memberId: string, from: Tier, to: Tier): Promise<void>;
}

export type ReviewError = { kind: 'MemberNotFound' } | { kind: 'ReviewTooEarly'; daysInTier: number };

const REQUIRED_CENTS: Record<Tier, number> = { Bronze: 0, Silver: 50_000, Gold: 200_000 };
const LOWER: Record<Tier, Tier> = { Gold: 'Silver', Silver: 'Bronze', Bronze: 'Bronze' };
const DAY_MS = 86_400_000;

export class ReviewLoyaltyTier {
  constructor(
    private readonly members: MemberRepository,
    private readonly spend: SpendHistory,
    private readonly notifier: TierNotifier,
    private readonly now: () => Date,
  ) {}

  async execute(memberId: string): Promise<Result<Tier, ReviewError>> {
    const member = await this.members.find(memberId);
    if (!member) return Result.fail({ kind: 'MemberNotFound' });
    const now = this.now();
    const daysInTier = Math.floor((now.getTime() - member.tierSince.getTime()) / DAY_MS);
    if (daysInTier < 365) return Result.fail({ kind: 'ReviewTooEarly', daysInTier });
    const spent = await this.spend.totalCents(memberId, new Date(now.getTime() - 365 * DAY_MS), now);
    if (spent >= REQUIRED_CENTS[member.tier]) return Result.ok(member.tier);
    const lower = LOWER[member.tier];
    await this.members.save({ ...member, tier: lower, tierSince: now });
    await this.notifier.downgraded(memberId, member.tier, lower);
    return Result.ok(lower);
  }
}
```

The spend history fake returns a configured total and records the window it was asked for, which lets one test verify the 365-day range. The notifier is a spy. A table of tier/spend pairs covers keeping and losing a tier, and shows that a downgrade drops only one level.

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { ReviewLoyaltyTier, Member, MemberRepository, SpendHistory, Tier, TierNotifier } from './ReviewLoyaltyTier';

class InMemoryMembers implements MemberRepository {
  readonly members = new Map<string, Member>();
  async find(id: string): Promise<Member | null> {
    return this.members.get(id) ?? null;
  }
  async save(member: Member): Promise<void> {
    this.members.set(member.id, member);
  }
}

class FixedSpend implements SpendHistory {
  lastWindow: { from: Date; to: Date } | null = null;
  constructor(public cents = 0) {}
  async totalCents(_memberId: string, from: Date, to: Date): Promise<number> {
    this.lastWindow = { from, to };
    return this.cents;
  }
}

const NOW = new Date('2025-01-15T00:00:00Z');
const daysAgo = (d: number): Date => new Date(NOW.getTime() - d * 86_400_000);

describe('ReviewLoyaltyTier', () => {
  let members: InMemoryMembers;
  let spend: FixedSpend;
  let downgraded: ReturnType<typeof vi.fn<TierNotifier['downgraded']>>;
  let useCase: ReviewLoyaltyTier;

  beforeEach(() => {
    members = new InMemoryMembers();
    spend = new FixedSpend();
    downgraded = vi.fn<TierNotifier['downgraded']>().mockResolvedValue(undefined);
    useCase = new ReviewLoyaltyTier(members, spend, { downgraded }, () => NOW);
  });

  it.each<{ tier: Tier; cents: number; expected: Tier }>([
    { tier: 'Gold', cents: 200_000, expected: 'Gold' },
    { tier: 'Gold', cents: 199_999, expected: 'Silver' },
    { tier: 'Gold', cents: 0, expected: 'Silver' },
    { tier: 'Silver', cents: 50_000, expected: 'Silver' },
    { tier: 'Silver', cents: 49_999, expected: 'Bronze' },
    { tier: 'Bronze', cents: 0, expected: 'Bronze' },
  ])('$tier member who spent $cents keeps/moves to $expected', async ({ tier, cents, expected }) => {
    // Arrange
    members.members.set('m1', { id: 'm1', tier, tierSince: daysAgo(400) });
    spend.cents = cents;

    // Act
    const result = await useCase.execute('m1');

    // Assert
    expect(result).toEqual({ success: true, data: expected });
    expect(members.members.get('m1')?.tier).toBe(expected);
  });

  it('notifies and restarts the tier clock on a downgrade', async () => {
    // Arrange
    members.members.set('m1', { id: 'm1', tier: 'Gold', tierSince: daysAgo(365) });
    spend.cents = 10_000;

    // Act
    await useCase.execute('m1');

    // Assert
    expect(downgraded).toHaveBeenCalledWith('m1', 'Gold', 'Silver');
    expect(members.members.get('m1')?.tierSince).toEqual(NOW);
    expect(spend.lastWindow).toEqual({ from: daysAgo(365), to: NOW });
  });

  it('fails with MemberNotFound', async () => {
    // Arrange: no members

    // Act
    const result = await useCase.execute('ghost');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('MemberNotFound');
  });

  it('refuses to review a member who reached the tier less than a year ago', async () => {
    // Arrange
    members.members.set('m1', { id: 'm1', tier: 'Gold', tierSince: daysAgo(364) });

    // Act
    const result = await useCase.execute('m1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error).toEqual({ kind: 'ReviewTooEarly', daysInTier: 364 });
    expect(downgraded).not.toHaveBeenCalled();
  });
});
```

Refactor this Express route so the lending rules no longer depend on Express or PostgreSQL:

```typescript
app.post('/api/loans', async (req, res) => {
  const { memberId, bookId } = req.body;
  const member = await pool.query('SELECT * FROM members WHERE id = $1', [memberId]);
  if (member.rows.length === 0) return res.status(404).json({ error: 'Member not found' });
  if (member.rows[0].unpaid_fees > 10) {
    return res.status(403).json({ error: 'Outstanding fees' });
  }
  const active = await pool.query(
    'SELECT COUNT(*) FROM loans WHERE member_id = $1 AND returned_at IS NULL', [memberId]);
  if (Number(active.rows[0].count) >= 5) {
    return res.status(409).json({ error: 'Loan limit reached' });
  }
  const due = new Date(Date.now() + 21 * 24 * 60 * 60 * 1000);
  await pool.query('INSERT INTO loans (member_id, book_id, due_at) VALUES ($1, $2, $3)',
    [memberId, bookId, due]);
  res.status(201).json({ dueAt: due });
});
```

### Architectural Flaws in Original Code
1. **Business rules inside the HTTP handler:** the fee ceiling (10), the loan limit (5) and the 21-day period are hidden in a route callback.
2. **SQL in the controller:** the rules cannot run or be tested without PostgreSQL.
3. **Clock coupling:** `Date.now()` is called directly, so the due date is not deterministic in tests.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/Member.ts`)
```typescript
import { Result } from '../shared/Result';

export type LoanError =
  | { kind: 'MemberNotFound' }
  | { kind: 'OutstandingFees'; amount: number }
  | { kind: 'LoanLimitReached'; limit: number };

export class Member {
  static readonly MAX_FEES = 10;
  static readonly MAX_ACTIVE_LOANS = 5;
  static readonly LOAN_DAYS = 21;

  constructor(
    readonly id: string,
    readonly unpaidFees: number,
    readonly activeLoans: number,
  ) {}

  borrow(bookId: string, now: Date): Result<Loan, LoanError> {
    if (this.unpaidFees > Member.MAX_FEES) {
      return Result.fail({ kind: 'OutstandingFees', amount: this.unpaidFees });
    }
    if (this.activeLoans >= Member.MAX_ACTIVE_LOANS) {
      return Result.fail({ kind: 'LoanLimitReached', limit: Member.MAX_ACTIVE_LOANS });
    }
    const dueAt = new Date(now.getTime() + Member.LOAN_DAYS * 24 * 60 * 60 * 1000);
    return Result.ok({ memberId: this.id, bookId, dueAt });
  }
}

export interface Loan {
  readonly memberId: string;
  readonly bookId: string;
  readonly dueAt: Date;
}
```

#### 2. Application Layer (`src/application/BorrowBook.ts`)
```typescript
import { Result } from '../shared/Result';
import { Loan, LoanError, Member } from '../domain/Member';

export interface MemberRepository {
  findById(id: string): Promise<Member | null>;
}

export interface LoanRepository {
  save(loan: Loan): Promise<void>;
}

export interface Clock {
  now(): Date;
}

export class BorrowBook {
  constructor(
    private readonly members: MemberRepository,
    private readonly loans: LoanRepository,
    private readonly clock: Clock,
  ) {}

  async execute(input: { memberId: string; bookId: string }): Promise<Result<Loan, LoanError>> {
    const member = await this.members.findById(input.memberId);
    if (!member) return Result.fail({ kind: 'MemberNotFound' });

    const loan = member.borrow(input.bookId, this.clock.now());
    if (!loan.success) return loan;

    await this.loans.save(loan.data);
    return loan;
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/PostgresLibrary.ts`)
```typescript
import { Pool } from 'pg';
import { Loan, Member } from '../domain/Member';
import { LoanRepository, MemberRepository } from '../application/BorrowBook';

export class PostgresMemberRepository implements MemberRepository {
  constructor(private readonly pool: Pool) {}

  async findById(id: string): Promise<Member | null> {
    const member = await this.pool.query('SELECT unpaid_fees FROM members WHERE id = $1', [id]);
    if (member.rows.length === 0) return null;
    const active = await this.pool.query(
      'SELECT COUNT(*) FROM loans WHERE member_id = $1 AND returned_at IS NULL', [id]);
    return new Member(id, Number(member.rows[0].unpaid_fees), Number(active.rows[0].count));
  }
}

export class PostgresLoanRepository implements LoanRepository {
  constructor(private readonly pool: Pool) {}

  async save(loan: Loan): Promise<void> {
    await this.pool.query('INSERT INTO loans (member_id, book_id, due_at) VALUES ($1, $2, $3)',
      [loan.memberId, loan.bookId, loan.dueAt]);
  }
}
```

