### Architectural Flaws in Original Code
1. **Violation of Dependency Rule:** Business rules (calculating total, validating empty items) and side effects (sending email) are coupled to Express HTTP handlers.
2. **Direct DB Coupling:** Raw SQL query is executed directly inside the controller.
3. **Testability:** Impossible to test order creation business logic without spinning up Express and PostgreSQL.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/entities/Order.ts`)
```typescript
export interface OrderItem {
  readonly productId: string;
  readonly price: number;
  readonly quantity: number;
}

export class Order {
  private constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly items: readonly OrderItem[],
    public readonly total: number,
    public readonly status: 'PENDING' | 'PAID' | 'CANCELLED'
  ) {}

  public static create(customerId: string, items: OrderItem[]): Order {
    if (!items || items.length === 0) {
      throw new Error('Order must contain at least one item');
    }
    const total = items.reduce((sum, item) => sum + item.price * item.quantity, 0);
    const id = crypto.randomUUID();
    return new Order(id, customerId, [...items], total, 'PENDING');
  }
}
```

#### 2. Application Layer — Port Contracts (`src/application/ports/`)
```typescript
import { Order } from '../../domain/entities/Order';

export interface IOrderRepository {
  save(order: Order): Promise<void>;
}

export interface INotificationPort {
  sendOrderCreated(customerId: string, orderId: string): Promise<void>;
}
```

#### 3. Application Layer — Use Case (`src/application/use-cases/CreateOrderUseCase.ts`)
```typescript
import { Order, OrderItem } from '../../domain/entities/Order';
import { IOrderRepository, INotificationPort } from '../ports';

export interface CreateOrderDTO {
  customerId: string;
  items: OrderItem[];
}

export type CreateOrderResult =
  | { success: true; orderId: string; total: number }
  | { success: false; error: string };

export class CreateOrderUseCase {
  constructor(
    private readonly orderRepo: IOrderRepository,
    private readonly notifier: INotificationPort
  ) {}

  async execute(dto: CreateOrderDTO): Promise<CreateOrderResult> {
    try {
      const order = Order.create(dto.customerId, dto.items);
      await this.orderRepo.save(order);
      await this.notifier.sendOrderCreated(order.customerId, order.id);
      return { success: true, orderId: order.id, total: order.total };
    } catch (error) {
      return { success: false, error: (error as Error).message };
    }
  }
}
```

#### 4. Infrastructure / Interface Adapter (`src/infrastructure/http/controllers/CreateOrderController.ts`)
```typescript
import { Request, Response } from 'express';
import { CreateOrderUseCase } from '../../application/use-cases/CreateOrderUseCase';

export class CreateOrderController {
  constructor(private readonly useCase: CreateOrderUseCase) {}

  async handle(req: Request, res: Response): Promise<Response> {
    const { customerId, items } = req.body;
    const result = await this.useCase.execute({ customerId, items });

    if (!result.success) {
      return res.status(400).json({ error: result.error });
    }
    return res.status(201).json({ orderId: result.orderId, total: result.total });
  }
}
```

A failed check here is a normal business answer, not an error, so the use case returns `Result.ok` with either "eligible" or "deferred + reasons". `Result.fail` is reserved for the donor not existing.

### Domain (`src/domain/eligibility.ts`)
```typescript
export type DonationType = 'WHOLE_BLOOD' | 'PLASMA';
export type Sex = 'F' | 'M';

export interface Donor {
  readonly id: string;
  readonly birthDate: Date;
  readonly sex: Sex;
  readonly lastDonation: { readonly type: DonationType; readonly on: Date } | null;
}

export interface Measurements {
  readonly weightKg: number;
  readonly hemoglobinGdl: number;
}

export type DeferralReason = 'AGE' | 'WEIGHT' | 'HEMOGLOBIN' | 'DONATION_GAP';

export type Eligibility =
  | { status: 'ELIGIBLE' }
  | { status: 'DEFERRED'; reasons: readonly DeferralReason[]; eligibleFrom: Date | null };

const MIN_HEMOGLOBIN: Record<Sex, number> = { F: 12.5, M: 13.0 };
const DAY_MS = 86_400_000;

export function ageOn(birthDate: Date, date: Date): number {
  const age = date.getFullYear() - birthDate.getFullYear();
  const birthdayPassed =
    date.getMonth() > birthDate.getMonth() ||
    (date.getMonth() === birthDate.getMonth() && date.getDate() >= birthDate.getDate());
  return birthdayPassed ? age : age - 1;
}

export function requiredGapDays(previous: DonationType, requested: DonationType): number {
  if (previous === 'WHOLE_BLOOD' && requested === 'WHOLE_BLOOD') return 56;
  if (previous === 'PLASMA' && requested === 'PLASMA') return 14;
  return 28;
}

export function assessEligibility(donor: Donor, m: Measurements, requested: DonationType, today: Date): Eligibility {
  const reasons: DeferralReason[] = [];
  const age = ageOn(donor.birthDate, today);
  const maxAge = donor.lastDonation === null ? 60 : 65;
  if (age < 18 || age > maxAge) reasons.push('AGE');
  if (m.weightKg < 50) reasons.push('WEIGHT');
  if (m.hemoglobinGdl < MIN_HEMOGLOBIN[donor.sex]) reasons.push('HEMOGLOBIN');

  let eligibleFrom: Date | null = null;
  if (donor.lastDonation) {
    const gap = requiredGapDays(donor.lastDonation.type, requested);
    const nextDate = new Date(donor.lastDonation.on.getTime() + gap * DAY_MS);
    if (today < nextDate) {
      reasons.push('DONATION_GAP');
      eligibleFrom = nextDate;
    }
  }

  if (reasons.length === 0) return { status: 'ELIGIBLE' };
  return { status: 'DEFERRED', reasons, eligibleFrom: reasons.length === 1 ? eligibleFrom : null };
}
```

### Use case (`src/application/CheckDonorEligibility.ts`)
```typescript
import { Result } from '../shared/Result';
import { DonationType, Donor, Eligibility, Measurements, assessEligibility } from '../domain/eligibility';

export interface DonorRepository {
  findById(id: string): Promise<Donor | null>;
}

export type EligibilityError = { kind: 'DonorNotFound'; donorId: string };

export class CheckDonorEligibility {
  constructor(private readonly donors: DonorRepository, private readonly today: () => Date) {}

  async execute(donorId: string, m: Measurements, requested: DonationType): Promise<Result<Eligibility, EligibilityError>> {
    const donor = await this.donors.findById(donorId);
    if (!donor) return Result.fail({ kind: 'DonorNotFound', donorId });
    return Result.ok(assessEligibility(donor, m, requested, this.today()));
  }
}
```

`eligibleFrom` is only set when the gap is the single reason, because a date would mislead the nurse if the donor is also underweight. A 61-year-old who has donated before can still donate; the same person on their first visit is deferred for `AGE`. The check is read-only, so the use case needs nothing besides the repository and the injected date.

```typescript
// Domain Layer

/**
 * Domain Event interface - represents an event that occurred in the domain
 */
export interface IDomainEvent {
  readonly eventId: string;
  readonly occurredAt: Date;
  readonly eventType: string;
}

/**
 * Domain Port - Event Publisher interface
 * Defines the contract for publishing domain events
 */
export interface IEventPublisher {
  /**
   * Publishes a domain event
   * @param event - The domain event to publish
   * @returns Result indicating success or failure
   */
  publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>>;
}

// Application Layer

/**
 * Domain Error for event publishing failures
 */
export class EventPublishingError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "EventPublishingError";
  }
}

// Infrastructure Layer - Test Double Implementation

/**
 * In-Memory Event Publisher - Test Double implementation
 * Used for testing without external dependencies
 */
export class InMemoryEventPublisher implements IEventPublisher {
  private events: IDomainEvent[] = [];
  private subscribers: Array<(event: IDomainEvent) => void> = [];

  /**
   * Publishes a domain event to in-memory storage
   * @param event - The domain event to publish
   * @returns Success result
   */
  async publish(event: IDomainEvent): Promise<Result<void, EventPublishingError>> {
    try {
      this.events.push(event);
      this.subscribers.forEach(subscriber => subscriber(event));
      return Result.success<void>(undefined);
    } catch (error) {
      return Result.failure<EventPublishingError>(
        new EventPublishingError(`Failed to publish event: ${error instanceof Error ? error.message : 'Unknown error'}`)
      );
    }
  }

  /**
   * Gets all published events
   * @returns Array of published events
   */
  getPublishedEvents(): IDomainEvent[] {
    return [...this.events];
  }

  /**
   * Clears all published events
   */
  clearEvents(): void {
    this.events = [];
  }

  /**
   * Subscribe to events
   * @param subscriber - Function to be called when an event is published
   */
  subscribe(subscriber: (event: IDomainEvent) => void): void {
    this.subscribers.push(subscriber);
  }

  /**
   * Unsubscribe from events
   * @param subscriber - Function to remove from subscribers
   */
  unsubscribe(subscriber: (event: IDomainEvent) => void): void {
    const index = this.subscribers.indexOf(subscriber);
    if (index > -1) {
      this.subscribers.splice(index, 1);
    }
  }
}

// Result type implementation (used in the pattern)
export class Result<T, E extends Error> {
  private constructor(
    public readonly isSuccess: boolean,
    public readonly value?: T,
    public readonly error?: E
  ) {}

  static success<T>(value: T): Result<T, never> {
    return new Result<T, never>(true, value);
  }

  static failure<E extends Error>(error: E): Result<never, E> {
    return new Result<never, E>(false, undefined, error);
  }
}
```

Three concerns, three places: shape validation of the untrusted body, the submission rules (pure domain) and the use case that fetches the speaker's history and the CFP window.

### Domain rules (`src/domain/submission.ts`)
```typescript
import { Result } from '../shared/Result';

export type TalkFormat = 'TALK_20' | 'TALK_40' | 'WORKSHOP_120';
export const FORMATS: readonly TalkFormat[] = ['TALK_20', 'TALK_40', 'WORKSHOP_120'];
export const MAX_SUBMISSIONS = 3;
export const MAX_CO_SPEAKERS = 2;

export interface Proposal {
  readonly title: string;
  readonly abstract: string;
  readonly format: TalkFormat;
  readonly coSpeakerIds: readonly string[];
}

export interface SpeakerContext {
  readonly speakerId: string;
  readonly existingTitles: readonly string[];
  readonly spokeBefore: boolean;
}

export type SubmissionError =
  | { kind: 'InvalidRequest'; field: string }
  | { kind: 'ConferenceNotFound' }
  | { kind: 'CfpClosed' }
  | { kind: 'TitleLength' }
  | { kind: 'AbstractLength' }
  | { kind: 'WorkshopNeedsExperience' }
  | { kind: 'InvalidCoSpeakers' }
  | { kind: 'SubmissionLimit' }
  | { kind: 'DuplicateTitle' };

export function checkProposal(p: Proposal, ctx: SpeakerContext): Result<Proposal, SubmissionError> {
  const title = p.title.trim();
  if (title.length < 10 || title.length > 90) return Result.fail({ kind: 'TitleLength' });
  if (p.abstract.length < 100 || p.abstract.length > 1500) return Result.fail({ kind: 'AbstractLength' });
  if (p.format === 'WORKSHOP_120' && !ctx.spokeBefore) return Result.fail({ kind: 'WorkshopNeedsExperience' });

  const unique = new Set(p.coSpeakerIds);
  if (p.coSpeakerIds.length > MAX_CO_SPEAKERS || unique.size !== p.coSpeakerIds.length || unique.has(ctx.speakerId)) {
    return Result.fail({ kind: 'InvalidCoSpeakers' });
  }
  if (ctx.existingTitles.length >= MAX_SUBMISSIONS) return Result.fail({ kind: 'SubmissionLimit' });
  if (ctx.existingTitles.some((t) => t.trim().toLowerCase() === title.toLowerCase())) {
    return Result.fail({ kind: 'DuplicateTitle' });
  }
  return Result.ok({ ...p, title });
}
```

### Use case (`src/application/SubmitTalk.ts`)
```typescript
import { Result } from '../shared/Result';
import { Proposal, SubmissionError, checkProposal } from '../domain/submission';

export interface CfpWindow { readonly opensAt: Date; readonly closesAt: Date; }

export interface ConferenceRepository { cfpWindow(conferenceId: string): Promise<CfpWindow | null>; }

export interface SubmissionRepository {
  titlesBy(speakerId: string, conferenceId: string): Promise<readonly string[]>;
  add(id: string, conferenceId: string, speakerId: string, proposal: Proposal): Promise<void>;
}

export interface SpeakerHistory { spokeAtPreviousEdition(speakerId: string, conferenceId: string): Promise<boolean>; }

export class SubmitTalk {
  constructor(
    private readonly conferences: ConferenceRepository,
    private readonly submissions: SubmissionRepository,
    private readonly history: SpeakerHistory,
    private readonly now: () => Date,
    private readonly newId: () => string,
  ) {}

  async execute(conferenceId: string, speakerId: string, body: unknown): Promise<Result<string, SubmissionError>> {
    const parsed = parseProposal(body);
    if (!parsed.success) return parsed;

    const window = await this.conferences.cfpWindow(conferenceId);
    if (!window) return Result.fail({ kind: 'ConferenceNotFound' });
    const now = this.now();
    if (now < window.opensAt || now >= window.closesAt) return Result.fail({ kind: 'CfpClosed' });

    const checked = checkProposal(parsed.data, {
      speakerId,
      existingTitles: await this.submissions.titlesBy(speakerId, conferenceId),
      spokeBefore: await this.history.spokeAtPreviousEdition(speakerId, conferenceId),
    });
    if (!checked.success) return checked;

    const id = this.newId();
    await this.submissions.add(id, conferenceId, speakerId, checked.data);
    return Result.ok(id);
  }
}
```

### Parsing the request body (`src/application/parseProposal.ts`)
```typescript
import { Result } from '../shared/Result';
import { FORMATS, Proposal, SubmissionError, TalkFormat } from '../domain/submission';

const isRecord = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null;
const isFormat = (v: unknown): v is TalkFormat => FORMATS.some((f) => f === v);
const isStringArray = (v: unknown): v is string[] => Array.isArray(v) && v.every((s) => typeof s === 'string');

export function parseProposal(body: unknown): Result<Proposal, SubmissionError> {
  if (!isRecord(body)) return Result.fail({ kind: 'InvalidRequest', field: 'body' });
  const { title, abstract, format, coSpeakerIds = [] } = body;
  if (typeof title !== 'string') return Result.fail({ kind: 'InvalidRequest', field: 'title' });
  if (typeof abstract !== 'string') return Result.fail({ kind: 'InvalidRequest', field: 'abstract' });
  if (!isFormat(format)) return Result.fail({ kind: 'InvalidRequest', field: 'format' });
  if (!isStringArray(coSpeakerIds)) return Result.fail({ kind: 'InvalidRequest', field: 'coSpeakerIds' });
  return Result.ok({ title, abstract, format, coSpeakerIds });
}
```
The parser only checks shapes; length limits stay in the domain so they also apply to submissions imported from elsewhere. The use case takes `unknown` so the web layer can pass the body through without casting.

Refactor this Express middleware. The plan quota rules depend directly on Redis and on the request object:

```typescript
export async function quota(req: Request, res: Response, next: NextFunction) {
  const tenant = req.header('x-tenant-id');
  if (!tenant) return res.status(401).json({ error: 'Missing tenant' });
  const plan = (await redis.hget(`tenant:${tenant}`, 'plan')) ?? 'free';
  const limits: Record<string, number> = { free: 1000, pro: 50000, enterprise: Infinity };
  const day = new Date().toISOString().slice(0, 10);
  const key = `usage:${tenant}:${day}`;
  const used = await redis.incr(key);
  if (used === 1) await redis.expire(key, 86400);
  const limit = limits[plan] ?? 1000;
  res.setHeader('X-RateLimit-Remaining', String(Math.max(0, limit - used)));
  if (used > limit) return res.status(429).json({ error: 'Daily quota exceeded', plan });
  next();
}
```

### Architectural Flaws in Original Code
1. **Plan policy inside middleware:** the daily limits per plan cannot be changed or tested without Express and Redis.
2. **Storage keys mixed with rules:** counter naming and TTL handling sit next to the quota decision.
3. **Plans are untyped strings:** the limits table is a `Record<string, number>`, so a misspelled plan name compiles.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/quota.ts`)
```typescript
export type Plan = 'free' | 'pro' | 'enterprise';

const DAILY_LIMITS: { readonly [P in Plan]: number } = {
  free: 1000,
  pro: 50_000,
  enterprise: Infinity,
};

/** Missing or unknown plans are treated as free, as before. */
export function toPlan(value: string | null): Plan {
  return value === 'pro' || value === 'enterprise' ? value : 'free';
}

export interface QuotaDecision {
  readonly allowed: boolean;
  readonly remaining: number;
  readonly plan: Plan;
}

export function decide(plan: Plan, usedToday: number): QuotaDecision {
  const limit = DAILY_LIMITS[plan];
  return { allowed: usedToday <= limit, remaining: Math.max(0, limit - usedToday), plan };
}
```

#### 2. Application Layer (`src/application/ConsumeQuota.ts`)
```typescript
import { Result } from '../shared/Result';
import { Plan, QuotaDecision, decide } from '../domain/quota';

export type QuotaError = { kind: 'MissingTenant' };

export interface TenantPlans {
  planOf(tenantId: string): Promise<Plan>;
}

export interface UsageCounter {
  /** Increments and returns today's request count for the tenant. */
  increment(tenantId: string, day: string): Promise<number>;
}

export class ConsumeQuota {
  constructor(
    private readonly plans: TenantPlans,
    private readonly usage: UsageCounter,
    private readonly today: () => string,
  ) {}

  async execute(tenantId: string | undefined): Promise<Result<QuotaDecision, QuotaError>> {
    if (!tenantId) return Result.fail({ kind: 'MissingTenant' });
    const plan = await this.plans.planOf(tenantId);
    const used = await this.usage.increment(tenantId, this.today());
    return Result.ok(decide(plan, used));
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/redisQuota.ts`)
```typescript
import type { Redis } from 'ioredis';
import { Plan, toPlan } from '../domain/quota';
import { TenantPlans, UsageCounter } from '../application/ConsumeQuota';

export class RedisTenantPlans implements TenantPlans {
  constructor(private readonly redis: Redis) {}

  async planOf(tenantId: string): Promise<Plan> {
    return toPlan(await this.redis.hget(`tenant:${tenantId}`, 'plan'));
  }
}

export class RedisUsageCounter implements UsageCounter {
  constructor(private readonly redis: Redis) {}

  async increment(tenantId: string, day: string): Promise<number> {
    const key = `usage:${tenantId}:${day}`;
    const used = await this.redis.incr(key);
    if (used === 1) await this.redis.expire(key, 86_400);
    return used;
  }
}
```

#### 4. Presentation Layer (`src/http/quotaMiddleware.ts`)
```typescript
import { NextFunction, Request, Response } from 'express';
import { ConsumeQuota } from '../application/ConsumeQuota';

export function quotaMiddleware(consumeQuota: ConsumeQuota) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const result = await consumeQuota.execute(req.header('x-tenant-id'));
    if (!result.success) return res.status(401).json({ error: 'Missing tenant' });

    const { allowed, remaining, plan } = result.data;
    res.setHeader('X-RateLimit-Remaining', String(remaining));
    if (!allowed) return res.status(429).json({ error: 'Daily quota exceeded', plan });
    next();
  };
}
```
Wiring: `app.use(quotaMiddleware(new ConsumeQuota(plans, usage, () => new Date().toISOString().slice(0, 10))))`.

```typescript
// Domain/Entities/Subscription.ts
export interface Subscription {
  readonly id: string;
  readonly userId: string;
  readonly status: 'active' | 'cancelled' | 'expired';
  readonly startDate: Date;
  readonly endDate: Date;
  readonly plan: string;
}

export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly userId: string,
    public readonly status: 'active' | 'cancelled' | 'expired',
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly plan: string
  ) {}

  static create(
    id: string,
    userId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      userId,
      'active',
      startDate,
      endDate,
      plan
    );
  }

  isActive(): boolean {
    return this.status === 'active';
  }

  isExpired(): boolean {
    return this.status === 'expired';
  }

  isCancelled(): boolean {
    return this.status === 'cancelled';
  }

  cancel(): Subscription {
    if (this.isExpired()) {
      throw new SubscriptionAlreadyExpiredError();
    }

    return new Subscription(
      this.id,
      this.userId,
      'cancelled',
      this.startDate,
      this.endDate,
      this.plan
    );
  }
}

// Domain/Errors/SubscriptionErrors.ts
export class SubscriptionAlreadyExpiredError extends Error {
  constructor() {
    super('Cannot cancel an already expired subscription');
    this.name = 'SubscriptionAlreadyExpiredError';
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor() {
    super('Subscription not found');
    this.name = 'SubscriptionNotFoundError';
  }
}

// Domain/Result.ts
export type Result<T, E> = Success<T> | Failure<E>;

interface Success<T> {
  readonly isSuccess: true;
  readonly value: T;
  readonly error?: never;
}

interface Failure<E> {
  readonly isSuccess: false;
  readonly value?: never;
  readonly error: E;
}

export function success<T>(value: T): Success<T> {
  return { isSuccess: true, value };
}

export function failure<E>(error: E): Failure<E> {
  return { isSuccess: false, error };
}

// Application/UseCases/CancelSubscriptionUseCase.ts
import { Result, success, failure } from '../Domain/Result';
import { Subscription } from '../Domain/Entities/Subscription';
import { SubscriptionAlreadyExpiredError } from '../Domain/Errors/SubscriptionErrors';

export interface CancelSubscriptionUseCase {
  execute(subscriptionId: string): Promise<Result<Subscription, CancelSubscriptionError>>;
}

export type CancelSubscriptionError = 
  | SubscriptionNotFoundError 
  | SubscriptionAlreadyExpiredError;

export class CancelSubscriptionUseCaseImpl implements CancelSubscriptionUseCase {
  constructor(
    private readonly subscriptionRepository: SubscriptionRepository
  ) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, CancelSubscriptionError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return failure(new SubscriptionNotFoundError());
      }

      const cancelledSubscription = subscription.cancel();

      await this.subscriptionRepository.save(cancelledSubscription);

      return success(cancelledSubscription);
    } catch (error) {
      if (error instanceof SubscriptionAlreadyExpiredError) {
        return failure(error);
      }
      throw error;
    }
  }
}

// Domain/Repositories/SubscriptionRepository.ts
export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: The `Subscription` class contains only domain logic and has no dependencies on external frameworks or infrastructure
2. **Invariant Validation**: The `cancel()` method explicitly checks if the subscription is already expired and throws a typed error
3. **Result Pattern**: Uses a strict `Result<T, E>` type with `success()` and `failure()` factory functions
4. **Typed Errors**: Domain-specific error types that extend `Error` with descriptive names
5. **Dependency Rule Compliance**: The domain layer (Entities, Errors, Result) has no dependencies on external libraries or frameworks
6. **No `any` Type**: All types are explicitly defined with interfaces and types
7. **Type Safety**: Strict typing throughout with proper interfaces and type guards

The `CancelSubscriptionUseCase` validates that:
- The subscription exists
- The subscription is not already expired (invariant rule)
- Returns appropriate Result types with proper error handling

This small helper calculates VAT but it reads the rates from the environment and calls a remote service to validate tax numbers. How should it be layered?

```typescript
export async function invoiceTax(net: number, country: string, buyerVatId?: string) {
  const rates = JSON.parse(process.env.VAT_RATES ?? '{}');
  if (buyerVatId) {
    const r = await fetch(`https://vat-check.example/api/${buyerVatId}`);
    if ((await r.json()).valid && country !== 'DE') return { rate: 0, tax: 0, reverseCharge: true };
  }
  const rate = rates[country] ?? 0.19;
  return { rate, tax: Math.round(net * rate * 100) / 100, reverseCharge: false };
}
```

### Architectural Flaws
1. **The tax rule depends on configuration and HTTP:** reverse charge and rounding cannot be tested without `process.env` and a network call.
2. **Unvalidated inputs:** the rates JSON and the remote response are trusted as-is.

The rule itself is small, so a pure function plus two narrow interfaces is enough.

### Domain (`src/domain/vat.ts`)
```typescript
export interface VatLine {
  readonly rate: number;
  readonly tax: number;
  readonly reverseCharge: boolean;
}

export const SELLER_COUNTRY = 'DE';
export const DEFAULT_RATE = 0.19;

export function vatFor(net: number, rate: number, buyerCountry: string, buyerHasValidVatId: boolean): VatLine {
  if (buyerHasValidVatId && buyerCountry !== SELLER_COUNTRY) {
    return { rate: 0, tax: 0, reverseCharge: true };
  }
  return { rate, tax: Math.round(net * rate * 100) / 100, reverseCharge: false };
}
```

### Application (`src/application/CalculateInvoiceTax.ts`)
```typescript
import { DEFAULT_RATE, VatLine, vatFor } from '../domain/vat';

export interface VatRates { rateFor(country: string): number | undefined; }
export interface VatIdRegistry { isValid(vatId: string): Promise<boolean>; }

export class CalculateInvoiceTax {
  constructor(private readonly rates: VatRates, private readonly registry: VatIdRegistry) {}

  async execute(net: number, country: string, buyerVatId?: string): Promise<VatLine> {
    const valid = buyerVatId ? await this.registry.isValid(buyerVatId) : false;
    return vatFor(net, this.rates.rateFor(country) ?? DEFAULT_RATE, country, valid);
  }
}
```

### Infrastructure (`src/infrastructure/vat.ts`)
```typescript
export class EnvVatRates implements VatRates {
  private readonly rates: Record<string, number>;
  constructor(json: string | undefined) {
    this.rates = JSON.parse(json ?? '{}') as Record<string, number>;
  }
  rateFor(country: string): number | undefined { return this.rates[country]; }
}

export class HttpVatIdRegistry implements VatIdRegistry {
  async isValid(vatId: string): Promise<boolean> {
    const res = await fetch(`https://vat-check.example/api/${encodeURIComponent(vatId)}`);
    const body: unknown = await res.json();
    return typeof body === 'object' && body !== null && (body as { valid?: unknown }).valid === true;
  }
}
```
Wire it once: `new CalculateInvoiceTax(new EnvVatRates(process.env.VAT_RATES), new HttpVatIdRegistry())`. `vatFor(100, 0.19, 'FR', true)` now returns the reverse-charge line without any I/O.

This NestJS controller reserves warehouse stock but every rule sits next to TypeORM calls. Refactor it to Clean Architecture:

```typescript
@Controller('reservations')
export class ReservationController {
  constructor(
    @InjectRepository(StockItem) private stock: Repository<StockItem>,
    @InjectRepository(Reservation) private reservations: Repository<Reservation>,
  ) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    if (!Number.isInteger(body.quantity) || body.quantity <= 0) {
      throw new BadRequestException('Quantity must be a positive integer');
    }
    const item = await this.stock.findOne({ where: { sku: body.sku } });
    if (!item) throw new NotFoundException('Unknown SKU');
    const available = item.onHand - item.reserved;
    if (available < body.quantity) {
      throw new ConflictException(`Only ${available} units available`);
    }
    item.reserved += body.quantity;
    await this.stock.save(item);
    return this.reservations.save({ sku: body.sku, quantity: body.quantity, createdAt: new Date() });
  }
}
```

### Architectural Flaws in Original Code
1. **Framework exceptions as business errors:** `BadRequestException` and `ConflictException` tie the reservation rules to NestJS.
2. **ORM entities as domain model:** the availability calculation mutates a TypeORM row in the controller.
3. **No atomic boundary:** the stock update and the reservation insert are two unrelated saves.

---

### Clean Architecture Refactoring

#### 1. Domain Layer (`src/domain/StockItem.ts`)
```typescript
import { Result } from '../shared/Result';

export type ReservationError =
  | { kind: 'InvalidQuantity' }
  | { kind: 'UnknownSku'; sku: string }
  | { kind: 'InsufficientStock'; available: number };

export class StockItem {
  constructor(
    readonly sku: string,
    readonly onHand: number,
    private reservedUnits: number,
  ) {}

  get reserved(): number {
    return this.reservedUnits;
  }

  get available(): number {
    return this.onHand - this.reservedUnits;
  }

  static checkQuantity(quantity: number): Result<number, ReservationError> {
    return Number.isInteger(quantity) && quantity > 0 ? Result.ok(quantity) : Result.fail({ kind: 'InvalidQuantity' });
  }

  reserve(quantity: number): Result<void, ReservationError> {
    const valid = StockItem.checkQuantity(quantity);
    if (!valid.success) return valid;
    if (this.available < quantity) {
      return Result.fail({ kind: 'InsufficientStock', available: this.available });
    }
    this.reservedUnits += quantity;
    return Result.ok(undefined);
  }
}
```

#### 2. Application Layer (`src/application/ReserveStock.ts`)
```typescript
import { Result } from '../shared/Result';
import { ReservationError, StockItem } from '../domain/StockItem';

export interface StockReservation {
  readonly sku: string;
  readonly quantity: number;
  readonly createdAt: Date;
}

export interface StockStore {
  findBySku(sku: string): Promise<StockItem | null>;
  /** Persists the item and the reservation in one transaction; returns the reservation id. */
  commit(item: StockItem, reservation: StockReservation): Promise<string>;
}

export class ReserveStock {
  constructor(private readonly store: StockStore, private readonly now: () => Date) {}

  async execute(sku: string, quantity: number): Promise<Result<StockReservation & { id: string }, ReservationError>> {
    const valid = StockItem.checkQuantity(quantity); // before the lookup, as in the original (400 before 404)
    if (!valid.success) return valid;
    const item = await this.store.findBySku(sku);
    if (!item) return Result.fail({ kind: 'UnknownSku', sku });

    const reserved = item.reserve(quantity);
    if (!reserved.success) return reserved;

    const reservation: StockReservation = { sku, quantity, createdAt: this.now() };
    const id = await this.store.commit(item, reservation);
    return Result.ok({ id, ...reservation });
  }
}
```

#### 3. Infrastructure Layer (`src/infrastructure/TypeOrmStockStore.ts`)
```typescript
import { DataSource } from 'typeorm';
import { StockItem } from '../domain/StockItem';
import { StockReservation, StockStore } from '../application/ReserveStock';
import { StockItemRow, ReservationRow } from './rows';

export class TypeOrmStockStore implements StockStore {
  constructor(private readonly db: DataSource) {}

  async findBySku(sku: string): Promise<StockItem | null> {
    const row = await this.db.getRepository(StockItemRow).findOne({ where: { sku } });
    return row ? new StockItem(row.sku, row.onHand, row.reserved) : null;
  }

  async commit(item: StockItem, reservation: StockReservation): Promise<string> {
    return this.db.transaction(async (tx) => {
      await tx.getRepository(StockItemRow).update({ sku: item.sku }, { reserved: item.reserved });
      const inserted = await tx.getRepository(ReservationRow).insert({ ...reservation });
      return String(inserted.identifiers[0].id);
    });
  }
}
```
The transaction makes the two writes atomic. Like the original, it does not lock the stock row: under concurrent reservations, `findBySku` should read with `lock: { mode: 'pessimistic_write' }` inside the same transaction.

#### 4. Presentation Layer (NestJS controller)
```typescript
import { BadRequestException, Body, ConflictException, Controller, NotFoundException, Post } from '@nestjs/common';
import { ReserveStock } from '../application/ReserveStock';

@Controller('reservations')
export class ReservationController {
  constructor(private readonly reserveStock: ReserveStock) {}

  @Post()
  async reserve(@Body() body: { sku: string; quantity: number }) {
    const result = await this.reserveStock.execute(body.sku, body.quantity);
    if (result.success) return result.data;
    const error = result.error;
    switch (error.kind) {
      case 'InvalidQuantity':
        throw new BadRequestException('Quantity must be a positive integer');
      case 'UnknownSku':
        throw new NotFoundException('Unknown SKU');
      case 'InsufficientStock':
        throw new ConflictException(`Only ${error.available} units available`);
    }
  }
}
```

NestJS exceptions now live only at the edge; the domain reports failures as typed values.

Critique this notification preferences service. Which SOLID principles does it break, and what would you change?

```typescript
import { PrismaClient } from '@prisma/client';
import sgMail from '@sendgrid/mail';
import webpush from 'web-push';

export class NotificationPreferences {
  private prisma = new PrismaClient();

  async notify(userId: string, event: 'comment' | 'mention' | 'digest', text: string) {
    const prefs = await this.prisma.preference.findUnique({ where: { userId } });
    const hour = new Date().getHours();
    const quiet = prefs?.quietStart !== undefined && hour >= prefs.quietStart && hour < prefs.quietEnd;

    if (prefs?.channels.includes('mail') && !(quiet && event !== 'digest')) {
      const user = await this.prisma.user.findUnique({ where: { id: userId } });
      await sgMail.send({ to: user!.address, from: 'noreply@app.io', subject: event, text });
    }

    if (prefs?.channels.includes('push') && !quiet && event !== 'digest') {
      const subs = await this.prisma.pushSubscription.findMany({ where: { userId } });
      for (const s of subs) await webpush.sendNotification(JSON.parse(s.json), text);
    }
  }
}
```

### SOLID Critique

#### Dependency Inversion Principle — the central problem
The high-level policy ("respect quiet hours, digests are always delivered by mail") is welded to three concrete libraries: `new PrismaClient()` on the field initialiser, `sgMail` and `webpush` as module imports. Consequences:
- The quiet-hours rule cannot be tested without a database and two network services.
- `new Date().getHours()` reads the **server's** time zone, so a user in Tokyo gets "quiet hours" based on Frankfurt time. Nothing can inject the clock or the user's zone, so this bug cannot even be reproduced in a test.

#### Single Responsibility Principle — violated
Three reasons to change share one method: the delivery policy (quiet hours, which events go where), the persistence of preferences and subscriptions, and the wire format of each channel. The policy is also duplicated with subtle differences: `!(quiet && event !== 'digest')` for mail and `!quiet && event !== 'digest'` for push. Someone changing quiet hours has to edit both expressions and keep them consistent.

#### Open/Closed Principle — violated
A third channel (SMS, Slack) means another `if` block in `notify()` with yet another copy of the rule.

#### Not a violation: Interface Segregation
The public surface is one method that callers actually need. Splitting it would not help anyone.

#### Also
`user!.address` asserts that the row exists; a deleted user throws an opaque `TypeError` in the middle of a loop.

---

### Refactoring

Put the decision in a pure function, and let each channel be an implementation of one small interface.

```typescript
export type Channel = 'mail' | 'push';
export type NotificationEvent = 'comment' | 'mention' | 'digest';

export interface Preferences {
  readonly channels: readonly Channel[];
  readonly quietHours?: { readonly start: number; readonly end: number };
  readonly timeZone: string;
}

/** Pure delivery policy: which channels should receive this event right now. */
export function channelsFor(prefs: Preferences, event: NotificationEvent, localHour: number): Channel[] {
  const q = prefs.quietHours;
  const quiet =
    q !== undefined &&
    (q.start <= q.end
      ? localHour >= q.start && localHour < q.end
      : localHour >= q.start || localHour < q.end); // overnight window, e.g. 22 -> 7
  if (event === 'digest') return prefs.channels.filter((c) => c === 'mail');
  return quiet ? [] : [...prefs.channels];
}
```

```typescript
export interface PreferenceStore {
  find(userId: string): Promise<Preferences | null>;
}

export interface ChannelSender {
  readonly channel: Channel;
  send(userId: string, event: NotificationEvent, text: string): Promise<void>;
}

export interface LocalClock {
  hourIn(timeZone: string): number;
}

export class NotificationService {
  private readonly senders: ReadonlyMap<Channel, ChannelSender>;

  constructor(
    private readonly prefs: PreferenceStore,
    senders: readonly ChannelSender[],
    private readonly clock: LocalClock,
  ) {
    this.senders = new Map(senders.map((s) => [s.channel, s]));
  }

  async notify(userId: string, event: NotificationEvent, text: string): Promise<Channel[]> {
    const prefs = await this.prefs.find(userId);
    if (!prefs) return [];
    const targets = channelsFor(prefs, event, this.clock.hourIn(prefs.timeZone));
    for (const channel of targets) {
      await this.senders.get(channel)?.send(userId, event, text);
    }
    return targets;
  }
}
```

Infrastructure provides `PrismaPreferenceStore`, `SendGridMailSender` (which looks up the address and returns early when the user is gone) and `WebPushSender`. Each is wired in the composition root.

What you gain:
- **One rule, one place.** The behaviour that was split between two boolean expressions is now `channelsFor`, testable with plain values: `channelsFor({ channels: ['mail','push'], quietHours: { start: 22, end: 7 }, timeZone: 'Asia/Tokyo' }, 'digest', 23)` returns `['mail']`.
- **The time-zone bug is fixable and testable**, because the hour comes from an injected `LocalClock` that knows the user's zone.
- **New channel = new `ChannelSender`.** `NotificationService` does not change.
- **A second bug surfaced and got fixed.** The original check `hour >= start && hour < end` is never true for an overnight window such as 22 → 7. Once the rule was a pure function the case was obvious, and `channelsFor` now handles windows that cross midnight.

