```typescript
// Domain/Entities/Subscription.ts
export class Subscription {
  private constructor(
    public readonly id: string,
    public readonly customerId: string,
    public readonly startDate: Date,
    public readonly endDate: Date,
    public readonly status: SubscriptionStatus,
    public readonly plan: string
  ) {
    this.validateInvariants();
  }

  static create(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    plan: string
  ): Subscription {
    return new Subscription(
      id,
      customerId,
      startDate,
      endDate,
      SubscriptionStatus.ACTIVE,
      plan
    );
  }

  static from(
    id: string,
    customerId: string,
    startDate: Date,
    endDate: Date,
    status: SubscriptionStatus,
    plan: string
  ): Subscription {
    return new Subscription(id, customerId, startDate, endDate, status, plan);
  }

  private validateInvariants(): void {
    if (this.startDate > this.endDate) {
      throw new InvalidSubscriptionError("Start date cannot be after end date");
    }

    if (this.isExpired()) {
      throw new InvalidSubscriptionError("Cannot create subscription with expired date range");
    }
  }

  isExpired(): boolean {
    return new Date() > this.endDate;
  }

  isActive(): boolean {
    return this.status === SubscriptionStatus.ACTIVE;
  }

  canCancel(): boolean {
    return !this.isExpired() && this.isActive();
  }

  cancel(): Subscription {
    if (!this.canCancel()) {
      throw new InvalidSubscriptionError("Cannot cancel expired or inactive subscription");
    }

    return Subscription.from(
      this.id,
      this.customerId,
      this.startDate,
      this.endDate,
      SubscriptionStatus.CANCELLED,
      this.plan
    );
  }
}

export enum SubscriptionStatus {
  ACTIVE = "ACTIVE",
  CANCELLED = "CANCELLED",
  EXPIRED = "EXPIRED"
}

// Domain/Errors/SubscriptionErrors.ts
export class InvalidSubscriptionError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvalidSubscriptionError";
  }
}

export class SubscriptionNotFoundError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SubscriptionNotFoundError";
  }
}

// Domain/UseCases/CancelSubscriptionUseCase.ts
import { Result, ok, error } from "../Result";
import { Subscription } from "../Entities/Subscription";
import { InvalidSubscriptionError, SubscriptionNotFoundError } from "../Errors/SubscriptionErrors";

export interface SubscriptionRepository {
  findById(id: string): Promise<Subscription | null>;
  save(subscription: Subscription): Promise<void>;
}

export class CancelSubscriptionUseCase {
  constructor(private readonly subscriptionRepository: SubscriptionRepository) {}

  async execute(subscriptionId: string): Promise<Result<Subscription, InvalidSubscriptionError | SubscriptionNotFoundError>> {
    try {
      const subscription = await this.subscriptionRepository.findById(subscriptionId);

      if (!subscription) {
        return error(new SubscriptionNotFoundError(`Subscription with id ${subscriptionId} not found`));
      }

      if (!subscription.canCancel()) {
        return error(new InvalidSubscriptionError("Cannot cancel already expired or inactive subscription"));
      }

      const cancelledSubscription = subscription.cancel();
      await this.subscriptionRepository.save(cancelledSubscription);

      return ok(cancelledSubscription);
    } catch (err) {
      if (err instanceof InvalidSubscriptionError) {
        return error(err);
      }
      throw err;
    }
  }
}

// Domain/Result.ts
export type Result<T, E extends Error> = {
  isSuccess: boolean;
  isError: boolean;
  value?: T;
  error?: E;
};

export function ok<T, E extends Error>(value: T): Result<T, E> {
  return {
    isSuccess: true,
    isError: false,
    value,
  };
}

export function error<T, E extends Error>(error: E): Result<T, E> {
  return {
    isSuccess: false,
    isError: true,
    error,
  };
}
```

This implementation follows Clean Architecture principles with:

1. **Pure Domain Entity**: `Subscription` contains all business logic and invariants without dependencies on external frameworks
2. **Invariant Validation**: 
   - Cannot cancel expired subscriptions
   - Cannot create subscriptions with invalid date ranges
   - Cannot cancel inactive subscriptions
3. **Result Pattern**: Use cases return `Result<T, E>` with typed errors
4. **Dependency Rule**: Domain layer doesn't depend on infrastructure (repositories, databases)
5. **Typed Errors**: Specific error types for different failure cases
6. **Immutability**: Subscription objects are immutable, with `cancel()` returning a new instance
7. **DDD Compliance**: Clear separation of concerns with entities, value objects, and use cases

The `CancelSubscriptionUseCase` validates that:
- The subscription exists
- The subscription is not already expired
- The subscription is currently active
- Returns appropriate

Critique this caching layer. Is subclassing the right call here, and which SOLID principles are affected?

```typescript
class ProductCatalog {
  constructor(protected http: HttpClient) {}

  async getProduct(id: string): Promise<Product | null> {
    const res = await this.http.get(`/products/${id}`);
    return res.status === 404 ? null : (res.body as Product);
  }

  async search(term: string): Promise<Product[]> {
    return (await this.http.get(`/products?q=${term}`)).body as Product[];
  }

  async updatePrice(id: string, cents: number): Promise<void> {
    await this.http.put(`/products/${id}/price`, { cents });
  }
}

class CachedProductCatalog extends ProductCatalog {
  private cache = new Map<string, Product | null>();

  async getProduct(id: string) {
    if (this.cache.has(id)) return this.cache.get(id)!;
    const product = await super.getProduct(id);
    this.cache.set(id, product);
    return product;
  }
}
```

### Critique

#### Liskov Substitution Principle — violated (stale reads)
`ProductCatalog` guarantees read-your-writes: after `updatePrice(id, 999)`, `getProduct(id)` returns the new price. `CachedProductCatalog` inherits `updatePrice` but not the knowledge that it should invalidate, so the subclass silently breaks that guarantee:

```text
await catalog.updatePrice('p1', 999);
await catalog.getProduct('p1'); // still the old price, forever
```

The cache never expires either, and it caches `null`, so a product created after the first miss stays "not found" for the life of the process. Code that worked with the base class misbehaves with the subclass, which is the textbook LSP failure.

#### Open/Closed — fragile, not a clean extension
Inheritance couples the cache to the base class's internals. If someone adds `getProducts(ids)` to `ProductCatalog`, the subclass inherits it **uncached** and nobody notices. Every change to the base class must be mirrored in the subclass.

#### Single Responsibility — violated
`CachedProductCatalog` is both "talk to the product API" (inherited) and "decide what to cache and for how long". You cannot reuse the caching policy for another catalogue, and you cannot pick a different store (Redis, LRU) without a new subclass.

#### Dependency Inversion — partly fine
`HttpClient` is injected, which is good. But consumers depend on the concrete class `ProductCatalog`, and the casts `res.body as Product` trust the remote payload without validation.

#### Not a violation: Interface Segregation
Three methods is a reasonable surface. Read-only callers could take a narrower `ProductReader`, but that is a refinement, not a defect.

---

### Refactoring: composition (decorator) instead of inheritance

```typescript
export interface Product {
  readonly id: string;
  readonly name: string;
  readonly priceCents: number;
}

export interface ProductCatalog {
  getProduct(id: string): Promise<Product | null>;
  search(term: string): Promise<Product[]>;
  updatePrice(id: string, cents: number): Promise<void>;
}

export interface Clock {
  now(): number;
}

interface Entry {
  readonly product: Product;
  readonly expiresAt: number;
}

export class CachingProductCatalog implements ProductCatalog {
  private readonly entries = new Map<string, Entry>();

  constructor(
    private readonly inner: ProductCatalog,
    private readonly clock: Clock,
    private readonly ttlMs: number,
  ) {}

  async getProduct(id: string): Promise<Product | null> {
    const hit = this.entries.get(id);
    if (hit && hit.expiresAt > this.clock.now()) return hit.product;

    const product = await this.inner.getProduct(id);
    if (product) this.entries.set(id, { product, expiresAt: this.clock.now() + this.ttlMs });
    else this.entries.delete(id); // never cache a miss
    return product;
  }

  search(term: string): Promise<Product[]> {
    return this.inner.search(term);
  }

  async updatePrice(id: string, cents: number): Promise<void> {
    await this.inner.updatePrice(id, cents);
    this.entries.delete(id);
  }
}
```

Why this is better:
- **Read-your-writes is restored** because the decorator owns `updatePrice` and invalidates on write.
- **The compiler protects you.** Adding `getProducts` to the `ProductCatalog` interface makes `CachingProductCatalog` fail to compile until you decide how to cache it. With inheritance it was silently inherited.
- **Expiry is testable** with a fake `Clock` instead of waiting real time.
- **The HTTP implementation (`HttpProductCatalog`) knows nothing about caching**, and the cache wraps any implementation, including an in-memory one in tests.

Wire it at the composition root: `new CachingProductCatalog(new HttpProductCatalog(http), systemClock, 60_000)`. Inside `HttpProductCatalog`, replace `as Product` with a type guard over `unknown` so a malformed response becomes an error rather than a lie in the cache.

Refactor this Lambda-style function where pricing, tax rules and DynamoDB access share one body:

```typescript
exports.handler = async (event) => {
  const cart = JSON.parse(event.body);
  const net = cart.lines.reduce((s, l) => s + l.unit * l.qty, 0);
  const tax = cart.country === 'DE' ? net * 0.19 : cart.country === 'FR' ? net * 0.2 : 0;
