Our triage SLA checker escalates bugs that sit untriaged too long. Please write AAA-style unit tests for it, including the exact SLA boundary for each priority.

```typescript
import { Result } from '../shared/Result';

export type Priority = 'P1' | 'P2' | 'P3';

export interface BugReport {
  id: string;
  priority: Priority;
  reportedAt: Date;
  triagedAt: Date | null;
  escalated: boolean;
}

export interface BugRepository {
  get(id: string): Promise<BugReport | null>;
  save(bug: BugReport): Promise<void>;
}

export interface OnCallPager {
  page(bugId: string, priority: Priority, hoursOverdue: number): Promise<void>;
}

export type SlaError = { kind: 'BugNotFound' } | { kind: 'AlreadyTriaged' } | { kind: 'AlreadyEscalated' };

const SLA_HOURS: Record<Priority, number> = { P1: 4, P2: 24, P3: 72 };

export class CheckTriageSla {
  constructor(
    private readonly bugs: BugRepository,
    private readonly pager: OnCallPager,
    private readonly now: () => Date,
  ) {}

  async execute(bugId: string): Promise<Result<{ breached: boolean }, SlaError>> {
    const bug = await this.bugs.get(bugId);
    if (!bug) return Result.fail({ kind: 'BugNotFound' });
    if (bug.triagedAt) return Result.fail({ kind: 'AlreadyTriaged' });
    if (bug.escalated) return Result.fail({ kind: 'AlreadyEscalated' });
    const waitedHours = (this.now().getTime() - bug.reportedAt.getTime()) / 3_600_000;
    const hoursOverdue = waitedHours - SLA_HOURS[bug.priority];
    if (hoursOverdue <= 0) return Result.ok({ breached: false });
    await this.pager.page(bug.id, bug.priority, hoursOverdue);
    await this.bugs.save({ ...bug, escalated: true });
    return Result.ok({ breached: true });
  }
}
```

The bug store is an in-memory fake and the pager a `vi.fn`, since paging is a fire-and-forget call whose arguments are what matters. `it.each` checks every priority at exactly its SLA (not breached) and one hour past it (breached, paged with 1 hour overdue).

```typescript
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { CheckTriageSla, BugReport, BugRepository, OnCallPager, Priority } from './CheckTriageSla';

class InMemoryBugs implements BugRepository {
  readonly bugs = new Map<string, BugReport>();
  async get(id: string): Promise<BugReport | null> {
    return this.bugs.get(id) ?? null;
  }
  async save(bug: BugReport): Promise<void> {
    this.bugs.set(bug.id, bug);
  }
}

const NOW = new Date('2024-12-02T12:00:00Z');
const hoursAgo = (h: number): Date => new Date(NOW.getTime() - h * 3_600_000);
const aBug = (overrides: Partial<BugReport> = {}): BugReport => ({
  id: 'BUG-1', priority: 'P2', reportedAt: hoursAgo(1), triagedAt: null, escalated: false, ...overrides,
});

describe('CheckTriageSla', () => {
  let bugs: InMemoryBugs;
  let page: ReturnType<typeof vi.fn<OnCallPager['page']>>;
  let useCase: CheckTriageSla;

  beforeEach(() => {
    bugs = new InMemoryBugs();
    page = vi.fn<OnCallPager['page']>().mockResolvedValue(undefined);
    useCase = new CheckTriageSla(bugs, { page }, () => NOW);
  });

  it.each<{ priority: Priority; waited: number; breached: boolean }>([
    { priority: 'P1', waited: 4, breached: false },
    { priority: 'P1', waited: 5, breached: true },
    { priority: 'P2', waited: 24, breached: false },
    { priority: 'P2', waited: 25, breached: true },
    { priority: 'P3', waited: 72, breached: false },
    { priority: 'P3', waited: 73, breached: true },
  ])('$priority untriaged for $waited h -> breached: $breached', async ({ priority, waited, breached }) => {
    // Arrange
    await bugs.save(aBug({ priority, reportedAt: hoursAgo(waited) }));

    // Act
    const result = await useCase.execute('BUG-1');

    // Assert
    expect(result).toEqual({ success: true, data: { breached } });
    expect(bugs.bugs.get('BUG-1')?.escalated).toBe(breached);
    if (breached) expect(page).toHaveBeenCalledWith('BUG-1', priority, 1);
    else expect(page).not.toHaveBeenCalled();
  });

  it('fails with BugNotFound', async () => {
    // Arrange: empty tracker

    // Act
    const result = await useCase.execute('BUG-404');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('BugNotFound');
  });

  it('fails with AlreadyTriaged even when the SLA was missed', async () => {
    // Arrange
    await bugs.save(aBug({ priority: 'P1', reportedAt: hoursAgo(10), triagedAt: hoursAgo(2) }));

    // Act
    const result = await useCase.execute('BUG-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AlreadyTriaged');
    expect(page).not.toHaveBeenCalled();
  });

  it('does not page twice for a bug that was already escalated', async () => {
    // Arrange
    await bugs.save(aBug({ priority: 'P1', reportedAt: hoursAgo(10), escalated: true }));

    // Act
    const result = await useCase.execute('BUG-1');

    // Assert
    expect(result.success).toBe(false);
    if (result.success) return;
    expect(result.error.kind).toBe('AlreadyEscalated');
    expect(page).not.toHaveBeenCalled();
  });
});
```
